import type { BankQuestion } from "@/lib/bank";

/** Reading Comprehension (English Language): 375 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eng-reading-comprehension-1","question":"Passage: Community libraries in small towns have quietly changed their role over the past decade. Once places where people simply borrowed books, many now run coding clubs for teenagers, help elderly residents fill in online forms and host weekly storytelling sessions for toddlers. Librarians say footfall has risen even as book loans have fallen, because people come for services they cannot easily find elsewhere. Some councils, however, still judge libraries only by the number of books issued, and cut their budgets when loan figures drop. Such decisions, critics argue, measure the wrong thing and punish libraries for adapting to what their communities actually need. Question: The passage is mainly about:","options":["why teenagers now prefer coding clubs to reading library books","how councils raise the money needed to keep public libraries open","how small-town libraries have taken on new roles yet are still judged by loans","the history of library storytelling sessions and the many toddlers who attend them"],"answer":2,"explanation":"The passage describes the new services libraries offer and criticises councils that still judge them only by book loans. Teenagers and storytelling are details, not the main idea.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-2", "question": "Passage: The new metro line was expected to ease traffic on the city's main avenue. In its first month, though, ridership was meagre: trains that could carry a thousand passengers ran with barely a hundred aboard. Officials blamed the lack of feeder buses, since most stations stood a long walk from residential areas. Once the transport department added shuttle services from nearby colonies, numbers began to climb, and by the sixth month the line was carrying close to its planned load during peak hours. The episode taught planners that a railway is only as useful as the ways people have of reaching it. Question: As used in the passage, the word 'meagre' most nearly means:", "options": ["steady", "excessive", "scanty", "irregular"], "answer": 2, "explanation": "Trains built for a thousand passengers carried barely a hundred, so 'meagre' means scanty or inadequate. 'Excessive' is its opposite.", "difficulty": "easy", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-3","question":"Passage: Mangrove forests grow where rivers meet the sea, in a zone that floods with salt water twice a day. Few trees can survive such conditions, but mangroves have evolved special adaptations. Some species push up breathing roots, called pneumatophores, through the mud so that they can take in air when the soil is waterlogged. Others filter out most of the salt at their roots or shed it through their leaves. Their tangled root systems slow down waves, trap sediment and shelter young fish. Villages behind dense mangrove belts have often suffered less damage from storm surges than those on bare coasts. Question: According to the passage, pneumatophores help mangroves to:","options":["trap sediment brought down by the rivers","take in air when the soil is waterlogged","shelter young fish from larger predators","filter out and shed excess salt through their leaves"],"answer":1,"explanation":"The passage says breathing roots called pneumatophores let mangroves take in air from waterlogged mud. Shedding salt is done by other species, and trapping sediment is a job of the tangled root system as a whole.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-4", "question": "Passage: It is fashionable to sneer at handwritten letters as a relic of slower times. Yet anyone who has found an old letter from a grandparent tucked inside a book knows the small jolt of recognising a familiar slant of the pen, the crossed-out word, the hurried postscript. An email can carry the same words, but it cannot carry the hand that wrote them. We need not abandon our keyboards; we might simply keep a few sheets of paper for the occasions that deserve them: a thank-you, a condolence, a birthday wish to someone far away. Question: The author's attitude towards handwritten letters is best described as:", "options": ["appreciative and gently persuasive", "neutral and purely factual", "nostalgic to the point of rejecting technology", "hostile and dismissive"], "answer": 0, "explanation": "The author values handwritten letters and mildly urges readers to write some. The author does not reject technology ('We need not abandon our keyboards'), so the last option overstates it.", "difficulty": "easy", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-5","question":"Passage: When a village in a drought-prone district faced repeated crop failures, its residents did not wait for a large dam. They built hundreds of small check dams and contour trenches, banned the cutting of trees on common land and agreed to grow crops that needed less water. Within a decade the water table had risen, wells that had been dry for years held water again, and families who had migrated to cities began to return. Visitors now come from across the country to study the village, though its leaders insist that the real secret was not engineering but agreement among neighbours. Question: It can be inferred that the village leaders believe its success depended most on:","options":["generous funding from the state and central governments","the construction of a single large dam upstream","collective decision-making by the residents","advanced engineering techniques brought in by experts"],"answer":2,"explanation":"The leaders say the secret was 'not engineering but agreement among neighbours', which points to collective decisions. The passage says the village did not wait for a large dam and never mentions government funding.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-6", "question": "Passage: Many people assume that the colour of an egg's shell tells us something about its nutrition. Brown eggs often cost more in shops, and buyers tend to think they are healthier or more natural. In fact, shell colour depends almost entirely on the breed of the hen: hens with white feathers and white ear-lobes usually lay white eggs, while many breeds with red or brown feathers lay brown ones. What the hen eats and how it is raised affect the yolk far more than its breed does. A brown egg and a white egg from hens on the same diet are, for practical purposes, nutritionally the same. Question: The primary purpose of the passage is to:", "options": ["explain how hens are raised on farms", "compare the prices of eggs in different shops", "correct a common misconception about eggs", "advise buyers to prefer white eggs"], "answer": 2, "explanation": "The passage sets up a popular belief (brown eggs are healthier) and shows it is mistaken. It recommends neither colour, so 'advise buyers to prefer white eggs' is wrong.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-7", "question": "Passage: Honeybees tell one another where food is through a movement known as the waggle dance. A forager returning to the hive runs in a straight line while shaking its abdomen, then loops back and repeats the run. The angle of the straight run relative to the vertical comb shows the direction of the food relative to the sun, and the length of the waggle run shows distance: the longer the run, the farther the flowers. Because the sun moves across the sky, bees adjust the angle of their dance through the day, so a dance performed at noon for the same flowers differs from one performed in the morning. Question: Which of the following is NOT supported by the passage?", "options": ["Bees signal the quality of the nectar by the speed of their loops", "Bees use the position of the sun as a reference for direction", "A dance for the same flowers changes its angle during the day", "The length of the waggle run tells other bees how far away the food is"], "answer": 0, "explanation": "The passage links the angle to direction and the length of the run to distance, and says the angle shifts as the sun moves. It says nothing about nectar quality or the speed of the loops.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-8","question":"Passage: The committee's report was candid about the failures of the flood-warning system. It admitted that sirens in three districts had not sounded, that text alerts had reached residents hours late, and that officials had ignored early readings from upstream gauges. Rather than blaming individuals, the report traced these lapses to a culture in which nobody owned the system from end to end. Its recommendations were modest in cost but sweeping in scope: a single agency to run warnings, regular drills, and publication of every gauge reading in real time, so that citizens could see for themselves when a river was rising. Question: In the passage, 'sweeping' most nearly means:","options":["wide-ranging","clearing away","victorious","hurried and careless"],"answer":0,"explanation":"'Modest in cost but sweeping in scope' contrasts low cost with broad reach, so 'sweeping' means wide-ranging. 'Cleaning' is the literal sense and does not fit.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-9", "question": "Passage: For centuries sailors navigated by the stars, but finding longitude at sea remained dangerously difficult. Latitude could be judged from the height of the sun at noon; longitude required knowing the exact time at the home port while at sea, and the pendulum clocks of the day could not keep time on a rolling ship. In the eighteenth century a self-taught English carpenter, John Harrison, spent decades building a series of marine timekeepers. His fourth, built like a large pocket watch, lost only a few seconds on a voyage to the Caribbean. Accurate chronometers soon made long voyages far safer. Question: Which is the most suitable title for the passage?", "options": ["The Invention of the Pendulum Clock", "How Sailors Read the Stars", "Solving the Longitude Problem", "A Voyage to the Caribbean"], "answer": 2, "explanation": "The whole passage is about the difficulty of finding longitude and how Harrison's timekeepers solved it. Star navigation, pendulum clocks and the voyage are only details.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-10","question":"Passage: A city once tried to reduce its population of cobras by paying a reward for every dead snake. At first the scheme seemed to work: thousands of skins were handed in. Then officials noticed that the number of rewards kept rising while sightings in the streets did not fall. Enterprising residents had begun breeding cobras at home to collect the money. When the scheme was scrapped, the breeders released their now worthless snakes, and the city ended up with more cobras than before. Economists still use the story to warn that a badly designed incentive can produce the very problem it was meant to solve. Question: Economists use the story to illustrate that:","options":["breeding animals at home is a reliable way for residents to earn money","governments should never offer cash rewards to solve public problems","snakes are especially hard to control in crowded cities","an incentive can backfire when people find ways to exploit it"],"answer":3,"explanation":"The passage ends by warning that a badly designed incentive can produce the problem it was meant to solve. It does not say rewards should never be offered; 'never' goes beyond the text.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-11", "question": "Passage: The minister announced, with considerable fanfare, that the new highway would be completed 'well ahead of schedule'. This was the fourth such announcement in six years. The first had promised completion by 2019; the second, by 2021; the third, after a 'thorough review', by 2023. Each time the ribbon was ready, the scissors sharpened and the press invited. Commuters who have spent those years inching past half-built flyovers may be forgiven for not reaching for their party hats just yet. Question: The tone of the passage is:", "options": ["celebratory", "apologetic", "indifferent", "sarcastic"], "answer": 3, "explanation": "By listing the broken deadlines and mocking the ready ribbon and 'party hats', the writer ridicules the announcement, so the tone is sarcastic. Nothing in it is truly celebratory.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-12","question":"Passage: Sleep researchers have found that teenagers' internal body clocks shift later during puberty: most adolescents do not feel sleepy until around eleven at night and naturally wake after eight. Schools that begin classes at seven-thirty therefore make students wake in the middle of their biological night. Several districts that moved their start time to nine reported that students slept longer, attended more regularly and did slightly better in morning tests. Opponents point to the cost of rescheduling buses and the disruption to parents' working hours, but supporters argue that these are problems of convenience, while lost sleep is a problem of health. Question: According to the passage, early school start times harm teenagers because:","options":["school buses often arrive late, cutting into the first lessons","morning tests are harder for students than afternoon tests","they force students to wake before their body clocks are ready","teenagers spend their evenings on screens and so sleep too little"],"answer":2,"explanation":"The passage says puberty shifts the body clock later, so a 7:30 start makes students wake in their biological night. Screens and late buses are never mentioned.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-13","question":"Passage: Ancient Roman concrete has outlasted many modern structures, and for years engineers puzzled over why. Recent analysis of samples from a Roman tomb suggests part of the answer: the builders mixed in quicklime, which left small white lumps of lime scattered through the material. When cracks later formed and water seeped in, it dissolved some of this lime, which then recrystallised as calcium carbonate and sealed the crack. Modern concrete, made to a smooth and uniform mix, lacks these reservoirs. Researchers are now testing whether adding lime lumps on purpose could give today's concrete a similar ability to heal itself. Question: Which of the following can be inferred from the passage?","options":["Modern concrete cracks far more often than Roman concrete did in its time","Water always weakens concrete structures, whatever lime they contain","Roman builders understood the chemistry that made their concrete self-healing","Modern concrete's uniform mix may lack what lets Roman concrete heal itself"],"answer":3,"explanation":"The lime lumps that heal cracks are missing from smooth, uniform modern mixes, so uniformity removes the self-healing reservoirs. The passage never says the Romans understood the chemistry or that modern concrete cracks more often, and here water actually helps the repair.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-14", "question": "Passage: Translation is often described as the faithful transfer of meaning from one language to another, as if meaning were a parcel that could be lifted out of one box and placed unchanged into another. Anyone who has tried to translate a joke knows better. Puns depend on sounds that the second language does not share; idioms carry histories that cannot be explained without killing them. A good translator therefore makes choices, sacrificing a pun here to keep a rhythm there, and every such choice is an act of interpretation. To read a translation is to read two authors at once. Question: The author would most likely agree that:", "options": ["a perfect translation keeps every element of the original", "jokes should never be translated", "translators should explain every idiom in a footnote", "every translation reflects the translator's own judgement"], "answer": 3, "explanation": "The author calls every choice 'an act of interpretation' and says a translation has 'two authors', so each translation carries the translator's judgement. The author says idioms die when explained, so footnoting every idiom goes against the passage.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-15","question":"Passage: Supporters of plastic bag bans often cite the image of a turtle tangled in a carrier bag. The image is real, but the economics are more complicated. A cotton tote must be reused many dozens of times before its overall environmental cost, counting the water and energy used to grow and process the cotton, falls below that of a thin plastic bag used once. Many shoppers, it turns out, collect totes faster than they wear them out. None of this means the bans are wrong; it means that their benefit depends less on the bag we carry than on how long we keep carrying it. Question: The final sentence of the passage serves to:","options":["limit the criticism and name what the bans' benefit depends on","prove that cotton totes are always worse for the environment than plastic","introduce a new argument about the harm plastic does to wildlife","reject plastic bag bans altogether as a costly mistake"],"answer":0,"explanation":"After raising problems with totes, the author says the bans are not wrong and that their value depends on reusing bags for a long time. This limits the criticism rather than rejecting the bans.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-16","question":"Passage: The old merchant was not a man given to sentiment. He kept careful accounts, paid his workers on the exact day and expected the same exactness in return. Yet when a fire gutted the shop of his chief rival, he was the first to arrive with carts of timber and cloth, and he refused all talk of repayment. Asked why, he said only that a bazaar with one shop is not a bazaar but a monopoly, and that monopolies make men lazy. His neighbours could never decide whether this was generosity dressed as calculation, or calculation dressed as generosity. Question: The neighbours' uncertainty arises because the merchant's action:","options":["could be explained either by kindness or by self-interest","ruined his own business by giving away timber and cloth","broke the unwritten rules that govern trade in the bazaar","went against his habit of keeping exact accounts"],"answer":0,"explanation":"Helping a rival looks generous, but his reason (competition keeps him from getting lazy) sounds calculating, so the act fits both motives. Nothing suggests it broke rules or ruined him.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-17","question":"Passage: A survey found that people who drink green tea daily report fewer colds than those who do not. A tea company has used the finding in advertisements claiming that green tea 'boosts immunity'. But the survey also showed that daily green-tea drinkers were more likely to exercise, less likely to smoke and, on average, slept an hour longer each night. Any of these habits could explain the difference. Until a trial compares similar people who are randomly assigned to drink or not drink tea, the advertisement claims more than the evidence allows. Question: The author's main criticism of the advertisement is that it:","options":["misreports the survey's numbers to make the effect look larger","relies on a survey too small to give reliable results","ignores the possible side effects of drinking green tea daily","treats a correlation as proof of cause, ignoring other habits"],"answer":3,"explanation":"The author says exercise, not smoking or longer sleep could explain the fewer colds, so the advert jumps from correlation to cause. Survey size and side effects are never raised.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-18","question":"Passage: Every spring the hillside above our town turns a pale violet, and every spring the newspapers send photographers. The flowers belong to an invasive shrub that escaped from an old botanical garden and is steadily choking the native grasses that once fed cattle. Graziers have watched their pastures shrink by a third. The photographs, of course, show none of this: only couples posing in a lavender haze. It is hard to blame the visitors. Beauty is persuasive. But a landscape can be lovely and dying at the same time, and the second fact deserves at least as much attention as the first. Question: The author's attitude towards the newspaper coverage is best described as:","options":["mildly critical","bitterly hostile","enthusiastic","indifferent"],"answer":0,"explanation":"The author notes that the photographs leave out the damage and asks that it get equal attention, while saying it is 'hard to blame the visitors'. That is mild criticism, not fury.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-19","question":"Passage: The Indian Ocean Dipole is a difference in sea-surface temperature between the western and eastern parts of the Indian Ocean. In a positive phase, waters near East Africa are warmer than usual while those near Indonesia are cooler; in a negative phase, the pattern reverses. A positive dipole tends to bring heavier rain to East Africa and the Indian subcontinent and drier conditions to Australia. Forecasters watch it closely alongside El Niño in the Pacific, because a positive dipole can partly offset the drying effect that El Niño usually has on the Indian monsoon. Question: The passage answers which of the following questions?","options":["In which year was the strongest positive dipole of the century recorded?","What causes the dipole to switch from one phase to the other?","How can a positive dipole affect the monsoon in an El Niño year?","How often does a positive phase occur in a typical decade?"],"answer":2,"explanation":"The last sentence says a positive dipole can partly offset El Niño's drying effect on the monsoon. The causes, frequency and record years of the dipole are not discussed.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-20","question":"Passage: Meera had rehearsed the speech for a week. She knew where to pause, where to look up, where the audience would laugh. When she reached the stage and the microphone shrieked, she laughed first, before anyone else could, and said, 'Well, at least it's awake.' The hall relaxed. Afterwards her teacher told her the speech had been good but the recovery had been better. Meera, who had expected praise for the lines she had polished so carefully, was not sure whether to feel flattered or slightly cheated. Question: Meera's mixed feelings at the end arise because:","options":["the microphone failure spoiled the speech she had rehearsed for a whole week","she was praised more for an unplanned moment than for her preparation","her teacher criticised the speech she had polished so carefully","the audience did not laugh at the jokes she had planned"],"answer":1,"explanation":"The teacher valued her quick recovery above the speech she had rehearsed for a week, so she felt both flattered and cheated. The teacher actually called the speech good.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-21", "question": "Passage: The new manager's first weeks were marked by a studied informality. She ate in the canteen, learned the names of the cleaning staff and left her door open. Some employees found this refreshing; others, more cynical, noticed that every conversation seemed to end with a question about who was doing what, and how well. By the end of the quarter two departments had been merged and three senior posts abolished. Those who had called her approachable now called her shrewd, though it is possible she was both. Question: The phrase 'studied informality' suggests an informality that was:", "options": ["academic in nature", "deliberate and calculated", "learned from management books", "careless and accidental"], "answer": 1, "explanation": "'Studied' here means carefully planned. Her friendly manner also helped her gather information before restructuring. Reading it as 'learned from books' or 'academic' confuses it with studying.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-22","question":"Passage: Our city's planners propose to widen the main road from four lanes to six to cut congestion. Experience elsewhere should give them pause. When roads are widened, journeys become quicker for a while, and that very speed attracts drivers who previously took buses, travelled at other hours or did not make the trip at all. Within a few years traffic usually returns to its old level, now spread across six lanes instead of four. Transport economists call this induced demand. If the aim is to move more people, the money might do more good in buses and safe footpaths. Question: The author's argument assumes that:","options":["what happened in other cities will also happen in this city","congestion on the main road cannot be reduced by any measure","buses cost less to run than footpaths cost to build and maintain","nobody in the city now travels to work by bus"],"answer":0,"explanation":"The author predicts the city's result from 'experience elsewhere', which works only if this city behaves like those cities. That link is never stated, so it is the hidden assumption. The author suggests buses as a fix, so 'no measure works' contradicts the passage.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-23","question":"Passage: For most of the twentieth century, scientists believed that adult brains could not grow new neurons. Studies in birds first challenged this view: canaries were found to produce new brain cells each season as they learned new songs. Later research found new neurons in the hippocampus of adult rodents and, more controversially, of humans. How much new growth happens in adult humans is still debated, with some laboratories reporting it into old age and others finding little after childhood. What is no longer seriously argued is that the adult brain is fixed; even where new cells are scarce, existing connections are constantly rewired. Question: Which statement best reflects the current position described in the passage?","options":["Humans keep growing new neurons throughout life, just as canaries do each season","The adult brain cannot form new connections once childhood is over","Growth of new neurons in adults was first discovered in human brains","Adult neuron growth is disputed, but the brain's capacity to change is accepted"],"answer":3,"explanation":"The passage says the amount of adult neuron growth is still debated, but nobody now argues that the brain is fixed. The canary option treats a disputed point as settled, and the first discoveries were in birds.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-24","question":"Passage: A shopkeeper who sells umbrellas does well in the rainy season and badly in summer; one who sells sunglasses has the opposite problem. If the two merge their shops, their combined income becomes far steadier, even though neither has sold an extra item. This, in miniature, is the logic of diversification. An investor who holds assets that tend to rise and fall at different times can reduce the swings in the value of the whole collection without necessarily lowering the average return. The trick lies not in owning many things, but in owning things that do not all move together. Question: The umbrella and sunglasses example is used to show that:","options":["owning a large number of different assets is by itself enough to guarantee safety","seasonal businesses are too risky and should be avoided by investors","merging two shops always increases the total number of items sold","combining businesses that do well at different times steadies total income"],"answer":3,"explanation":"The merged shop has steadier income because the two businesses do well in different seasons. The passage says no extra items are sold and that owning many things is not the trick.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-25", "question": "Passage: Bioluminescence, the production of light by living things, is rare on land but common in the deep sea, where sunlight never reaches. The light is produced when an enzyme, luciferase, acts on a molecule called luciferin in the presence of oxygen. Deep-sea creatures use it in many ways: anglerfish dangle a glowing lure to attract prey, some squid release clouds of glowing ink to confuse predators, and many small shrimps light up their undersides to match the faint glow from above, so that a hunter looking up sees no silhouette. On land, fireflies use their flashes mainly to find mates. Question: How many of the following statements are supported by the passage? I. Luciferase is the molecule that is acted upon to produce light. II. Some animals use light to hide rather than to be seen. III. Fireflies use light chiefly to attract prey. IV. Oxygen is needed for the light-producing reaction.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II is supported (shrimps light their undersides so they cast no silhouette) and IV is supported (the reaction needs oxygen). I swaps the roles, because luciferase is the enzyme and luciferin is the molecule acted upon. III is wrong, because fireflies flash mainly to find mates. So only two are supported.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-26","question":"Passage: A software firm that switched to a four-day week, without cutting pay, reports that output per employee did not fall and that staff took fewer sick days. Its chief executive now urges all companies to follow. Critics point out that the firm made the change after a year of strong profits and that its employees, mostly young programmers, work on tasks that can be finished anywhere and at any hour. A hospital, a factory line or a bus depot, they say, cannot simply close for a day. Question: Which of the following, if true, would most strengthen the critics' position?","options":["Many programmers already prefer to work from home at hours they choose","The firm's employees reported higher job satisfaction after the change","The firm's profits rose even further in the year after the switch to four days","Hospitals trying shorter weeks had to hire many more staff to keep wards open"],"answer":3,"explanation":"The critics say the firm's result will not carry over to round-the-clock services. Evidence that hospitals needed far more staff to make it work supports exactly that. Higher satisfaction and rising profits back the chief executive instead.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-27", "question": "Passage: Of the roughly seven thousand languages spoken today, linguists estimate that around forty per cent are endangered, many with fewer than a thousand speakers. A language rarely dies because its speakers are forbidden to use it; more often, parents decide that their children will get better jobs in a dominant language and stop speaking the old one at home. Within two generations, the grandparents may be the last fluent speakers. Revival is difficult but not impossible: Hebrew, once used mainly in prayer and scholarship, became the everyday language of millions in the twentieth century, and efforts in Wales and New Zealand have increased the number of young speakers of Welsh and Maori. Question: Each of the following can be inferred from the passage EXCEPT:", "options": ["Economic considerations can lead families to give up their own language", "Most endangered languages are dying because governments have banned them", "A language that has stopped being used in daily life can regain everyday use", "Passing a language on at home is crucial to its survival"], "answer": 1, "explanation": "The passage says a language 'rarely' dies because it is forbidden; it usually fades when parents stop using it for economic reasons. The other three follow from the text, and the Hebrew example shows a language returning to daily use.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-28","question":"Passage: Critics dismissed her first exhibition as the work of a hobbyist; her bold, flat colours seemed childish beside the subtle shading then in fashion. She did not argue. For twenty years she painted in a rented room above a tailor's shop, selling just enough to pay the rent. When a younger generation rediscovered her canvases, the same newspapers that had mocked her hailed her as a pioneer. Asked in an interview whether she felt vindicated, she replied that she had been too busy painting to keep score. Question: Her reply in the interview suggests that she was:","options":["doubtful, looking back, about the merit of her early flat style","quietly vindicated and eager to say so to the newspapers","resentful of the critics but too proud to show it openly","unconcerned with critics' verdicts and absorbed in her work"],"answer":3,"explanation":"'Too busy painting to keep score' shows she paid little attention to praise or blame and simply kept working, as she had for twenty years without arguing. Nothing suggests resentment, eagerness for credit or doubt about her style.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-29","question":"Passage: Antibiotics kill bacteria or stop them from multiplying, but they do not work against viruses. When a patient takes an antibiotic, the drug kills the susceptible bacteria first; any cells that happen to carry a resistance gene survive and multiply. Bacteria can also pass resistance genes to one another, even across species, on small rings of DNA called plasmids. Each unnecessary prescription, for instance for a common cold, therefore gives resistant strains an opportunity without offering any benefit. Large amounts of antibiotics are also given to farm animals to make them grow faster, adding further pressure. Question: How many of the following can be inferred from the passage? I. An antibiotic prescribed for a common cold brings no benefit because the cold is caused by a virus. II. Resistance genes can pass only from parent bacteria to their offspring. III. Antibiotic use on farms adds to the selection of resistant bacteria. IV. Resistant bacteria survive treatment because exposure to the drug produces the resistance gene in them.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I follows from 'no benefit' for a cold with 'do not work against viruses', and III from the farm sentence. II is contradicted by plasmids passing genes between bacteria, and IV by cells that 'happen to carry' the gene. So two can be inferred.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-30","question":"Passage: Some historians argue that the printing press caused the Protestant Reformation. The claim has an obvious appeal: Luther's pamphlets were printed in hundreds of thousands of copies and spread across Germany within weeks. But earlier reformers, such as Jan Hus a century before, had attracted large followings without print, and the press also served the Catholic side, which printed its own replies in great numbers. A better way to put it may be that print changed the speed and scale of the quarrel, while the grievances that fuelled it had been building for generations. Question: Which best describes the organisation of the passage?","options":["The events of the Reformation are narrated in the order they occurred","A claim is challenged with counter-evidence and then restated in a weaker form","A theory is stated and then fully confirmed with historical examples","The views of two rival historians are compared in turn, and both are rejected"],"answer":1,"explanation":"The passage states the claim that print caused the Reformation, offers Hus and Catholic printing as objections, and ends with a narrower claim (print changed the speed and scale). It does not simply confirm or reject the theory.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-31", "question": "Passage: The company won its long legal battle against the small start-up that had copied its design. The court awarded damages, and the company's lawyers celebrated. But the case had dragged on for six years, cost several times the damages awarded and produced a stream of headlines portraying the company as a bully crushing a pair of young inventors. Its sales among younger buyers fell steadily over the same period. Inside the boardroom, at least one director described the outcome as a Pyrrhic victory. Question: By calling it a 'Pyrrhic victory', the director meant that the win:", "options": ["was celebrated before the verdict was announced", "was obtained by unfair means", "was likely to be overturned on appeal", "cost so much that it was hardly worth winning"], "answer": 3, "explanation": "A Pyrrhic victory is one gained at such a cost that it is nearly a defeat. Here the legal costs ran several times the damages and the company's image and sales suffered. Nothing suggests unfair means or an appeal.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-32", "question": "Passage: The government plans to raise the tax on sugary drinks, arguing that higher prices will reduce consumption and so lower rates of diabetes. Drink makers reply that consumers will simply switch to cheaper brands or to sweets, leaving their sugar intake unchanged. Evidence from countries that introduced similar taxes is mixed: purchases of taxed drinks fell noticeably, but few studies have yet tracked whether total sugar intake or diabetes rates changed. Health experts add that diabetes has several causes, including inactivity and family history. Question: Which of the following is implicit in the government's argument? I. Demand for sugary drinks responds to price. II. Sugary drinks are the only cause of diabetes.", "options": ["Only I", "Only II", "Both I and II", "Neither I nor II"], "answer": 0, "explanation": "The government expects higher prices to cut consumption, which assumes demand responds to price (I). Its argument needs sugary drinks to be one cause of diabetes, not the only one, so II is too extreme.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-33","question":"Passage: In 2010 a town of 50,000 people had 10,000 registered cars. By 2020 the population had grown to 60,000 and the number of cars to 18,000. The council's report celebrates the fact that the share of residents using the bus rose from 20 per cent to 22 per cent over the same decade. A local newspaper, however, notes that roads are far more crowded than before and that the bus network has not added a single route in ten years. Both sides claim the figures prove their point. Question: Which conclusion is best supported by the figures in the passage?","options":["Cars per person rose by half, outpacing the small rise in the bus share","The number of bus users fell during the decade even as its share went up","The town's population grew faster than its number of registered cars","Cars per person rose by 80 per cent, far outpacing the bus share"],"answer":0,"explanation":"Cars per 1,000 people went from 10,000 ÷ 50 = 200 to 18,000 ÷ 60 = 300, a 50% rise. Bus users went from 10,000 to 13,200, so they rose rather than fell. 80% is the rise in the total number of cars, not cars per person, and population grew only 20% against 80% for cars.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-34", "question": "Passage: I grew up in a town that the new expressway has turned into a suburb of the city. My mother can reach the hospital in twenty minutes instead of two hours, and my nephews can take jobs that did not exist when I left. I am glad of all this. I am also aware that the mango orchard where we spent our summers is a warehouse now, that the river ghat is fenced off, and that the bazaar sells exactly what every other bazaar sells. When people ask whether the expressway has been good for the town, I find I cannot give them a single answer. Question: The author's attitude towards the change in the town is best described as:", "options": ["nostalgic", "resentful", "ambivalent", "apathetic"], "answer": 2, "explanation": "The author is glad of faster hospital trips and new jobs but regrets the lost orchard and ghat, and cannot give 'a single answer'. That mix is ambivalence. 'Nostalgic' covers only the regret and leaves out the gladness.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-35","question":"Passage: Archaeologists digging at a coastal site found many fish bones in the lowest layers, dated to about 6000 BCE, and almost none in the layers above, dated to about 5000 BCE, where the bones of goats and cattle dominate. One team concludes that the inhabitants gave up fishing because they took up herding. Another suggests that the sea retreated during that thousand years, leaving the settlement several kilometres inland and making fishing impractical, after which the people turned to herding. Question: Which finding would most support the second team's view over the first?","options":["Herding was already practised in nearby inland villages by 5500 BCE","Fishing hooks of bone were found among the fish bones in the lowest layers","Goat bones in the upper layers show clear signs of butchery with stone tools","Sediment cores show the coast moved kilometres seaward by 5000 BCE"],"answer":3,"explanation":"The second team's view rests on the sea having retreated, and sediment cores showing the coastline moving away confirm that directly. Butchered goats and fishing hooks fit both views, and nearby herding, if anything, supports the first team.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-36","question":"Passage: Cities are often hotter than the countryside around them, sometimes by several degrees at night. Dark roofs and roads absorb sunlight during the day and release the heat after dark; tall buildings trap warm air and block breezes; and air conditioners pump heat from inside buildings into the streets. The effect is not merely uncomfortable. During heat waves it raises death rates among the elderly and the poor, who are least able to escape it. Remedies are known and often cheap: painting roofs white, planting trees along streets and keeping open water bodies can all lower local temperatures. Question: Which of the following best summarises the passage?","options":["Cities are hotter than villages only during the day, when roofs absorb sunlight","How cities are built and run traps heat that harms the vulnerable; cheap fixes exist","Planting trees is the only reliable way to cool a city during a heat wave","Air conditioners are the main cause of high city temperatures and should be limited"],"answer":1,"explanation":"The summary has to cover the causes, the danger to the vulnerable and the cheap remedies. The other options overstate one cause or one remedy, or contradict the passage, which stresses that cities stay hotter at night.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-37", "question": "Passage: The judge was known for her temper, not in the sense of anger, but of balance. She could temper a harsh law with a merciful sentence, yet she never let sympathy blunt the edge of a ruling that the facts demanded. Lawyers who appeared before her learned to prepare thoroughly, because she had little patience for arguments that leaned on emotion rather than evidence. When she retired, colleagues remembered her less for any single judgment than for the steadiness she brought to every one. Question: In the passage, 'temper' in its first use and 'temper' in its second use mean, respectively:", "options": ["mood; strengthen", "composure; provoke", "composure; soften", "anger; harden"], "answer": 2, "explanation": "The first 'temper' is a noun meaning calm balance or composure (the passage rules out anger). The second is a verb meaning to soften or moderate, as in softening a harsh law with mercy.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-38","question":"Passage: The Great Barrier Reef stretches for more than 2,300 kilometres off the coast of Queensland, Australia, and is made up of about 3,000 individual reefs. Its corals live in partnership with tiny algae that supply them with food through photosynthesis and give them their colours. When the water stays unusually warm for several weeks, the corals expel the algae and turn white, an event called bleaching. Bleached corals are not dead and can recover if temperatures fall soon enough; prolonged heat, however, starves them. Mass bleaching struck the reef in 1998, 2002, 2016 and 2017, among other years. Question: Which question CANNOT be answered from the passage?","options":["Can bleached corals ever recover from the event?","Why do corals turn white when they bleach in warm water?","How do the algae benefit the corals that host them?","What percentage of the reef's coral died in 2016?"],"answer":3,"explanation":"The passage gives bleaching years but no death figures. It does explain whitening (the coloured algae are expelled), recovery (possible if the water cools soon) and the benefit (food from photosynthesis).","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-39","question":"Passage: Many early European maps of distant lands filled their unknown interiors with drawings of animals and invented mountain ranges. Later mapmakers, more cautious, began to leave such regions blank. A blank space looked like a confession of ignorance, and some patrons disliked it. Yet it had a practical virtue: a traveller who saw a white patch knew he was entering country no outsider had charted, while one who trusted an invented mountain range might plan a route around obstacles that did not exist, or march confidently towards a lake that was not there. Question: Which of the following is the closest modern parallel to the virtue the passage praises?","options":["A forecast that gives a percentage chance of rain instead of promising rain","A textbook that adds more pictures and diagrams to each chapter","A satellite image whose cloudy patches are quietly filled in with guessed terrain","A map app that shows more restaurants and shops in each area"],"answer":0,"explanation":"The blank map was useful because it honestly showed the limits of knowledge. A forecast that states its uncertainty does the same. A satellite image that fills gaps with guesses repeats the invented-mountain error.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-40","question":"Passage: Gardeners in dry regions are often advised to water deeply but rarely, rather than a little every day. Frequent shallow watering keeps only the top few centimetres of soil moist, so roots stay near the surface, where the soil dries fastest in hot weather. Deep, infrequent watering sends moisture far down, and roots follow it. A plant with deep roots can survive a week of heat that would wilt its shallow-rooted neighbour, even though both received the same total amount of water. Question: Which situation follows the same principle as the one described?","options":["A student revises the same chapter for five minutes every day to keep it fresh","A coach sets occasional long, hard sessions rather than many easy ones","A farmer doubles the total water he gives his crop in order to raise the yield","A city adds more taps so that residents need not walk far to fetch water"],"answer":1,"explanation":"The principle is that the same total input, given in fewer, deeper doses, builds resilience for hard times, just as deep roots survive a heat wave. Long, demanding training sessions build endurance the same way. Doubling the total water changes the amount rather than how it is given.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-41","question":"Passage: For centuries, the stepwells of western India were far more than places to draw water. Built with long flights of stone steps leading down to the water table, they allowed people to reach water even when the level dropped sharply in summer. Because the lower chambers stayed several degrees cooler than the surface, travellers rested there during the hottest hours, and women gathered to talk while filling their pots. Many stepwells were richly carved with gods, dancers and floral patterns, turning a practical structure into a work of art. When piped water arrived in the twentieth century, most stepwells were abandoned and filled with rubbish. Today, a few have been cleaned and restored, and they attract tourists and local families alike, reminding visitors that engineering and beauty once went hand in hand. Question: The passage is mainly about:","options":["the many roles stepwells played and how they fell into neglect","the techniques craftsmen used to carve stone sculptures of gods","why piped water is safer and better than water drawn from wells","the growth of the tourist industry in western India"],"answer":0,"explanation":"The passage describes the practical, social and artistic roles of stepwells, their abandonment and partial revival. Carving and tourism are only details.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-42","question":"Passage: Street vendors are often treated as a nuisance by city authorities. They are accused of blocking pavements, creating litter and avoiding taxes. Yet millions of people depend on them every day for cheap meals, vegetables and household goods, and the vendors themselves are frequently migrants with no other source of income. A law passed in India in 2014 tried to strike a balance by asking cities to survey vendors, issue certificates and set aside vending zones. Where it has been implemented sincerely, vendors no longer live in fear of sudden evictions, and pavements have become more orderly. Where it has been ignored, the old cycle of raids, bribes and returns continues. The problem, it seems, lies less in the law than in the will to apply it. Question: According to the passage, where the law has been ignored:","options":["pavements have become more orderly and easier to walk on","vendors have voluntarily moved to the vending zones","raids, bribes and the vendors' return keep repeating","city authorities have stopped collecting taxes from vendors"],"answer":2,"explanation":"The passage says that where the law is ignored 'the old cycle of raids, bribes and returns continues'. Orderly pavements are reported where the law IS implemented.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-43","question":"Passage: My grandmother learned to read at the age of sixty-two. As a girl she had been kept at home to look after her younger brothers, and for most of her life she signed documents with a thumbprint, a fact that embarrassed her more than she ever admitted. When the village started an evening class for adults, she was the first to enrol and the last to leave each night. She practised letters on the backs of old calendars and made us children test her on the signboards at the bus stand. The day she read a whole page of the newspaper aloud, slowly but without help, she did not smile; she simply folded the paper, put it under her pillow and said she would read the rest tomorrow. Question: Which word best describes the grandmother as presented in the passage?","options":["resentful","complacent","boastful","determined"],"answer":3,"explanation":"She enrols first, stays last, practises daily and quietly plans to read more — signs of determination. She does not boast even after succeeding.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-44","question":"Passage: Weather forecasting has improved remarkably in the last few decades. A five-day forecast today is about as accurate as a one-day forecast was in the 1980s. The gains come from three sources: satellites that watch the whole planet continuously, faster computers that can run more detailed models of the atmosphere, and better methods of feeding fresh observations into those models. Even so, the weather remains a chaotic system, in which tiny errors in the starting data grow larger over time. That is why forecasters now issue predictions as probabilities — a 70 per cent chance of rain — rather than as certainties. Far from being a sign of weakness, such honesty about uncertainty helps farmers, fishermen and disaster managers make better decisions. Question: As used in the passage, the word 'chaotic' refers to a system in which:","options":["events happen without any physical cause behind them","small errors at the start grow into large differences later","nothing can ever be predicted, however good the data","only satellites, not ground stations, can collect useful data"],"answer":1,"explanation":"The passage defines it in the next clause: tiny errors in the starting data grow larger over time. It does not claim that weather is causeless or wholly unpredictable.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-45","question":"Passage: Composting at home is easier than most people imagine. Vegetable peels, tea leaves, eggshells and dry leaves can be layered in a simple container with a few holes for air. Within six to eight weeks, microbes break this material down into dark, crumbly compost that enriches garden soil. The main rules are to keep the heap moist but not soggy, to turn it every week so that air reaches the inside, and to avoid adding meat or oily food, which attract pests and produce bad smells. A household that composts its kitchen waste can cut the rubbish it sends to landfills by nearly half. In cities where landfills are already overflowing, such small habits, repeated across thousands of homes, can make a visible difference. Question: Which of the following should NOT be added to a home compost heap, according to the passage?","options":["Meat and oily food","Vegetable peels and tea leaves","Eggshells","Dry leaves"],"answer":0,"explanation":"The passage says to avoid meat and oily food because they attract pests and cause smells. The other three are listed as suitable materials.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-46","question":"Passage: For many small farmers, the diesel pump was both a blessing and a burden. It lifted water from wells to the fields, but fuel was expensive and often had to be carried from a town many kilometres away. Solar pumps promise to change this. Once installed, they run on free sunlight, need little maintenance and make no noise or smoke. Government subsidies have brought the cost within reach of many farmers. There is, however, a risk that experts have begun to point out: because pumping now costs almost nothing, some farmers run their pumps all day, drawing more groundwater than the land can replenish. Unless free energy is matched by careful water management, the solar revolution could simply dry up the wells faster. Question: The 'risk' mentioned in the passage is that solar pumps may:","options":["pollute the air around fields with smoke","break down frequently in hot weather","be too expensive for most farmers to buy","encourage farmers to overuse groundwater"],"answer":3,"explanation":"Because pumping becomes almost free, farmers may draw more groundwater than can be replenished. The passage states the pumps need little maintenance and make no smoke.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-47","question":"Passage: When a computer program defeated the world chess champion in 1997, many people predicted the death of the game. Why would anyone play chess if a machine could always win? The opposite happened. Chess is more popular today than ever before. Players use computers to analyse their games, spot mistakes and prepare new openings. Young players in small towns, with no coach nearby, can now practise against strong opponents at any hour. Online platforms broadcast tournaments to millions of viewers, with engines showing who is winning after each move. The machines did not replace human players; they became their tireless teachers. The story of chess suggests that a technology that outperforms people can still enrich, rather than end, a human activity. Question: What happened to chess after a computer defeated the world champion?","options":["Most professional players gave up the game","It was replaced by computer-only tournaments","It became more popular than before","It was banned on online platforms"],"answer":2,"explanation":"The passage says 'The opposite happened. Chess is more popular today than ever before.' Computers became teachers rather than replacements.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-48","question":"Passage: Elephants need space. A single herd may roam hundreds of square kilometres in a year, following water and food through the seasons. As forests have been broken up by roads, railways, canals and farms, elephants increasingly find their old paths blocked. When they push through, they trample crops and sometimes kill people, and angry villagers retaliate. Wildlife corridors — narrow strips of protected land that link one forest patch to another — offer a solution. They let elephants move between habitats without wandering into villages. Securing corridors is not easy: the land is often privately owned, and families must be compensated fairly for moving. But experience shows that a well-planned corridor costs far less than the endless cycle of crop damage, compensation claims and deaths that it prevents. Question: According to the passage, a wildlife corridor is:","options":["a fence that keeps elephants away from busy roads and railways","a strip of protected land connecting separate forest areas","a zoo where injured or orphaned elephants are treated","a compensation scheme for farmers who lose crops"],"answer":1,"explanation":"The passage defines corridors as 'narrow strips of protected land that link one forest patch to another'.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-49","question":"Passage: Most students prepare for exams by reading their notes again and again. It feels productive, because the material becomes familiar. But familiarity is not the same as memory. Research on learning shows that two simple changes work far better. The first is testing oneself: closing the book and trying to recall what one has read, even if the attempt fails. The second is spacing: reviewing a topic after a day, then after a few days, then after a week, instead of cramming it all at once. Both methods feel harder than rereading, and that very difficulty is what strengthens memory. Students who adopt them often report that they study for fewer hours but remember more on the day of the exam. Question: According to the passage, why does rereading feel productive?","options":["Because the material starts to feel familiar","Because it strengthens memory more than any other method","Because it is harder than testing oneself","Because it requires fewer hours of study than other methods"],"answer":0,"explanation":"Rereading feels productive because 'the material becomes familiar', but the passage warns that familiarity is not memory.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-50","question":"Passage: The old lighthouse keeper still climbs the hundred and twelve steps every evening, though the lamp has been automatic for eleven years. Nobody pays him to do it. The government that once employed him now sends a technician twice a year to check the bulbs and the solar panels, and the technician, a cheerful young man, always finds everything in order. 'Of course it is in order,' the old man tells him. 'I wipe the glass every night.' The technician laughs, but he has noticed that the lamp at this lighthouse never seems to need the repairs that lamps at the other, empty lighthouses do. In his report he writes only 'Satisfactory'. He does not know how to write down an old man's habit. Question: The keeper continues to climb the steps every evening mainly because:","options":["the automatic lamp must still be switched on by hand","the government still pays him a small wage for it","it is a lifelong habit and a matter of personal care","the technician has asked him to check the lamp each night"],"answer":2,"explanation":"The lamp is automatic and nobody pays him; he goes out of habit and care ('I wipe the glass every night').","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-51","question":"Passage: Folk theatre in many parts of India once travelled from village to village, performing all night on makeshift stages lit by lanterns. Audiences knew the stories by heart, yet they came every year, because the pleasure lay in how each troupe sang, joked and improvised. Today many of these forms are struggling. Young performers leave for jobs in cities, and audiences prefer television serials that require no late nights. Some troupes have survived by shortening their shows, adding film songs or performing at hotels for tourists. Purists complain that this dilutes the tradition. But traditions have always changed; the forms we now call 'classical' were once new and controversial. The real danger is not change but silence — a stage where nobody performs at all. Question: The author's attitude towards troupes that adapt their performances is best described as:","options":["fearful and alarmed","contemptuous and dismissive of their choices","completely indifferent to what they do","understanding and broadly accepting"],"answer":3,"explanation":"The author argues that traditions have always changed and that 'the real danger is not change but silence', so he accepts adaptation. It is the purists, not the author, who complain.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-52","question":"Passage: Constant noise is usually treated as an irritation rather than a health problem. Yet studies in several countries have linked long-term exposure to traffic noise with higher blood pressure, poorer sleep and even a greater risk of heart disease. The reason seems to be that the body reacts to loud or sudden sounds as if to a threat, releasing stress hormones even while a person is asleep and not consciously aware of the sound. Over years, these repeated small alarms take their toll. Unlike smoke, noise leaves no visible trace, which may explain why it receives so little attention from city planners. Quieter road surfaces, better window insulation and limits on night-time honking are cheap measures that could protect the health of millions. Question: It can be inferred from the passage that noise receives little attention from planners partly because:","options":["it has been proven harmless to people who are asleep","its effects are not visible in the way that smoke is","the measures to reduce it are very expensive to install","people quickly get used to it and stop reacting"],"answer":1,"explanation":"The passage says noise 'leaves no visible trace, which may explain why it receives so little attention'. It describes the remedies as cheap and says the body keeps reacting even during sleep.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-53","question":"Passage: India's groundwater crisis began with a success. In the 1970s and 1980s, cheap electric pumps and subsidised power allowed millions of farmers to sink their own borewells. Irrigation was no longer limited to land near canals, and harvests rose. But because each farmer could pump as much as he wanted, and electricity was often free or charged at a flat rate, there was no reason to save water. As water tables fell, farmers drilled deeper, spending more on bigger pumps. In some districts, wells that once struck water at twenty feet now go down several hundred. The individual farmer is not to blame; he is responding sensibly to the incentives before him. It is the incentives that must change, and that is a task for policy, not for preaching. Question: The author holds that the main cause of the groundwater crisis is:","options":["the greed and ignorance of individual farmers","incentives that reward unlimited pumping","the failure of canals to reach most villages","a decline in rainfall over recent decades"],"answer":1,"explanation":"The author explicitly says the farmer 'is not to blame' and that 'it is the incentives that must change' — flat or free power encouraged unlimited pumping.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-54","question":"Passage: A shirt that costs less than a cup of coffee seems like a bargain. But the low price hides costs that someone else pays. Growing cotton consumes vast amounts of water; dyeing fabric pollutes rivers near factories; and garment workers, often young women, may earn too little to live on. Because such clothes are cheap, buyers treat them as disposable, wearing them a few times before throwing them away. Most of these garments end up in landfills or are burnt. Some brands now promise 'sustainable' collections, but critics point out that a brand selling ever larger volumes of clothing cannot be sustainable merely by changing the fabric. The most sustainable shirt, they say, is the one already in your wardrobe. Question: The critics' view of 'sustainable' collections is that:","options":["they use even more water than ordinary cotton clothes do","they are too expensive for most ordinary buyers to afford","they cannot solve the problem while sales keep rising","they are the best solution the industry can offer today"],"answer":2,"explanation":"Critics say a brand selling 'ever larger volumes' cannot be sustainable merely by changing the fabric; the root problem is overconsumption.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-55","question":"Passage: Look up on a clear night in any large city and you will see perhaps a dozen stars. A few generations ago, the same sky would have shown thousands, with the Milky Way stretching across it like a pale river. The difference is not in the sky but in the ground: street lamps, billboards and buildings spill so much light upwards that the darkness is washed away. This light pollution does more than spoil the view. Migrating birds, which navigate partly by the stars, become confused and crash into lit towers; baby turtles, which crawl towards the brightest horizon, head inland instead of to the sea. Fortunately, light pollution is easier to fix than most kinds. Shielded lamps that point downwards save energy as well as the night. Question: The author's statement that light pollution is 'easier to fix than most kinds' most likely rests on the fact that:","options":["simple changes to lamp design reduce it immediately","birds and turtles are slowly adapting to the brighter nights","most cities have already banned unshielded street lamps","it disappears on its own during the long winter nights"],"answer":0,"explanation":"The passage follows the claim with the remedy: shielded lamps that point downwards. Unlike, say, chemical pollution, nothing lingers once the light is redirected.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-56","question":"Passage: Children learn best in a language they understand. That seems obvious, yet in many schools young children are taught in a language they rarely hear at home. They spend the early years memorising words they cannot follow, and many fall behind permanently. Studies show that pupils who begin in their mother tongue and then move gradually to a second language often end up better in both languages than those who start directly in the second. The reason is that reading and reasoning, once learnt in a familiar language, transfer easily. Parents, however, often prefer English-medium schools because they see English as the key to good jobs. The challenge for policy is to respect that hope without sacrificing the foundation on which all learning rests. Question: Which of the following best describes the 'challenge for policy' mentioned at the end?","options":["Teaching all children only in their mother tongue from start to finish of school","Persuading parents that English is unnecessary for getting good jobs","Abolishing English-medium schools entirely in the early years","Meeting parents' wish for English without dropping mother-tongue foundations"],"answer":3,"explanation":"The final sentence speaks of respecting parents' hope (English for jobs) without sacrificing the foundation (mother-tongue learning). It does not reject English.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-57","question":"Passage: Delivery riders and cab drivers who work through apps are called 'partners' rather than employees. The label matters. As partners, they can choose their hours and log out whenever they like, which many value. But they also lack the protections employees enjoy: there is no paid leave, no health insurance from the company and no pension. If a rider is injured in an accident, the cost often falls on him alone. Companies argue that treating riders as employees would destroy the flexibility that attracts them. Workers' groups respond that flexibility and security are not opposites; a fund paid for by a small charge on every order could provide insurance without forcing anyone to work fixed hours. Such funds, they add, already exist for some other informal trades. Question: The workers' groups' proposal is intended to show that:","options":["companies should stop charging customers for deliveries","riders should be made full-time employees with fixed hours","security can be provided without removing flexibility","flexibility is not really valued by most riders"],"answer":2,"explanation":"They argue 'flexibility and security are not opposites' and propose an order-based fund that insures riders without fixed hours.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-58","question":"Passage: Turning seawater into drinking water sounds like the perfect answer to water shortages. The technology already exists: in reverse osmosis, seawater is pushed at high pressure through membranes that hold back the salt. Several coastal cities depend on such plants. Yet desalination has drawbacks that make it a last resort rather than a first choice. It uses a great deal of energy, which makes the water expensive and, if the power comes from coal, adds to carbon emissions. The leftover brine, twice as salty as seawater, is usually pumped back into the sea, where it can harm marine life near the outlet. For inland towns, the cost of piping water uphill from the coast adds further to the bill. Fixing leaking pipes is usually far cheaper. Question: The author's view of desalination is that it is:","options":["harmless to the environment as long as it is done properly","the perfect answer to water shortages in every region","a technology that has not yet been tested at scale","useful but costly, best kept for when other options fail"],"answer":3,"explanation":"The author calls it 'a last resort rather than a first choice' because of energy use, cost and brine. The 'perfect answer' view is the one he qualifies.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-59","question":"Passage: Loneliness among the elderly is often described as a private sorrow. Increasingly, doctors treat it as a public health problem. People who are chronically lonely tend to sleep badly, eat poorly and visit doctors more often; some studies suggest that loneliness harms health as much as smoking a pack of cigarettes a day. The causes are partly modern: children move to distant cities for work, joint families give way to nuclear ones, and neighbourhoods change faster than old friendships can adjust. Some towns now run 'befriending' schemes in which volunteers phone or visit elderly people regularly. Such schemes cost little, and early evaluations show that a weekly conversation can lift mood and reduce visits to the doctor. Few medicines are so cheap or so pleasant. Question: The comparison with smoking is used in the passage to:","options":["emphasise how serious the health effects of loneliness can be","argue that elderly people tend to smoke more when they are lonely","show that smoking is one of the main causes of loneliness","suggest that befriending schemes also help people quit smoking"],"answer":0,"explanation":"The comparison shows the scale of harm — loneliness may hurt health as much as heavy smoking — supporting the claim that it is a public health issue.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-60","question":"Passage: Bamboo is technically a grass, but in many parts of Asia it has long been used as a building material. It grows astonishingly fast — some species several centimetres a day — and can be harvested in three to five years, compared with decades for most timber. Weight for weight, it is remarkably strong in tension, which is why it has been used for scaffolding on high-rise buildings. Its weaknesses are equally real: untreated bamboo rots and attracts insects, and its hollow, irregular stems are hard to join with the precision modern construction demands. Engineers are now developing treated and laminated bamboo products that overcome these problems. If they succeed, a plant once seen as the poor man's timber may become a material of choice. Question: The phrase 'the poor man's timber' suggests that bamboo was traditionally regarded as:","options":["the most valuable building material in Asia","a cheap and inferior substitute for wood","a material used only by the wealthy","too strong to be used for houses"],"answer":1,"explanation":"'Poor man's X' means a cheaper, lesser version of X. The final sentence contrasts this old view with its possible future as 'a material of choice'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-61","question":"Passage: Some cities charge drivers a fee for entering the busiest parts of town during peak hours. The idea, known as congestion pricing, is simple: road space at rush hour is scarce, and when something scarce is free, it gets overused. Where the scheme has been tried, traffic in the charged zone has fallen sharply, buses run faster and air quality has improved. The money collected is often spent on public transport. Critics argue that the charge is unfair to poorer drivers, who may have no alternative. Supporters reply that the poorest residents rarely drive into city centres at all; they ride the very buses that the scheme speeds up. The fairness of the policy, they say, depends on how its revenue is used. Question: The supporters' reply to the critics relies mainly on the point that:","options":["the poorest mostly ride buses, which the scheme speeds up","poorer drivers can easily afford the charge if they plan ahead","the charge applies only to luxury cars entering the centre","traffic did not actually fall in the charged zone"],"answer":0,"explanation":"Supporters say the poorest rarely drive into the centre and instead ride the buses that the scheme speeds up, so the scheme can help rather than hurt them.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-62","question":"Passage: Handloom weaving in India survives on a knife-edge. A sari that takes a weaver two weeks to make by hand must compete with a power-loom copy produced in an hour and sold at a fraction of the price. Most buyers cannot tell the difference, and some sellers are happy to keep it that way. Geographical Indication tags, which certify that a product comes from a particular region and is made by traditional methods, were meant to protect weavers from such imitation. In practice, enforcement is weak, and many weavers do not even know their craft is registered. A label is only as strong as the system that checks it. Without inspections and buyer awareness, the tag risks becoming a decoration rather than a defence. Question: What does the author mean by saying the tag 'risks becoming a decoration rather than a defence'?","options":["It is no longer being awarded to genuine handloom products","It is printed in an attractive design that buyers admire","It will raise the price of power-loom saris above handloom ones","It may look official but fail to protect weavers in practice"],"answer":3,"explanation":"Without enforcement and awareness, the GI label would exist on paper ('decoration') without actually shielding weavers from imitation ('defence').","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-63","question":"Passage: Some universities have begun to experiment with open-book examinations. Students may bring textbooks and notes into the hall, but the questions are designed so that the answers cannot simply be copied. Instead of asking 'Define inflation', a paper might describe a small town's rising prices and ask students to explain what is happening and what the local bank should do. Teachers who have tried this format report that it rewards understanding over memory, and that students prepare differently — less by learning definitions and more by practising how to apply ideas. Students, however, are often surprised to find that open-book papers are harder, not easier. Having the book in front of you is of little use if you do not know what you are looking for. Question: Why do students find open-book papers harder than they expect?","options":["They are not given enough time to read through their books in the hall","The questions test applying ideas, which the book alone cannot supply","The questions ask only for definitions that are hard to locate in the book","Teachers do not actually allow notes to be brought into the hall"],"answer":1,"explanation":"Questions are designed so answers cannot be copied; they require applying ideas, and 'having the book ... is of little use if you do not know what you are looking for'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-64","question":"Passage: Every summer the narrow roads of popular hill towns fill with cars. Hotels are booked months in advance, water tankers queue outside guest houses, and the hillsides are scarred by new construction. Tourism brings money and jobs, and few residents want it to stop. But the very crowds that sustain the economy are slowly destroying what the visitors come to see — the cool air, the quiet forests and the views. Some towns have begun to limit the number of vehicles allowed in each day or to charge an environmental fee. Hoteliers protest that such limits will drive tourists elsewhere. Their fear is understandable, yet a hill town that loses its charm will lose its tourists anyway, only more slowly and more painfully. Question: Which of the following best captures the author's response to the hoteliers' protest?","options":["Tourists will never go elsewhere, however crowded the town becomes","Hoteliers should be banned from building in the town altogether","Without limits the town loses its tourists anyway, more painfully","Environmental fees will actually increase the number of visitors"],"answer":2,"explanation":"The author grants their fear but argues that a town that loses its charm 'will lose its tourists anyway, only more slowly and more painfully'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-65","question":"Passage: Old mobile phones, laptops and chargers contain small amounts of gold, silver and copper, along with toxic lead and mercury. In many Indian cities, this electronic waste is processed not in factories but in small backyard workshops. Workers, often without gloves or masks, break open devices and burn cables to recover metal, breathing in fumes that damage the lungs and nerves. Formal recycling plants exist, but they struggle to get enough waste, because the informal sector pays households more for their old devices. Banning the backyard workshops would put thousands out of work and simply push the trade underground. A more realistic approach, some experts argue, is to bring informal workers into the formal system, training them and supplying safe equipment. Question: Why do formal recycling plants struggle to get enough e-waste?","options":["The government bans the sale of e-waste to private plants","Households prefer to keep their old devices at home","Informal workshops pay households more for old devices","Formal plants accept only laptops, not phones or chargers"],"answer":2,"explanation":"The passage states that formal plants struggle 'because the informal sector pays households more for their old devices'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-66","question":"Passage: People who hesitate to vaccinate their children are often portrayed as ignorant or selfish. Researchers who actually talk to them usually find something different: parents who love their children and are frightened of doing them harm. Many have read alarming stories online or heard of a neighbour's child who fell ill after an injection, even if the illness had nothing to do with it. Lecturing such parents, or mocking them, tends to make them dig in. What works better is patient conversation with someone they trust — often their own family doctor or a local health worker — who listens to their fears before answering them. Trust, once lost, is rebuilt slowly, one conversation at a time, and no advertising campaign can do the job on its own. Question: According to the passage, mocking hesitant parents usually:","options":["has no real effect on the decisions they make","persuades them to vaccinate their children quickly","makes them hold on to their views more firmly","makes them trust their own doctors more than before"],"answer":2,"explanation":"The passage says lecturing or mocking 'tends to make them dig in', i.e. hold their position more firmly.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-67","question":"Passage: Thousands of pieces of debris now circle the Earth: dead satellites, spent rocket stages and fragments from collisions. Even a fleck of paint, travelling at several kilometres a second, can damage a working satellite. The real fear is a chain reaction. When two large objects collide, they shatter into thousands of fragments, each of which can strike another object and create more fragments. If this cascade ever ran out of control, some orbits could become too dangerous to use for generations, threatening the satellites that guide aircraft, forecast weather and carry phone signals. Space agencies now require new satellites to leave orbit within a set time after their missions end, and several companies are testing ways to capture old debris. Cleaning up space, however, is far harder than littering it. Question: The 'chain reaction' feared in the passage refers to:","options":["collisions producing fragments that cause further collisions","dead satellites falling back into the atmosphere one after another","rockets exploding one after another during launch","phone and navigation networks failing in succession"],"answer":0,"explanation":"The passage explains that colliding objects shatter into fragments which strike other objects and create more fragments — a cascade of collisions.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-68","question":"Passage: In some countries, people are organ donors unless they choose otherwise; in others, they must actively sign up to become donors. The difference sounds minor, yet donor rates in 'opt-out' countries are often dramatically higher. Most people do not hold strong views either way, and they simply stay with whatever option is set as the default. Policymakers have taken note. Defaults are now used to raise pension savings, by enrolling employees automatically while letting them withdraw if they wish. Such 'nudges' are attractive because they preserve freedom of choice while steering behaviour. Critics worry, though, that a government skilled at nudging could just as easily steer people towards choices that serve the state rather than the citizen. The tool, in other words, is only as trustworthy as the hand that uses it. Question: The critics' concern about nudges is that:","options":["they have no measurable effect on how people actually behave","they remove all freedom of choice from the citizens who are nudged","they are too expensive for most governments to put into practice","the technique could serve the state's interests, not the citizen's"],"answer":3,"explanation":"Critics fear a government 'could just as easily steer people towards choices that serve the state rather than the citizen'. The passage itself says nudges preserve freedom of choice.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-69","question":"Passage: A few years ago, brightly coloured shared bicycles appeared on the streets of many cities, unlocked by a phone app and left anywhere after use. Investors poured in money, and companies flooded pavements with tens of thousands of bikes. Within months, many of the schemes collapsed. Bikes were vandalised, stolen or dumped in rivers; pavements were blocked by heaps of abandoned cycles; and companies, competing to grow fast, charged fares too low to cover repairs. The idea itself was not foolish — cities that later introduced smaller, well-managed schemes with docking stations and fair prices have seen steady use. The lesson is that a good idea, scaled up recklessly, can look like a bad one. Investors who judged the idea by the wreckage drew exactly the wrong conclusion. Question: The author would most likely agree that the early shared-bicycle schemes failed mainly because of:","options":["the basic idea of shared bicycles being unsound","reckless expansion and poor management","a lack of interest among city residents","government bans on bicycles"],"answer":1,"explanation":"The author says 'the idea itself was not foolish' and blames reckless scaling, rock-bottom fares and poor upkeep; well-managed schemes later succeeded.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-70","question":"Passage: Wetlands were long regarded as wasteland — damp, mosquito-ridden places best drained and built upon. Scientists now describe them as the kidneys of the landscape. Reeds and microbes in marshes filter pollutants from water that passes through them; the spongy soil soaks up floodwater in the monsoon and releases it slowly in the dry months; and the shallow waters shelter fish and migratory birds. When a city fills in its wetlands for housing, it often discovers the loss only during the next heavy rain, when water that once spread harmlessly into the marsh floods streets and homes instead. Restoring a wetland is possible, but it costs far more than protecting one, and some of what is lost never fully returns. Question: In calling wetlands 'the kidneys of the landscape', scientists mainly emphasise their role in:","options":["breeding and spreading mosquitoes","producing food for nearby cities","filtering and cleaning water","providing land for housing"],"answer":2,"explanation":"Kidneys filter blood; the analogy is explained by the next sentence about reeds and microbes filtering pollutants from water.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-71","question":"Passage: Rooftop vegetable gardens have become fashionable in many cities. Enthusiasts claim they can make households self-sufficient in vegetables, cool buildings in summer and reduce the food miles of the city. The last two claims are reasonable. A layer of soil and plants does keep the room below cooler, and a tomato grown on one's roof travels no distance at all. The first claim, however, deserves scepticism. A typical rooftop can produce a useful supplement of greens and herbs, but feeding a family through the year would need far more space, sunlight and labour than most city roofs or residents can offer. The value of rooftop gardens may lie less in the quantity of food they produce than in reconnecting city people with how food is grown. Question: Which of the enthusiasts' claims does the author doubt?","options":["That rooftop gardens keep the rooms below them noticeably cooler in summer","That rooftop gardens make households self-sufficient in vegetables","That rooftop gardens reduce the distance food travels to the city","That rooftop gardens reconnect city people with growing food"],"answer":1,"explanation":"The author calls the cooling and food-miles claims reasonable but says 'The first claim, however, deserves scepticism' — self-sufficiency. Reconnection is the author's own suggestion, not the enthusiasts'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-72","question":"Passage: Each time a doping scandal breaks, officials promise tougher testing. Yet testers are almost always a step behind, and athletes and their advisers know it well. New substances are designed to be invisible to existing tests, and by the time a test is developed, athletes have moved on to something else. For this reason, many anti-doping agencies now store athletes' samples for years so that they can be retested when better methods arrive. Several medals have been stripped long after the events, when old samples finally revealed what had been hidden. The threat of future detection may deter cheats more than today's tests do. An athlete can perhaps outwit the laboratory of the present; it is much harder to outwit the laboratory of the future. Question: The main point of the last two sentences is that:","options":["the threat of later retesting may deter doping more than current tests","present-day laboratories are completely ineffective at catching cheats","athletes should be tested only after they have retired from sport","stripping medals years after an event is unfair to the athletes"],"answer":0,"explanation":"They argue that stored samples face 'the laboratory of the future', so the threat of future detection deters cheats. The author does not call present tests useless or later penalties unfair.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-73","question":"Passage: When the last speakers of a village's dialect die, their songs, recipes and memories of famines and festivals often die with them. Oral history projects try to prevent this by recording elderly people as they talk about their lives. The recordings are rarely dramatic. A grandmother describes how rice was husked by hand; a retired postman lists the villages on his old route. Yet historians value such accounts precisely because they are ordinary. Official records tell us what kings decreed and what taxes were collected; they seldom tell us how people actually lived. The danger is that these projects capture voices but not context — a recording without notes on who is speaking, and when, can puzzle future listeners as much as it helps them. Question: According to the passage, historians value oral accounts mainly because they:","options":["are easy to understand without any context or explanation","describe dramatic events such as famines in great detail","are more accurate than official records about taxes collected","record everyday life that official documents tend to ignore"],"answer":3,"explanation":"Historians value them 'precisely because they are ordinary' — official records seldom tell how people actually lived. The passage warns that recordings without context can puzzle listeners.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-74","question":"Passage: Fact-checking websites have multiplied, yet false stories continue to spread faster than corrections. One reason is timing: a fact-check usually appears hours or days after the false claim, by which time the claim has been shared thousands of times. Another is that corrections rarely reach the people who saw the original story. A third, more troubling reason is that some people share stories not because they believe them but because the stories express how they feel. For such readers, a fact-check misses the point, rather as a weather report misses the point of a poem about rain. Fighting misinformation may therefore require not only checking facts but also understanding why certain falsehoods feel true to those who share them. A correction that ignores this may be accurate and still useless. Question: The comparison with 'a weather report' and 'a poem about rain' suggests that:","options":["fact-checkers should write in a more poetic style to reach their readers","weather reports are often just as unreliable as the false stories they resemble","poems and feelings spread faster online than ordinary news stories do","some stories are shared for their feeling, which a fact-check cannot answer"],"answer":3,"explanation":"Just as a weather report does not engage with what a poem expresses, a fact-check does not engage with the feelings that make people share a story.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-75","question":"Passage: Mr Dastur repaired clocks in a shop so narrow that customers had to stand sideways. He never advertised and kept no fixed hours, yet people brought him clocks from all over the city, some of them a hundred years old. He worked slowly, and when anyone complained, he would hold up a tiny brass wheel and say, 'This was made by a man who was not in a hurry. I will not insult him by being in one.' When he died, his nephew turned the shop into a mobile-phone store. It is busy and brightly lit, and the young man is courteous and quick. But on the shelf behind the counter, he has kept one of his uncle's clocks, which he winds every Sunday, though he cannot quite say why. Question: The nephew's habit of winding the clock every Sunday most likely suggests:","options":["a quiet plan to reopen the clock shop one day","an unspoken respect for his uncle and what he stood for","that the phone store has failed to attract customers","a lingering dislike of his uncle's slow, old-fashioned ways"],"answer":1,"explanation":"He keeps and winds the clock without being able to explain why, hinting at an inarticulate attachment to his uncle and his unhurried craft. Nothing suggests reopening the shop or failure of the store.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-76","question":"Passage: Sand seems limitless, yet it is one of the most heavily extracted materials on Earth. Concrete, glass and the land reclaimed for new ports all need it in huge quantities. Desert sand, ironically, is of little use for construction, because wind has rounded its grains so that they do not bind well. Builders want the angular sand found in riverbeds and coasts. As a result, rivers in many countries are being dredged faster than they can replenish themselves. Riverbeds sink, bridges are undermined, groundwater falls, and fish lose their breeding grounds. In some places, illegal mining is run by gangs who threaten officials and journalists. Few people think about sand at all, which is partly why its exploitation has gone so far unchecked. Question: Why, according to the passage, is desert sand of little use in construction?","options":["It contains too much salt for concrete to set properly","It is too expensive to transport from distant deserts","Its grains are rounded by wind and do not bind well","Governments have banned its use in construction"],"answer":2,"explanation":"The passage explains that wind has rounded desert sand grains 'so that they do not bind well'; builders need angular river and coastal sand.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-77","question":"Passage: Electric buses are quieter and cleaner than diesel ones, and their running costs are lower. Their purchase price, however, is much higher, largely because of the batteries. Many city transport bodies, already in debt, cannot afford to buy them outright. A newer approach is to lease the buses: a private company buys and maintains them, and the city pays a fee for each kilometre run. The city avoids the large upfront cost, and the company carries the risk if the buses break down. Critics warn that long contracts could lock cities into paying high fees for decades. Supporters reply that without such arrangements, most cities would not be able to switch to electric buses at all. A costly bus on the road, they say, is better than a cheap plan on paper. Question: Which of the following is an assumption underlying the supporters' reply?","options":["Most cities cannot afford to buy electric buses outright","Private companies never charge cities high leasing fees","Diesel buses will soon be banned in most cities","Electric buses have lower purchase prices than diesel buses"],"answer":0,"explanation":"Supporters claim that without leasing most cities could not switch at all, which assumes they cannot afford outright purchase. The passage says the purchase price is much higher, not lower.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-78","question":"Passage: Digital payments have spread rapidly, and many people now pay for tea, vegetables and bus tickets with their phones. Governments welcome the change, since digital transactions are easier to tax and trace than cash. But a fully cashless economy would leave some people behind: the elderly who are uncomfortable with smartphones, workers in areas with poor network coverage, and those who cannot afford a smartphone at all. There is also the question of resilience. When servers fail or networks go down during floods, digital payments stop, while cash continues to work. A sensible policy, then, would encourage digital payments without making cash disappear. The aim should be choice, not compulsion. A payment system, like a road, should serve everyone who needs to use it, not merely those who travel fastest. Question: The author's argument would be most WEAKENED if it were shown that:","options":["digital payments are easier for governments to tax and trace than cash","many elderly people still prefer to pay in cash","digital payments keep working when networks fail in disasters","some rural areas have poor or patchy mobile network coverage"],"answer":2,"explanation":"One of the author's reasons for keeping cash is resilience — cash works when networks fail. Evidence that digital payments work reliably in such conditions would undercut that reason. The other options support or are neutral to the argument.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-79","question":"Passage: Child prodigies are celebrated on television and in newspapers: the eight-year-old who solves complex sums, the ten-year-old violinist who plays with an orchestra. Yet studies that follow such children into adulthood find that only a minority become eminent in their fields. Some lose interest; others burn out under the pressure of expectations; many simply turn into competent but ordinary adults. The skills that make a prodigy — mastering what is already known, quickly and precisely — are different from those that make an innovator, who must question what is known and risk failure. A child praised constantly for being brilliant may become afraid of the very mistakes from which originality grows. Praising effort rather than talent, some psychologists suggest, may protect children from this trap. Question: The passage suggests that constant praise for brilliance may harm a gifted child by:","options":["making the child afraid of making mistakes","reducing the child's speed in learning","causing the child to lose interest in praise","preventing the child from mastering known skills"],"answer":0,"explanation":"The last sentence says such a child 'may become afraid of the very mistakes from which originality grows'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-80","question":"Passage: The fair came to our village every year after the harvest. For three days the dusty ground behind the temple became a city of tents: bangle sellers, sweet makers, a giant wheel that creaked alarmingly, and a man who swallowed swords for a fee. My father gave us each two rupees, a sum that seemed limitless until we reached the first stall. I remember spending mine on a tin whistle that broke the same evening, and feeling no regret at all. I went back to the village last year. The fair still happens, but it is smaller; the giant wheel is gone, and children walk around looking at their phones. I bought a tin whistle anyway. It broke the same evening, and this time, oddly, I minded. Question: Why does the narrator mind the broken whistle 'this time'?","options":["Because the whistle cost far more now than it had in his childhood","Because it now stands for a past he can no longer recapture","Because his children had wanted the whistle for themselves","Because the seller refused to replace the broken whistle"],"answer":1,"explanation":"As a child the joy lay in the moment; now the whistle carries nostalgia for a vanished fair and childhood, so its breaking hurts. Nothing is said about cost, his children or a refusal.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-81","question":"Passage: Seed banks store frozen samples of crop varieties so that they are not lost forever. The best known lies inside a mountain on a remote Arctic island, but hundreds of smaller banks exist around the world. Their value became clear when a war damaged a seed bank in the Middle East: scientists were able to restore its collection from duplicates stored abroad. Yet seed banks have a limitation. A seed frozen today is a snapshot of a plant adapted to today's conditions. In the field, farmers' varieties keep evolving as they adapt to new pests and a changing climate. Conservation in vaults and conservation on farms are therefore complementary; neither, on its own, is enough. A vault preserves the past; a farm keeps writing the future. Question: The author's main point about seed banks is that they:","options":["store only seeds adapted to the cold Arctic conditions of the main vault","have made it unnecessary for farmers to keep growing old varieties","are too vulnerable to war and disaster to be of real use","are valuable but need farmers to keep growing old varieties too"],"answer":3,"explanation":"The author praises seed banks but notes that frozen seeds stop evolving, so vault and on-farm conservation are 'complementary; neither ... is enough'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-82","question":"Passage: Lantana, a flowering shrub from the Americas, was brought to India as an ornamental hedge in the nineteenth century. Today it covers vast areas of forest, forming thickets so dense that native grasses and saplings cannot grow beneath them. Deer and other grazers lose their food, and the animals that prey on them follow. Clearing lantana is labour-intensive, and if the roots are not removed it simply grows back, often more vigorously. Some forest departments have turned the problem into an opportunity, training villagers to make furniture and baskets from lantana stems. The scheme provides income and removes the shrub at the same time. It is, however, a modest answer to an immense problem; the rate of clearing remains far below the rate of spread. Question: Which of the following best describes the author's assessment of the furniture-making scheme?","options":["It has completely eliminated lantana from the forests","It is helpful but far too small to solve the problem","It has made lantana spread faster through the forests","It is a waste of the villagers' time and the state's money"],"answer":1,"explanation":"The author calls it an opportunity that provides income and removes the shrub, but 'a modest answer to an immense problem' since clearing lags far behind spread.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-83","question":"Passage: Modern zoos describe themselves as centres of conservation rather than entertainment. Some have indeed helped save species: animals bred in captivity have been released to rebuild wild populations that had nearly vanished. Critics point out, however, that most animals in zoos belong to species that are not endangered at all, and that some animals — particularly large, wide-ranging ones such as elephants and polar bears — show signs of stress in even the best enclosures. Zoos reply that visitors who see living animals are more likely to support conservation. That may be true, but it is hard to prove. Perhaps the fairest conclusion is that zoos can be justified for some species and not for others. A blanket verdict either way says more about the speaker than about the animals. Question: The author's position on zoos is best described as:","options":["uninterested in the question of zoos altogether","entirely favourable to zoos as centres of conservation","entirely opposed to keeping any animals in zoos","qualified: justified for some species, not for all"],"answer":3,"explanation":"The author concedes the zoos' successes and the critics' points, then concludes that 'zoos can be justified for some species and not for others' — a qualified view.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-84","question":"Passage: Office workers in many organisations spend a large part of their week in meetings, and surveys suggest that a good share of those meetings are considered unproductive by the people who attend them. The cost is not only the hours spent in the room. Deep, focused work requires long stretches of uninterrupted time, and a day broken by meetings at ten, twelve and three leaves only short gaps in which little serious thinking is possible. Some companies have introduced 'no-meeting days' or require every meeting to have a written agenda and a fixed end time. Employees report that such rules feel restrictive at first, but that they soon find themselves finishing more work in fewer hours. Some even say they enjoy the meetings that remain, because there are fewer of them. Question: According to the passage, a hidden cost of frequent meetings is that they:","options":["break the day into gaps too short for focused work","require expensive meeting rooms and equipment","make employees spend longer hours inside the room","prevent written agendas from being prepared in time"],"answer":0,"explanation":"Beyond the hours in the room, meetings fragment the day so that the gaps are too short for deep work — this is the cost the passage highlights.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-85","question":"Passage: Several countries have banned smartphones in school classrooms. Supporters argue that phones distract pupils, encourage cyberbullying and reduce the amount of face-to-face play during breaks. Early reports from some schools describe calmer classrooms and livelier playgrounds. Opponents counter that phones can be useful learning tools, that pupils need to learn self-control rather than have temptations removed, and that bans are hard to enforce. Both sides, however, often rely on anecdotes. Carefully designed studies comparing similar schools with and without bans are still few, and their results are mixed. Until more such evidence is available, the debate is likely to be settled by conviction rather than by data — which is perhaps not the best way to make decisions about children. Question: What is the author's main concern in the passage?","options":["That bans are always impossible for schools to enforce","That smartphones are the main cause of cyberbullying","That the debate rests more on belief than on solid evidence","That pupils should be allowed to use phones freely in class"],"answer":2,"explanation":"The author notes both sides rely on anecdotes and worries that the issue will be 'settled by conviction rather than by data'. He takes no side on the ban itself.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-86","question":"Passage: Many cities now require new buildings above a certain size to install rainwater harvesting systems. On paper the rule is admirable: rooftops collect water, which is filtered and channelled into tanks or into the ground to recharge aquifers. In practice, surveys in several cities have found that a large share of such systems do not work. Pipes are blocked by leaves, filters are never cleaned, and recharge pits fill with silt. The systems were installed to obtain a completion certificate, and nobody was responsible for them afterwards. The lesson extends beyond rainwater. Rules that demand a one-time installation, without anyone checking that the thing keeps working, tend to produce structures that exist mainly on paper. Inspection, not installation, is what turns a rule into a result. Question: The 'lesson' that 'extends beyond rainwater' is that:","options":["rules requiring one-time installation fail unless upkeep is checked","rainwater harvesting is an expensive mistake that cities should drop","all such building rules should be abolished as useless","completion certificates should be issued faster to reduce delays"],"answer":0,"explanation":"The author generalises: rules demanding only installation, with no one checking that systems keep working, produce structures that 'exist mainly on paper'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-87","question":"Passage: As summers grow hotter, the people most at risk are not those in air-conditioned offices but those who work outdoors — construction labourers, street vendors, farm workers and delivery riders. When the body cannot shed heat, it suffers exhaustion and, in severe cases, heatstroke, which can be fatal. Yet many of these workers are paid by the day or by the task, so resting in the afternoon means losing income. Some cities have started 'heat action plans', which shift working hours to cooler parts of the day, provide drinking water and shaded rest areas, and send warnings by phone when temperatures soar. Such plans cost little. Their success, however, depends on employers accepting that a worker's lost hour is cheaper than a worker's lost life. Question: Why, according to the passage, do many outdoor workers not rest during the hottest hours?","options":["Because they do not feel the heat as much as office workers","Because they are paid by the day or task and would lose pay","Because employers provide air-conditioned rest areas for them","Because heat action plans forbid resting during working hours"],"answer":1,"explanation":"The passage says many are paid by the day or by the task, 'so resting in the afternoon means losing income'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-88","question":"Passage: Urban planners rarely discuss public toilets, yet their absence shapes how half the population moves through a city. Men, however inconvenienced, can usually find somewhere to relieve themselves. Women often cannot, and many simply drink less water before leaving home or avoid long journeys altogether. Surveys in several Indian cities have found that the shortage of clean, safe and lit toilets is one reason women give for not taking up jobs far from home. A toilet may seem a trivial matter beside metro lines and flyovers. But a city that offers women fast trains and no toilets has offered them only half a journey. Planners who measure success by kilometres of track, and never ask who can actually use it, will keep missing this point. A few cities have begun to map toilets alongside bus stops, which is a modest but telling start. Question: The phrase 'only half a journey' implies that:","options":["metro lines cover only half the area of each city that they are built to serve","women travel only half as far as men do on a typical day","good transport is not enough if basic facilities women need are missing","women prefer shorter train rides to long journeys across the whole city"],"answer":2,"explanation":"The author argues that without toilets, women may avoid long trips despite good transport; transport without such facilities serves them only partially.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-89","question":"Passage: Most startups fail, and most founders know this when they begin. Studies of failed startups suggest that running out of money is rarely the real cause; it is the final symptom. More often, the company built a product that not enough people wanted, or kept spending on growth before finding out whether customers would stay. Founders who have failed once are sometimes more successful the second time, not because failure itself teaches, but because they reflect on what went wrong. Others repeat the same mistakes. A culture that treats failure as shameful discourages such reflection; a culture that celebrates failure uncritically can be just as unhelpful. What matters is what one learns, not merely that one has failed. A failure examined honestly is an education; a failure merely survived is only an expense. Question: The author's view of 'celebrating failure' is that:","options":["it encourages founders to keep spending until they run out of money","it is the main reason why founders' second startups tend to succeed","it is always better than treating failure as something shameful","it is unhelpful if uncritical; what matters is what one learns"],"answer":3,"explanation":"The author says celebrating failure 'uncritically can be just as unhelpful' as shaming it; 'what matters is what one learns'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-90","question":"Passage: Advertisements rarely lie outright; they do not need to. A shampoo is 'up to 70 per cent stronger' — stronger than what, and measured how? A biscuit contains 'goodness of wheat', a phrase that sounds healthy but promises nothing measurable. A juice is labelled 'no added sugar', which may be true even if it is naturally loaded with sugar. Such phrases work because readers fill in the gaps with what they want to believe. The advertiser has made no false claim, yet the buyer walks away with a false impression. Consumer protection laws are good at punishing lies; they are much weaker against carefully chosen words that mislead without lying. The careful reader's best defence is a simple question: compared with what, and measured how? Asked often enough, it empties many slogans of their magic. Question: According to the passage, why are consumer protection laws weak against such advertisements?","options":["Because the ads mislead without making any literally false claim","Because advertisers willingly pay the fines that the laws impose","Because such advertisements are rarely noticed by ordinary buyers","Because the laws do not cover food and personal-care products"],"answer":0,"explanation":"The passage says these phrases make 'no false claim' yet create a false impression; laws are 'good at punishing lies' but weaker against misleading wording.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-91","question":"Passage: A farmer with two cows cannot bargain with a large dairy company. On his own, he must accept whatever price the buyer offers, and if the milk is not sold by evening, it spoils. Dairy cooperatives changed this equation in many parts of India. Farmers pooled their milk at a village collection centre, where it was tested and paid for according to its fat content, and the cooperative owned the chilling plants, processing units and even the brands under which the milk was sold. Because the members owned the business, the profits that would otherwise have gone to middlemen came back to them. The model works only as long as members trust the management; where cooperatives were captured by local politicians, farmers drifted back to private buyers. Question: Which of the following conditions does the passage present as essential to the success of the cooperative model?","options":["Members' trust in the management","Support from local politicians","Every farmer owning many cows","Selling milk only to private buyers"],"answer":0,"explanation":"The passage says the model works 'only as long as members trust the management'; political capture drove farmers away, so political support is the opposite of the answer.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-92","question":"Passage: Sugarcane is one of the thirstiest crops a farmer can grow, needing far more water per hectare than pulses or millets. Yet it is widely grown in some of the driest districts of western India. The reason is not ignorance. Cane enjoys an assured market, because sugar mills are obliged to buy it at a price fixed by the government, and payment, though sometimes delayed, is reliable. Pulses and millets, by contrast, face volatile prices and uncertain buyers. A farmer choosing cane is therefore choosing security, even if the district's aquifers pay the price. Persuading him to switch will require offering a comparable security for less thirsty crops — through assured procurement, for example — rather than merely lecturing him about water. Question: The author suggests that farmers in dry districts grow sugarcane mainly because:","options":["it needs less water than pulses or millets do","they are unaware of how much water the crop needs","it offers an assured market and reliable payment","pulses and millets cannot be grown in dry districts"],"answer":2,"explanation":"The author explicitly rejects ignorance as the reason and points to the assured market and government-fixed price that give cane security.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-93","question":"Passage: Traditional remedies are often defended on the ground that they have been used for centuries. Long use, however, is not the same as proof. People recover from many illnesses on their own, and a remedy taken just before recovery will be credited with the cure. At the same time, it would be foolish to dismiss traditional knowledge wholesale. Some of the most important modern drugs, including treatments for malaria, were developed from plants long used by healers. The sensible course is neither blind faith nor blanket rejection, but testing: carefully controlled trials that show whether a remedy works better than a placebo, and at what dose it is safe. A remedy that passes such tests deserves respect, whatever its origin. Question: Which of the following best describes the author's approach to traditional remedies?","options":["Only remedies made from plants deserve to be tested scientifically","Traditional remedies should all be rejected simply because they are old","Traditional remedies are proven by their centuries of continued use","Each remedy should be judged by controlled tests, not by age or origin"],"answer":3,"explanation":"The author rejects both blind faith and blanket rejection and recommends controlled trials; a remedy that passes 'deserves respect, whatever its origin'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-94","question":"Passage: Have you ever tried to cancel an online subscription and found the button buried under five menus, while the button to subscribe glowed on the home page? Designers call such tricks 'dark patterns'. They include pre-ticked boxes that sign you up for newsletters, countdown timers that create false urgency, and pop-ups that ask 'Are you sure you want to miss this great offer?' in a tone that makes refusal feel foolish. None of these is illegal in most places, and each, taken alone, seems minor. Together, they shift countless small decisions in the company's favour. Regulators in several countries have begun to act, arguing that a choice made under deliberate confusion is not really a free choice at all. Companies reply that persuasion has always been part of selling. Question: The regulators' argument, as presented, rests on the idea that:","options":["all online subscriptions should be banned outright to protect users","consent obtained through deliberate confusion is not real consent","countdown timers on websites are always accurate and fair","users never read pop-up messages before clicking on them"],"answer":1,"explanation":"Regulators argue that 'a choice made under deliberate confusion is not really a free choice at all'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-95","question":"Passage: Every autumn, smoke from burning crop stubble drifts across the plains of north India and mixes with city pollution to produce a thick, choking haze. Farmers burn the straw because the gap between harvesting rice and sowing wheat is only a few weeks, and burning is the quickest and cheapest way to clear the fields. Machines that cut and mulch the straw exist, and governments subsidise them, but many small farmers find them too costly to hire at the busiest time of year. Fines have had limited effect, partly because enforcement in thousands of villages is impractical. Lasting solutions will probably involve making the straw worth something — as fuel for power plants or raw material for packaging — so that farmers profit from collecting it instead of burning it. Question: The author implies that fines have not solved the problem largely because:","options":["mulching machines are not subsidised by any government","farmers can easily afford to pay them out of their profits","burning straw is legally permitted during the harvest season","they are hard to enforce across a vast number of villages"],"answer":3,"explanation":"The passage says fines have had limited effect 'partly because enforcement in thousands of villages is impractical'. It states that machines are subsidised.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-96","question":"Passage: Many rich countries are ageing fast. As birth rates fall and people live longer, the share of the population above sixty-five keeps rising, while the share of working age shrinks. Fewer workers must support more pensioners, and health budgets swell. Some economists treat this as a looming catastrophe. Others are less alarmed. They point out that older people today are healthier than their parents were at the same age, and many could work longer if workplaces were more flexible. They add that automation may reduce the need for young workers in some sectors. The challenge, in their view, is real but manageable — provided that retirement ages, pension rules and attitudes towards older workers change in time. Delay, they warn, would turn a manageable problem into a crisis. Question: The economists who are 'less alarmed' believe that:","options":["ageing will have no real effect on pensions or health budgets","the problem can be managed if policies and attitudes adapt","birth rates in rich countries will soon rise sharply again","automation will make pensions for older people unnecessary"],"answer":1,"explanation":"They call the challenge 'real but manageable' provided retirement ages, pension rules and attitudes change in time.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-97","question":"Passage: On a clear day in the climbing season, long queues of climbers can be seen inching towards the summit of the world's highest mountain, each clipped to the same fixed rope. Many are paying clients with limited experience, guided by professional teams who carry their oxygen and fix their ropes. Critics say the mountain has become a tourist attraction, its slopes littered with abandoned tents and, tragically, the bodies of those who did not return. Defenders of commercial expeditions note that they provide a living for local guides and porters, and that the mountain has never belonged only to elite climbers. Both sides agree on one point: the queues themselves are dangerous, because climbers waiting at high altitude use up oxygen and strength they may need for the descent. Question: On which point do critics and defenders of commercial expeditions agree?","options":["Only elite climbers should be allowed on the mountain","Commercial expeditions should be banned","Queues near the summit are dangerous","Local guides earn too little"],"answer":2,"explanation":"The last sentence states that both sides agree the queues are dangerous because waiting at altitude drains oxygen and strength.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-98","question":"Passage: Nostalgia was once considered a disease. Seventeenth-century doctors described it as a dangerous homesickness that afflicted soldiers far from home, and some believed it could be fatal. Modern psychologists take a kinder view. Experiments suggest that recalling cherished memories tends to lift people's mood, increase their sense that life is meaningful and make them feel more connected to others. People often turn to nostalgic memories when they feel lonely or anxious, as if consulting a store of reassurance. Nostalgia is not always healthy, of course; a person who lives only in the past may fail to engage with the present. But in moderate doses, the psychologists conclude, looking back can help people move forward. The past, used well, is less a refuge than a resource. Question: Which statement best expresses the change in thinking described in the passage?","options":["Nostalgia is now seen as helpful in moderation, not as an illness","Nostalgia is now considered more dangerous than doctors once thought","Psychologists believe nostalgia should be avoided entirely by adults","Doctors still treat nostalgia as an illness, mainly among soldiers"],"answer":0,"explanation":"It moved from a 'disease' in the seventeenth century to something that, 'in moderate doses', helps people — a kinder modern view.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-99","question":"Passage: Procrastination is usually blamed on laziness or poor time management. Psychologists increasingly see it differently: as a way of managing unpleasant feelings. A task that makes us anxious, bored or afraid of failing produces discomfort, and putting it off brings immediate relief. The relief is real but short-lived, and the task, now closer to its deadline, becomes even more stressful, which makes us want to avoid it still more. This explains why simply buying a better planner rarely helps. More effective strategies address the feeling directly: breaking the task into a first step so small that it feels easy, or forgiving oneself for past delays, which, surprisingly, reduces future procrastination rather than encouraging it. The cure for avoidance, it seems, is kindness more than discipline. Question: According to the passage, why does buying a better planner rarely cure procrastination?","options":["Because tasks become easier as the deadline draws closer","Because good planners are too expensive for most students","Because procrastinators do not know how to use planners properly","Because it is driven by feelings rather than by poor scheduling"],"answer":3,"explanation":"If procrastination is a way of avoiding unpleasant feelings, a time-management tool does not address its cause — 'This explains why simply buying a better planner rarely helps.'","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-100","question":"Passage: Some large companies now use software to screen job applications before any human reads them. The programs learn from the profiles of past successful employees and rank new applicants by how closely they resemble those profiles. The approach is fast and appears neutral. But if the company's past hiring favoured certain groups — men for engineering roles, for instance — the software will learn to favour them too, and it will do so quietly, at a scale no biased human recruiter could match. Because the program's reasoning is often hidden even from its makers, such bias can go unnoticed for years. Experts recommend regular audits that test whether equally qualified applicants from different groups receive equal scores. Speed, they warn, is no virtue in a process that is quietly unfair. Question: The passage's main concern about hiring software is that it may:","options":["be slower than human recruiters at screening large numbers of CVs","reject every applicant who lacks an engineering degree","reproduce past biases on a large scale without being noticed","reveal its reasoning too openly to rejected applicants"],"answer":2,"explanation":"The software learns from past hiring; if that was biased, it repeats the bias 'quietly, at a scale no biased human recruiter could match', often unnoticed.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-101","question":"Passage: Every website now asks us to accept its cookies, and every app presents a privacy policy several thousand words long. In theory, this gives users control over their data. In practice, almost nobody reads these documents; a study once estimated that reading every privacy policy one encounters in a year would take weeks. Faced with constant requests, people click 'accept' simply to get on with what they were doing. Lawyers call this 'consent fatigue'. The result is a system in which companies can say that users agreed, and users can say that they never really understood. Some experts argue that the burden should shift: instead of asking people to protect themselves through endless clicks, laws should limit what companies may collect in the first place. Question: The experts mentioned at the end propose that:","options":["users should be legally required to read every privacy policy in full","the law should limit data collection instead of relying on consent","websites should stop using cookies entirely to protect privacy","privacy policies should be made longer and more detailed"],"answer":1,"explanation":"They argue the burden should shift from individual consent ('endless clicks') to legal limits on what companies may collect.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-102","question":"Passage: When heavy rain floods a city, the headlines usually blame the rain. A closer look often points elsewhere. Many cities were once dotted with lakes and tanks, linked by channels that carried excess water from one to the next. Over decades, these lakes were filled in for housing, bus stands and even sports stadiums, and the channels were covered or blocked. The water still flows where the land slopes, as it always did, but it now finds roads and basements instead of lakes. Engineers can build bigger drains, but no drain can match the capacity of the lakes that were lost. A city that forgets its own geography, as one planner put it, will be reminded of it by the next monsoon. Question: What is the significance of the planner's remark quoted at the end?","options":["A city that ignores its natural drainage will be flooded as a result","Monsoons are becoming heavier every single year because of climate change","Planners should be required to study geography at school","Cities should stop building drains, which cannot match lakes"],"answer":0,"explanation":"The remark means that a city which builds over its lakes and channels will be 'reminded' — by flooding — of the drainage it destroyed.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-103","question":"Passage: Kamla has been a potter for forty years, and her hands still move on the wheel with a speed her grandchildren cannot follow. Her water pots once sold by the hundred at the weekly market. Then came plastic buckets and steel vessels, and for a decade her wheel turned only for festival lamps. Recently, a city shop began buying her pots, calling them 'artisanal' and selling them at five times the price she receives. Kamla is pleased with the orders but puzzled by the word. 'They are the same pots,' she says, turning one over in her hands. 'Only now people buy them to look at instead of to use.' She says this without bitterness, but also without quite understanding why a pot should be more valuable when it holds no water. Question: Kamla's attitude towards the new demand for her pots is best described as:","options":["proud and boastful","angry and resentful","pleased but bemused","completely indifferent"],"answer":2,"explanation":"She is 'pleased with the orders but puzzled by the word' and speaks 'without bitterness' — pleased yet bemused, not resentful.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-104","question":"Passage: Why do people volunteer? The obvious answer is altruism — the wish to help others without reward. Surveys of volunteers suggest a more mixed picture. Many say they volunteer to meet people, to gain skills that look good on a résumé, or simply because a friend asked them. Some cynics conclude that volunteering is not truly selfless. That conclusion seems too harsh. Motives are rarely pure, in volunteering or anything else, and a person who teaches children to read partly to improve his own career still helps the children learn. Organisations that recognise the mix of motives, offering training, friendship and recognition alongside the chance to help, tend to keep their volunteers longer than those that appeal to selflessness alone. Question: The author's response to the 'cynics' is that:","options":["mixed motives do not cancel the real good done by volunteers","volunteers are always purely selfless, whatever the surveys may say","volunteering mainly helps the volunteers rather than others","organisations should appeal only to people's selflessness"],"answer":0,"explanation":"The author finds the cynics' conclusion 'too harsh': motives are rarely pure, but the children still learn. He recommends recognising mixed motives, not appealing to selflessness alone.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-105","question":"Passage: A study of judges deciding parole cases found something unsettling. Early in the morning and just after a food break, judges granted parole in a large share of cases; as the session wore on, the share fell steadily, then rose again after the next break. The cases were not arranged by difficulty. One explanation offered is 'decision fatigue': making many decisions in a row depletes mental energy, and a tired mind tends to choose the safe default — in this case, refusing parole. Some researchers have questioned the study's interpretation, suggesting that the order of cases was not as random as it appeared. Even so, the possibility that an important judgement might depend on the time since a snack has prompted many institutions to examine how decisions are scheduled. Question: Which of the following, if true, would most WEAKEN the 'decision fatigue' explanation?","options":["Judges themselves reported feeling increasingly tired late in each session of hearings","Cases heard just before breaks were mostly of prisoners with weaker records","The judges took regular food breaks at fixed times throughout each day","Other professions also make more cautious choices when tired"],"answer":1,"explanation":"If harder cases were scheduled just before breaks, the fall in parole grants could be explained by case order rather than fatigue — exactly the doubt some researchers raised. The other options are neutral or supportive.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-106","question":"Passage: Satellite images show that tree cover in some regions has increased over the past two decades. Officials cite these figures as proof that forests are recovering. Ecologists urge caution. A satellite sees a green canopy; it does not see what kind of trees form it. A natural forest with hundreds of species and a single-species plantation of fast-growing eucalyptus may look much the same from space. Yet the plantation supports far fewer birds and insects, often uses more water, and can be cut down within a few years. Counting both as 'tree cover' can therefore hide the loss of natural forest behind the growth of plantations. Good statistics, the ecologists argue, must measure not only how much is green but what that green actually is. Question: Which of the following would the ecologists most likely regard as the WEAKEST evidence of forest recovery?","options":["A recovery of native tree species in previously cleared patches","A rise in the number of bird species recorded in ground surveys","An increase in the area of mixed native woodland confirmed on the ground","A rise in total green canopy measured only by satellite"],"answer":3,"explanation":"The ecologists' point is that satellite canopy figures cannot distinguish plantations from natural forest. The other options measure biodiversity or native species directly.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-107","question":"Passage: For decades, the departure of skilled graduates to rich countries was described as a 'brain drain', a loss of talent that poorer nations could ill afford. The picture has become more complicated. Many emigrants send money home, invest in businesses there, and, thanks to cheap travel and the internet, collaborate with colleagues in their home country. Some return after years abroad, bringing skills and contacts they could not have acquired at home. Economists now speak of 'brain circulation'. Yet the old concern has not vanished. A small country that loses most of its doctors may gain remittances but still be left without anyone to treat its sick. Whether migration is a drain or a circulation may depend less on the migrants than on what is left behind. Question: The final sentence implies that the effect of emigration depends largely on:","options":["how much money the emigrants earn and send home from abroad","whether the home country keeps enough capacity in essential services","whether emigrants use the internet to stay in touch","how many years emigrants choose to stay in rich countries before returning"],"answer":1,"explanation":"The example of a country losing its doctors shows that remittances cannot compensate for missing essential capacity; hence it depends on 'what is left behind'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-108","question":"Passage: Community radio stations broadcast to an area of a few kilometres, run by and for the people who live there. Their programmes rarely sound polished. A farmer may explain how he dealt with a pest; schoolchildren may read their own poems; a local health worker may answer questions about vaccination in the dialect of the village. Commercial and national broadcasters, aiming at large audiences, cannot afford such narrow content. That narrowness is exactly the point. Listeners trust a voice they recognise, speaking about problems they share, more than an expert from a distant city. The stations struggle financially, since they may carry only limited advertising, and their survival often depends on grants. Yet their value cannot easily be measured in listeners per rupee. Question: The sentence 'That narrowness is exactly the point' is used to suggest that:","options":["the local focus that limits the stations' reach is what gives them value","community radio should try harder to reach larger, regional audiences instead","narrow content is a weakness that the stations should correct","commercial broadcasters now copy community radio's local style"],"answer":0,"explanation":"What looks like a limitation (narrow, local content) is what makes listeners trust and value the stations — a deliberate reversal.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-109","question":"Passage: Cleaning sewers by hand is banned by law, yet deaths of workers inside manholes are still reported every year. Contractors find it cheaper to send a man down a drain with a rope than to hire a suction machine, and the workers, often from communities long confined to such jobs, have few alternatives. Machines alone will not end the practice. Unless the workers are offered other dignified livelihoods, many will continue to take dangerous jobs from unscrupulous contractors; and unless contractors face certain punishment, the law will remain a sheet of paper. The problem, in short, is as much social and economic as it is technical. Treating it as a matter of buying equipment risks declaring victory while men continue to die. Question: Which of the following statements would the author most likely reject?","options":["The problem has social and economic as well as purely technical dimensions","Workers need other dignified livelihoods for the ban to work","Contractors who break the law must face certain punishment","Supplying cleaning machines is by itself enough to end manual cleaning"],"answer":3,"explanation":"The author says 'Machines alone will not end the practice' and warns against treating it as a matter of buying equipment. The other three are positions he holds.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-110","question":"Passage: Relocating villages out of tiger reserves is among the most contested policies in conservation. Supporters point out that tigers need large undisturbed areas and that villagers inside reserves often live without roads, schools or hospitals; well-funded relocation can offer families land, housing and services they never had. Critics reply that 'voluntary' relocation is not always voluntary when facilities are withdrawn from those who stay, and that some communities have lived alongside wildlife for generations without harming it. Both arguments contain truth. The outcome depends heavily on process: whether families are genuinely consulted, whether compensation is fair and paid on time, and whether the new site has fertile land and water. A relocation that fails on these counts helps neither the tiger nor the people. Question: The critics' use of quotation marks around 'voluntary' suggests that:","options":["villagers always want to leave reserves for better services","relocation is always carried out by force by the police","relocation may come from indirect pressure, not free choice","the word is used in its strict legal sense under forest law"],"answer":2,"explanation":"Scare quotes signal doubt: when facilities are withdrawn from those who stay, the choice to leave is pressured, so it is not truly voluntary.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-111","question":"Passage: Committees are often formed in the belief that many minds produce better decisions than one. Sometimes they do. But a group of like-minded people, especially one led by a strong chairperson, can fall into 'groupthink': members suppress doubts to preserve harmony, assume that silence means agreement, and grow more confident as each voice echoes the last. Disastrous decisions in business and government have been traced to such dynamics. Remedies are known. A leader can speak last rather than first, so as not to anchor the discussion; one member can be asked to argue the opposite case; and outsiders can be invited to review the plan. None of these is costly. What they require is a leader secure enough to welcome disagreement. Question: Why might a leader be advised to speak last rather than first?","options":["To save time by summing up the discussion in meetings","To avoid swaying others' views before they have voiced them","Because the leader's own view matters least to the rest of the group","To ensure that the group reaches agreement more quickly"],"answer":1,"explanation":"Speaking first would 'anchor the discussion' — members would align with the leader. Speaking last lets independent views surface, which counters groupthink.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-112","question":"Passage: Gene-editing tools now allow scientists to make precise changes in a plant's own DNA — switching off a gene that makes a crop vulnerable to disease, for example — without introducing genes from other species. Supporters argue that such crops differ from older genetically modified crops and should be regulated like conventionally bred varieties, since the same change could, in principle, arise naturally. Opponents fear that relaxed rules will let large companies patent seeds and tighten their hold over farmers. Notice that the two sides are arguing about different things. One debate concerns biological safety; the other concerns economic power. Settling the first will not settle the second, and a sensible policy must address both. Each side would do well to answer the other's actual question. Question: The author's main point in the last three sentences is that:","options":["large companies should be banned from selling patented seeds to small farmers","gene-edited crops have been proven definitely safe to eat","two separate questions, scientific and economic, are being argued as one","opponents of gene editing simply misunderstand the science"],"answer":2,"explanation":"The author separates the biosafety debate from the debate about corporate power and says resolving one will not resolve the other.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-113","question":"Passage: Diaries are among the most valuable sources a historian can find, precisely because they were not written for historians. A government report presents events as officials wished them to be seen; a memoir is shaped by the author's later knowledge and reputation. A diary, written day by day, records what a person thought before he knew how things would turn out. Its errors are as revealing as its insights: a diarist who confidently predicts a quick victory in a war that drags on for years shows us what people actually believed at the time. Yet diaries have their own biases. Most were kept by the literate and the leisured, and their writers, too, sometimes imagined a future reader. A diary, like any source, must be read with sympathy and suspicion at once. Question: Why, according to the passage, are a diarist's mistaken predictions valuable to historians?","options":["They reveal what people genuinely believed before events unfolded","They show that most diarists were poorly informed about the events around them","They are more accurate than official government reports","They help historians predict how future events will unfold"],"answer":0,"explanation":"A wrong prediction made in the moment shows 'what people actually believed at the time', unclouded by hindsight.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-114","question":"Passage: In Hindustani music, a gharana is a lineage of musicians who share a distinctive style passed down from teacher to student. For generations, students learned by living with their guru, absorbing not only techniques but an entire way of approaching music. Some critics argue that this system preserved excellence but also discouraged innovation; a student who strayed too far from the gharana's style risked being called disloyal. Others counter that the great innovators of the tradition were themselves products of rigorous gharana training, and that one must master a language before one can say something new in it. Today, with recordings and online lessons, students often learn from many sources at once. Whether this produces richer music or merely shallower musicians remains an open question. Question: The counter-argument presented by 'others' is that:","options":["innovation in music is always a form of disloyalty to the guru","gharanas should be abolished to make room for innovation","online lessons are superior to traditional gharana training","mastering a tradition is the foundation of real innovation"],"answer":3,"explanation":"They say great innovators came from rigorous gharana training and that 'one must master a language before one can say something new in it'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-115","question":"Passage: A hospital in one city recently began publishing the waiting time for each of its departments on a public website, updated every hour. The aim was transparency. Within months, average waiting times had fallen sharply. Part of the improvement was genuine: managers, embarrassed by long published waits, moved staff to the busiest departments. But part was not. Some departments began registering patients only when a doctor was about to see them, so that the time spent waiting before registration no longer counted. A measure, once it becomes a target that people are judged by, tends to change the behaviour it was meant to record. The published figures improved faster than the patients' actual experience did. The hospital later began auditing registration times as well, and the gap narrowed. Question: Which of the following situations best illustrates the principle stated in the second-last sentence?","options":["A factory installs a faster new machine and its output rises steadily as a result","Teachers judged by pass rates discourage weak students from sitting the exam","A shop lowers its prices and its monthly sales increase","A city plants trees along its streets and summer temperatures fall"],"answer":1,"explanation":"The principle is that a measure used as a target distorts behaviour; discouraging weak students improves pass rates without improving learning. The other options describe genuine improvements.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-116","question":"Passage: Most of the apps on our phones cost nothing to download. They are free in the sense that no money changes hands, but they are not free to run. The companies behind them earn their revenue by selling advertisers access to our attention, and the more time we spend scrolling, the more they earn. This creates a powerful incentive to design apps that are hard to put down: endless feeds with no natural stopping point, notifications timed to pull us back, and recommendations tuned to whatever keeps us watching. None of this requires any conspiracy; it follows naturally from the business model. As the saying goes, when a product is free, you are not the customer — you are what is being sold. Question: Which of the following is the author's main point?","options":["The free-app business model, not a plot, drives apps to capture attention","App companies secretly conspire with one another to keep users hooked","Advertising on phones should be banned to protect users' time and attention","Users are the paying customers of free apps, not their product"],"answer":0,"explanation":"The author says the attention-maximising design 'follows naturally from the business model' and explicitly denies a conspiracy. The saying at the end says users are the product, not the customer.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-117","question":"Passage: Commercial aviation is one of the safest ways to travel, and one reason is the way the industry treats mistakes. When pilots make an error or notice a near miss, they are encouraged to report it, and in many systems such voluntary reports cannot be used to punish them. Investigators study every serious incident, publish their findings, and airlines around the world change their procedures in response. The goal is not to find someone to blame but to find out why the system allowed the error. Hospitals, by contrast, have often treated errors as personal failures to be hidden for fear of lawsuits or disgrace. Many experts believe that medicine could save thousands of lives by borrowing aviation's approach, though change has been slow. Question: The author's argument assumes that:","options":["hospitals already publish all their errors in the same way as airlines","pilots are by nature more careful and make fewer mistakes than doctors","errors are reported and fixed more readily when reporting is not punished","lawsuits against doctors improve safety in hospitals over time"],"answer":2,"explanation":"The argument links non-punitive reporting to learning and safety, and suggests hospitals' fear of blame hides errors. It does not claim pilots are naturally more careful.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-118","question":"Passage: To obtain a certificate stating that he was alive, the pensioner was told to bring proof of his existence. He offered himself. The clerk examined him carefully, consulted a thick file and explained, with genuine regret, that a man standing at the counter was not among the documents listed in the circular. What was required was a letter from a gazetted officer certifying that he had seen the pensioner alive. The pensioner pointed out that the clerk had just seen him alive. The clerk agreed that this was so, but he was not a gazetted officer, and in any case his seeing was not on the list. The pensioner went home, found an officer, and returned a week later, by which time the circular had been revised. Question: The tone of the passage is best described as:","options":["bitterly angry","gently satirical","solemn and tragic","neutral and technical"],"answer":1,"explanation":"The absurd logic (a living man is not valid proof of being alive), the clerk's 'genuine regret' and the final twist mock bureaucracy lightly, without rage or tragedy.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-119","question":"Passage: Millions of rural households still cook on stoves that burn wood, dung or crop waste. The smoke, inhaled daily by women and children in poorly ventilated kitchens, causes lung disease and is linked to many premature deaths. Programmes that supplied subsidised gas connections reached tens of millions of homes. Yet surveys found that many beneficiaries continued to use their old stoves for much of their cooking. A refill cylinder costs money, while wood can be gathered free; some families also preferred the taste of food cooked on a traditional fire. Providing a connection, it turned out, was the easier half of the task. The harder half is making the cleaner fuel the everyday choice rather than an occasional one, and that depends on price as much as on persuasion. Question: Which of the following, if true, would best support the author's distinction between the 'easier' and 'harder' halves of the task?","options":["Some urban families with gas connections also still cook with wood","The number of gas connections issued rose steadily every single year","Gas stoves are cheaper to manufacture than traditional clay stoves","Connected households bought far fewer refills than full-time use needs"],"answer":3,"explanation":"Low refill purchases show that connections (the easy half) did not translate into regular use (the hard half). Rising connection numbers concern only the easy half.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-120","question":"Passage: A census is often imagined as a simple count, but counting a billion people is anything but simple. Enumerators must reach remote hamlets, urban slums and people with no fixed address, such as migrant workers and the homeless. Some households are suspicious and give false answers, fearing that the information will be used against them; others are counted twice because family members are listed both where they live and where they work. Questions that seem straightforward, such as a person's occupation or language, can be answered in hundreds of ways. Census data therefore contain errors, and statisticians spend years estimating and correcting them. A census is less a photograph of a country than a carefully restored painting, faithful to the original but touched up by expert hands. Question: The comparison in the last sentence suggests that census data are:","options":["too damaged by errors to be of any real use","a perfectly accurate snapshot of the whole population","a work of imagination with little basis in actual fact","a careful reconstruction corrected for known errors"],"answer":3,"explanation":"A restored painting is a real original that experts have carefully corrected; likewise census data are real counts corrected for errors — not a perfect snapshot, nor fiction.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-121","question":"Passage: When the sea threatens a coastal town, the instinct is to build a wall. Seawalls do protect what lies directly behind them, but they often make matters worse elsewhere. Waves that once spent their energy on a sloping beach strike the wall and rebound, scouring away the sand in front of it; the beach narrows and eventually disappears. The sand that would naturally have drifted along the coast is trapped, so neighbouring beaches, deprived of supply, begin to erode in turn, and their residents demand walls of their own. Some engineers now favour 'soft' defences — restoring dunes, mangroves and reefs that absorb wave energy. These are slower to establish and less dramatic to inaugurate, which may explain why politicians prefer concrete. Question: The author's remark about politicians in the last sentence is best described as:","options":["praise for politicians' knowledge of coastal engineering","a factual report of a recent government decision","a mildly cynical explanation for the preference for seawalls","a recommendation that politicians build more and higher walls"],"answer":2,"explanation":"Suggesting that walls are chosen because they are quick and 'dramatic to inaugurate' implies political image matters more than effectiveness — a mildly cynical aside.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-122","question":"Passage: In some countries, a large share of young people learn a trade through apprenticeships: they spend part of the week in a company and part in a vocational school, earning a modest wage while they train. Employers help write the curriculum, so the skills taught are the ones actually needed. Youth unemployment in such countries tends to be low. Other countries, impressed by these results, have tried to copy the model, often with disappointing results. The reason is that apprenticeships depend on things that cannot be imported quickly: employers willing to invest in training workers who might later leave, industry bodies that certify standards, and a society that regards a skilled trade as a respectable career rather than a second-best option for those who failed academically. Question: Which of the following can be inferred from the passage?","options":["An apprenticeship system's success depends partly on how society views trades","Countries that copy apprenticeship systems usually succeed within a few years","Apprentices are not paid anything during their years of training","Employers have no role in designing what apprentices are taught"],"answer":0,"explanation":"The passage lists 'a society that regards a skilled trade as a respectable career' among the things that cannot be quickly imported. It says apprentices earn a wage and employers help write the curriculum.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-123","question":"Passage: Feeding pigeons is, for many city dwellers, an act of kindness and even piety. Grain is scattered at crossroads and outside temples every morning, and the birds gather in thousands. Doctors, however, have raised concerns. Dried pigeon droppings and feathers can cause a serious lung disease in susceptible people who breathe them in over long periods, and residents of buildings near feeding spots have reported higher rates of breathing problems. Some city authorities have tried to restrict feeding, provoking angry protests. Both sides speak the language of care — for the birds on one hand, for human health on the other. A workable compromise might move feeding to open spaces away from homes, rather than banning it outright, since bans that offend deeply held beliefs are rarely obeyed. Question: The author favours relocating feeding spots rather than banning feeding mainly because:","options":["pigeon droppings become harmless once they are in open spaces","bans that clash with deeply held beliefs are rarely obeyed","feeding pigeons has no real religious meaning for most people","doctors themselves support unrestricted feeding of pigeons"],"answer":1,"explanation":"The author says a ban is less workable 'since bans that offend deeply held beliefs are rarely obeyed'. The passage does not say droppings become harmless.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-124","question":"Passage: Fireworks during festivals are often blamed for the smog that blankets north Indian cities in early winter. The truth is more complicated. Studies show that fireworks cause sharp spikes in pollution for a few hours, sometimes pushing particle levels to many times the safe limit. But the season's persistent smog has larger, steadier sources: vehicle exhaust, construction dust, industrial emissions and crop burning in neighbouring states, all trapped near the ground by cold, still air. Banning fireworks therefore brings only modest relief to the season's average pollution, while provoking resentment among those who see the ban as an attack on their traditions. This does not mean fireworks are harmless; the short spikes can trigger asthma attacks. It means they are the most visible culprit, not the biggest. Question: Which of the following statements is NOT supported by the passage?","options":["Short pollution spikes from fireworks can trigger asthma attacks","Fireworks cause sharp but short-lived spikes in particle pollution","Cold, still air traps the season's pollutants near the ground","Banning fireworks would solve most of the season's smog problem"],"answer":3,"explanation":"The passage says a ban brings 'only modest relief' because fireworks are 'the most visible culprit, not the biggest'. The other three statements are stated in the passage.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-125","question":"Passage: At a country fair in the early twentieth century, visitors were invited to guess the weight of an ox. Individual guesses varied widely, and few were close. Yet when the guesses were averaged, the result came remarkably near the true weight. The episode is often cited to show that crowds can be wise. The effect, however, depends on conditions that are easily lost. The guessers must judge independently, each using his own information; if they hear one another's guesses or follow a confident leader, their errors stop cancelling out and begin to reinforce one another. A crowd of independent thinkers can be wiser than its smartest member. A crowd that echoes itself is merely a louder version of its loudest voice. Question: Which of the following situations would the author expect to produce the LEAST accurate average estimate?","options":["Strangers in different cities submit their guesses online independently","Each person writes a guess privately without seeing anyone else's guess","Members announce guesses in turn after a respected expert has spoken first","Participants with varied backgrounds guess without discussing the question"],"answer":2,"explanation":"The author says accuracy depends on independence; when people hear others or follow a confident leader, errors reinforce one another. Announcing guesses after an expert speaks destroys independence.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-126","question":"Passage: Our bodies keep time by light. Bright morning light, rich in blue wavelengths, tells the brain's internal clock that the day has begun, sharpening alertness; dimmer, warmer light in the evening allows the hormone that promotes sleep to rise. Many offices, however, are lit with the same flat light from morning till night, and many homes are lit brightly — and screens glow blue — until bedtime. Some researchers suspect that this confusion contributes to poor sleep and low daytime energy. A few companies have installed lighting that changes colour and intensity through the day. Early studies report modest improvements in sleep and mood, though the evidence is still limited. The cheapest remedy, the researchers note, is simply to spend time outdoors in the morning. Question: The author's attitude towards colour-changing office lighting is best described as:","options":["cautiously open: encouraging results, but not yet conclusive","strongly enthusiastic: it is a proven cure for poor sleep","dismissive: studies have shown it to be useless for workers","hostile: it disturbs workers' body clocks and harms health"],"answer":0,"explanation":"The author reports 'modest improvements' while noting that 'the evidence is still limited', and adds that a cheaper remedy exists — a cautious, open stance.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-127","question":"Passage: Second-hand markets are booming. Apps make it easy to sell a used phone, a sofa or a school uniform, and buyers increasingly see pre-owned goods not as a sign of poverty but as a sensible, even fashionable, choice. Environmentalists welcome the trend, since every item reused is one fewer item manufactured. There is a catch, however. Some studies suggest that knowing an item can be resold encourages people to buy new things more often, confident that they can recover part of the cost. If that is so, a thriving resale market could end up increasing total consumption rather than reducing it. The environmental benefit of reuse, in other words, depends not only on what happens to old goods but on how the possibility of reuse changes what people buy. Question: Which of the following best expresses the 'catch' described in the passage?","options":["Second-hand goods are usually of poor quality and wear out too fast to be worth it","Easy resale may lead people to buy new goods more often, offsetting reuse","Second-hand markets are declining as new goods get cheaper","Environmentalists oppose second-hand markets for encouraging waste"],"answer":1,"explanation":"The catch is that resale value may prompt more frequent new purchases, so total consumption could rise. Environmentalists in fact welcome the trend.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-128","question":"Passage: Parents and teachers are often told to praise children. But the kind of praise matters. In a series of experiments, children who were praised for being clever after solving puzzles tended, when offered a choice, to pick easier puzzles next time, as if to protect their reputation. Those praised for their effort more often chose harder ones and persisted longer when they struggled. The researchers argued that praising intelligence teaches children that ability is fixed, so failure becomes a threat; praising effort teaches them that ability grows, so failure becomes information. Later studies have found the effect smaller than first reported, and critics warn against empty praise for effort that achieves nothing. Still, the underlying idea — that what we praise shapes what children value — has proved durable. Question: According to the passage, why did children praised for being clever tend to choose easier puzzles?","options":["To avoid failures that might threaten their image as clever","Because easier puzzles earned them more praise for their effort","Because they lacked the ability to solve harder puzzles","Because the researchers had told them to pick easier ones"],"answer":0,"explanation":"They chose easier puzzles 'as if to protect their reputation'; if ability is seen as fixed, failure threatens the 'clever' label.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-129","question":"Passage: For thousands of years, many indigenous communities managed forests and grasslands with deliberate, small fires lit in the cool season. These low-intensity burns cleared dry undergrowth, encouraged fresh grass for grazing animals and created patches that stopped later fires from spreading. Colonial and modern forest departments often banned such burning, regarding all fire as destructive. In several regions, the result was the opposite of what was intended: dry fuel accumulated year after year until a single spark in the hot season set off a fire too intense to control. Some fire services are now working with indigenous elders to revive controlled burning. The episode is a reminder that a practice which looks harmful in isolation may serve a purpose within a larger system. Question: Which of the following situations is most similar in principle to the one described in the passage?","options":["A shop cuts its prices and sells far more units in the following month","Suppressing every minor fever stops the body clearing an infection itself","A school extends its teaching hours and its exam results steadily improve","A farmer buys a tractor and ploughs his fields much faster than before"],"answer":1,"explanation":"The passage's principle is that eliminating something that looks harmful (small fires) disrupts a larger system and leads to a worse outcome. Suppressing every fever, which is part of the body's defence, follows the same logic; the other three are simple actions that achieve their intended result.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-130","question":"Passage: Proposals to link India's rivers by a network of canals, carrying surplus water from flood-prone basins to drought-prone ones, have been discussed for decades. The appeal is obvious: one region drowns while another thirsts. Critics raise several objections. The idea of 'surplus' water ignores the role that floodwater plays in replenishing wetlands, carrying silt to deltas and pushing back seawater at river mouths. Huge canals and reservoirs would displace many people and submerge forests. And the costs, both financial and ecological, may be far higher than estimated. Supporters reply that doing nothing also has costs, measured in failed harvests and migrations. What both sides share, perhaps, is a recognition that water decisions made today will bind generations who have no voice in them. Question: Critics object to calling floodwater 'surplus' because:","options":["drought-prone regions do not actually need any more water","floods never really occur in India's river basins","floodwater performs important natural functions downstream","canals cannot carry large volumes of water over long distances"],"answer":2,"explanation":"Critics say the idea of surplus 'ignores the role that floodwater plays' in wetlands, silt deposition and holding back seawater.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-131","question":"Passage: Delivery companies are testing drones to carry parcels over the last few kilometres to customers. Supporters picture medicines reaching remote villages in minutes and city streets freed of delivery vans. The early trials have been impressive for small, light, urgent items such as blood samples. For ordinary shopping, the arithmetic is less kind. A drone carries one small parcel at a time, needs recharging, cannot fly in heavy rain or strong wind, and must land somewhere safe — not easy in a crowded apartment block. A van, by contrast, carries hundreds of parcels in a single trip. Drones may therefore transform a few specialised kinds of delivery long before they make any difference to the everyday flow of packages. Enthusiasm, in short, has outrun arithmetic. Question: Which of the following best summarises the author's assessment of delivery drones?","options":["Held back mainly by legal restrictions rather than practical problems","Already more efficient than vans for all kinds of deliveries","Useless for every kind of delivery, even urgent medical ones","Useful for small urgent items but no near-term substitute for vans"],"answer":3,"explanation":"The author calls trials impressive for small, urgent items but says that for ordinary shopping 'the arithmetic is less kind' (one parcel, weather, landing). Legal issues are not discussed.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-132","question":"Passage: Many museums in Europe hold objects that were taken from other countries during colonial rule — sculptures, manuscripts, even sacred relics. Countries of origin increasingly ask for them back. Museums have offered several arguments for keeping them: that the objects were acquired legally under the laws of the time, that they are better preserved where they are, and that a great museum shows the cultures of the whole world to millions of visitors. Each argument has weakened. Laws made by colonial powers can hardly settle the rights of the colonised; many countries of origin now have excellent museums; and the 'whole world' argument sounds odd when the world in question cannot easily obtain a visa to visit it. A number of museums have begun to return items, sometimes after decades of refusal. Question: The author's remark about obtaining 'a visa' is intended to:","options":["show that museums are especially popular with tourists from many countries","argue that museums should issue visas to their foreign visitors","note that people from source countries struggle to reach these museums","suggest that travel restrictions help protect fragile objects"],"answer":2,"explanation":"The irony is that a museum claiming to display the world's cultures to everyone is hard to reach for people from the very countries whose objects it holds.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-133","question":"Passage: Crop insurance is meant to protect farmers from ruin when drought or floods destroy their harvests. Under many schemes, the farmer pays a small premium and the government pays the rest. Yet farmers' complaints are persistent: claims are settled months or even years late, and the amount paid often bears little relation to the loss suffered. The problem lies partly in how losses are measured. Rather than inspecting each field, insurers estimate yields from sample plots in a whole area. A farmer whose crop was wiped out may receive little if the sample plots in his area fared well. Timely, accurate assessment — using satellites, drones and quicker field checks — could do more to restore farmers' faith in insurance than any increase in the subsidy. Question: Which of the following, if true, would most strengthen the author's conclusion?","options":["The government recently increased its share of the premium for farmers","Where loss assessment became faster and more precise, renewals rose sharply","Most farmers do not actually know what an insurance premium is or how it works","Sample plots in each area are chosen by local officials"],"answer":1,"explanation":"The author argues that better assessment would restore faith more than higher subsidies. Evidence that faster, accurate assessment raised renewals directly supports this. A subsidy increase alone says nothing about trust.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-134","question":"Passage: The government announces minimum support prices for many crops, but for decades it has bought large quantities mainly of rice and wheat. Farmers have responded rationally. In regions with assured procurement, they grow these two crops year after year, even where the soil and water are better suited to pulses, oilseeds or millets. The result is a paradox: the country builds up huge stocks of rice and wheat, sometimes more than its storage can hold, while importing pulses and edible oils. Depleted groundwater and soil fatigue add to the cost. A price support that was meant to give farmers security has come to shape what they grow, and not always wisely. Reformers argue that procurement should be widened to other crops, so that security no longer depends on growing only two. Question: The 'paradox' described in the passage is that:","options":["excess rice and wheat pile up while pulses and edible oils are imported","farmers grow pulses in regions where rice would be better suited","procurement prices for rice and wheat are kept lower than open-market prices","the government refuses to buy any of the rice and wheat grown"],"answer":0,"explanation":"The passage calls it a paradox that huge rice and wheat stocks pile up while pulses and edible oils are imported — a direct consequence of procurement policy.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-135","question":"Passage: Cricket was long a game of instinct and tradition. Captains set fields by feel, and selectors trusted their eyes. Today, every ball in a professional match is tracked and recorded, and analysts can tell a captain where a particular batsman scores most of his runs against left-arm spin in the final overs. Teams that use such data have gained clear advantages in planning. Yet the numbers have limits. They describe what has happened, often in conditions that will not repeat exactly, and they struggle to capture pressure, form and the mood of a dressing room. The best captains, many former players argue, use data to sharpen their judgement, not to replace it. A spreadsheet can suggest a field; it cannot read a batsman's nerves. Question: The author's view of data in cricket is that it:","options":["captures pressure and form better than players can","has made the role of captains largely unnecessary","is of no practical use to professional teams","is a valuable aid but no substitute for judgement"],"answer":3,"explanation":"The author grants that data gives 'clear advantages' but stresses its limits; the best captains use it 'to sharpen their judgement, not to replace it'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-136","question":"Passage: When a phone's battery fails, many owners discover that it cannot be replaced without special tools, or that the manufacturer will not sell spare parts to independent repair shops. Buying a new phone becomes the easiest option. The 'right to repair' movement argues that consumers should be able to fix what they own, or have it fixed by anyone they choose, at a fair price. Manufacturers respond that sealed designs make devices thinner and more water-resistant, and that unqualified repairs can compromise safety and data security. Some governments have begun to require that spare parts and repair manuals be made available for a number of years. Supporters see this as a victory for both consumers and the environment, since every repaired device postpones the need to manufacture a new one. Question: Which of the following is NOT one of the manufacturers' arguments as presented in the passage?","options":["Sealed designs make devices thinner","Repaired devices harm the environment more than new ones","Sealed designs improve water resistance","Unqualified repairs can compromise safety and data security"],"answer":1,"explanation":"Manufacturers cite thinness, water resistance, safety and data security. The environmental argument in the passage belongs to the supporters, and runs the other way.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-137","question":"Passage: When seat belts were made compulsory, some economists made a surprising prediction: drivers who felt safer might drive faster and less carefully, partly cancelling the benefit. This idea, called risk compensation, has since been studied in many settings. Cyclists who wear helmets, some studies suggest, are passed more closely by motorists; children wearing protective gear may play more roughly. The evidence is mixed, and in the case of seat belts the overall effect on deaths remained strongly positive. But the idea carries a useful warning. Safety measures change behaviour, and their real effect depends on how people respond to feeling safe, not merely on the protection they provide in an accident. Designers of safety rules ignore human psychology at their peril. Question: Which of the following would be the best example of risk compensation?","options":["A city installs speed cameras on main roads and road accidents fall sharply","A driver wears a seat belt and continues to drive carefully","Hikers with satellite phones try riskier routes, expecting easy rescue","A cyclist gives up riding altogether after a bad accident"],"answer":2,"explanation":"Risk compensation means people take more risks because they feel safer. Hikers attempting dangerous routes because rescue seems easy fit exactly; the other options show no such offsetting behaviour.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-138","question":"Passage: Satellite maps of many Indian cities reveal a striking pattern: wealthy neighbourhoods are green with trees, while crowded poorer areas are almost bare. The difference is not merely cosmetic. Trees shade streets and roofs, lowering temperatures by several degrees during heatwaves; they absorb some pollutants and reduce flooding by slowing rainwater. Residents of treeless areas, who often live in small, poorly ventilated homes and work outdoors, therefore bear more of the heat and pollution while having fewer means of escaping it. Planting drives often favour parks and highways, where space is easy to find, rather than dense neighbourhoods where it is scarce. Greening the city, the author suggests, must also mean greening it fairly. A shady avenue in a rich suburb is pleasant; a shady lane in a crowded colony can be life-saving. Question: The phrase 'greening it fairly' implies that:","options":["planting should favour treeless areas that suffer most from heat","all neighbourhoods should receive exactly the same number of trees","trees should be removed from wealthy areas to be planted elsewhere","parks and highways need more trees than residential areas"],"answer":0,"explanation":"The passage shows poorer, treeless areas bear more heat and pollution, while planting drives favour easy sites; fairness means directing greening to those who need it most.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-139","question":"Passage: Meat grown from animal cells in steel tanks, without raising or slaughtering animals, has moved from science fiction to the tasting table. Its supporters argue that it could cut the land, water and greenhouse gases used by livestock farming, and end the suffering of animals raised for food. Sceptics raise practical doubts. The nutrients in which the cells grow are expensive, the tanks must be kept free of contamination, and producing meat on a large scale requires enormous amounts of energy, whose source will determine whether the climate benefit is real. There are cultural doubts, too: many consumers are uneasy about food made in factories, however natural its ingredients. The technology may succeed, but its success will depend as much on cost and trust as on science. Question: According to the passage, whether lab-grown meat actually benefits the climate depends partly on:","options":["whether the meat is sold in supermarkets or restaurants","how many animals consumers continue to keep as pets","how its taste compares with that of ordinary meat","the source of the large amount of energy it needs"],"answer":3,"explanation":"The passage says large-scale production needs enormous energy, 'whose source will determine whether the climate benefit is real'.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-140","question":"Passage: When an online encyclopaedia that anyone can edit was launched, teachers warned students not to trust it. How could a work written by anonymous volunteers be reliable? Over the years, the warnings softened. Studies comparing selected articles with those in established encyclopaedias found the error rates broadly similar for many scientific topics, and errors in popular articles were often corrected within minutes. Weaknesses remain: obscure articles may go unchecked for long periods, and articles on contested political subjects can become battlegrounds. The best advice to students now is not to avoid the site but to use it as a starting point, following its references to the original sources — which is, in fact, how a good student should use any encyclopaedia. Question: The final clause, 'which is, in fact, how a good student should use any encyclopaedia', serves to:","options":["show that the advice is a general rule of good research, not a special one","argue that traditional printed encyclopaedias are now useless for students","suggest that students should never read any encyclopaedia at all","claim that the online encyclopaedia has no remaining weaknesses"],"answer":0,"explanation":"It reframes the advice as standard practice for all reference works, implying the online encyclopaedia need not be treated as uniquely suspect. The passage itself lists its weaknesses.","difficulty":"very-hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-141","question":"Passage: For decades, economists taught that any resource shared by many users, a pasture, a fishery, a forest, was doomed. Each herder, reasoning that one more cow costs him little while the damage is spread across everyone, would add animals until the pasture was stripped bare. The only cures, it was said, were to hand the resource to the state or to divide it into private plots. Fieldwork told a messier story. Villages in many parts of the world had managed shared forests and irrigation channels for centuries without either solution. They did so through rules they had made themselves: who could take what and when, how cheating was spotted, and what a cheat would pay. Where such arrangements failed, it was often because an outside authority had swept them aside in favour of a plan drawn up far away. The lesson was not that shared resources always thrive, but that the choice between state and market had been too narrow. Question: The author's central claim is that:","options":["shared resources are always better managed by local communities than by the state","the old theory missed a third option, self-governing communities","dividing shared land into private plots invariably destroys it in the end","herders are by nature cooperative rather than self-interested people"],"answer":1,"explanation":"The passage ends by saying the state-versus-market choice 'had been too narrow', pointing to self-governing villages. It explicitly denies that shared resources 'always thrive', so the 'always better' option overstates it.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-142","question":"Passage: For decades, economists taught that any resource shared by many users, a pasture, a fishery, a forest, was doomed. Each herder, reasoning that one more cow costs him little while the damage is spread across everyone, would add animals until the pasture was stripped bare. The only cures, it was said, were to hand the resource to the state or to divide it into private plots. Fieldwork told a messier story. Villages in many parts of the world had managed shared forests and irrigation channels for centuries without either solution. They did so through rules they had made themselves: who could take what and when, how cheating was spotted, and what a cheat would pay. Where such arrangements failed, it was often because an outside authority had swept them aside in favour of a plan drawn up far away. The lesson was not that shared resources always thrive, but that the choice between state and market had been too narrow. Question: Which of the following, if true, would most WEAKEN the author's explanation of why some community arrangements failed?","options":["Several forests run directly by the state were also badly degraded over the same period.","Villages with written rules managed their forests slightly better than villages with unwritten ones.","Economists later revised their textbooks to describe community management.","Many communities never touched by outside authority collapsed anyway once populations grew."],"answer":3,"explanation":"The author blames failures 'often' on outside authorities sweeping rules aside; failures without any outside interference undercut that explanation. State-run failures and textbook revisions do not touch the causal claim.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-143","question":"Passage: For decades, economists taught that any resource shared by many users, a pasture, a fishery, a forest, was doomed. Each herder, reasoning that one more cow costs him little while the damage is spread across everyone, would add animals until the pasture was stripped bare. The only cures, it was said, were to hand the resource to the state or to divide it into private plots. Fieldwork told a messier story. Villages in many parts of the world had managed shared forests and irrigation channels for centuries without either solution. They did so through rules they had made themselves: who could take what and when, how cheating was spotted, and what a cheat would pay. Where such arrangements failed, it was often because an outside authority had swept them aside in favour of a plan drawn up far away. The lesson was not that shared resources always thrive, but that the choice between state and market had been too narrow. Question: As used in the passage, the word 'messier' suggests that the evidence from fieldwork was:","options":["carelessly gathered in the field and therefore untrustworthy","contrary to every earlier finding in the field of economics","more complicated than the textbooks' tidy prediction allowed","too limited in scope to support any conclusion at all"],"answer":2,"explanation":"'Messier' contrasts the neat 'doomed' prediction with real villages that managed commons in varied ways; it does not question the quality of the research.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-144","question":"Passage: When restorers removed centuries of yellowed varnish from a celebrated fresco cycle, some critics were outraged. The colours that emerged were bright, almost garish, and quite unlike the sombre tones generations of viewers had admired. The critics argued that the restorers had stripped away the artist's own final glazes along with the grime. The restorers replied that the sombre tones had never been the artist's at all; they were the work of candle smoke, dust and earlier, clumsier restorations. Both sides claimed to be defending the painter's intentions, and neither could prove its case beyond doubt, since the painter left no description of how the finished work should look. What the quarrel really exposed was that a painting several centuries old is not a fixed object but a record of everything that has happened to it, and every restoration is a decision about which part of that record to keep. Question: According to the passage, the dispute could not be settled conclusively mainly because:","options":["the critics refused to examine the restored frescoes up close","the restorers used chemicals that had never been properly tested","the painter left no account of how the finished work should look","candle smoke cannot be told apart from the artist's varnish"],"answer":2,"explanation":"The passage says neither side could prove its case 'since the painter left no description of how the finished work should look'. The other reasons are not mentioned.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-145","question":"Passage: When restorers removed centuries of yellowed varnish from a celebrated fresco cycle, some critics were outraged. The colours that emerged were bright, almost garish, and quite unlike the sombre tones generations of viewers had admired. The critics argued that the restorers had stripped away the artist's own final glazes along with the grime. The restorers replied that the sombre tones had never been the artist's at all; they were the work of candle smoke, dust and earlier, clumsier restorations. Both sides claimed to be defending the painter's intentions, and neither could prove its case beyond doubt, since the painter left no description of how the finished work should look. What the quarrel really exposed was that a painting several centuries old is not a fixed object but a record of everything that has happened to it, and every restoration is a decision about which part of that record to keep. Question: The final sentence implies that restoration is best understood as:","options":["a purely technical return of a work to its exact original state","an act of interpretation that decides which layers of history to keep","a form of vandalism that should be avoided wherever it is possible","a scientific method that can settle disputes about an artist's intentions"],"answer":1,"explanation":"Calling a painting 'a record of everything that has happened to it' and restoration 'a decision about which part of that record to keep' makes restoration a matter of judgement, not a mechanical return to an 'original'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-146","question":"Passage: When restorers removed centuries of yellowed varnish from a celebrated fresco cycle, some critics were outraged. The colours that emerged were bright, almost garish, and quite unlike the sombre tones generations of viewers had admired. The critics argued that the restorers had stripped away the artist's own final glazes along with the grime. The restorers replied that the sombre tones had never been the artist's at all; they were the work of candle smoke, dust and earlier, clumsier restorations. Both sides claimed to be defending the painter's intentions, and neither could prove its case beyond doubt, since the painter left no description of how the finished work should look. What the quarrel really exposed was that a painting several centuries old is not a fixed object but a record of everything that has happened to it, and every restoration is a decision about which part of that record to keep. Question: The author's attitude towards the critics and the restorers is best described as:","options":["even-handed, declining to declare either side right","openly supportive of the restorers' work","contemptuous of the critics' taste in colour","indifferent to the question of the painter's intentions"],"answer":0,"explanation":"The author reports both arguments, notes that 'neither could prove its case', and moves to a larger point instead of a verdict. The passage is about intentions, so 'indifferent' does not fit.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-147","question":"Passage: The stationmaster at Kalwadi had stopped expecting promotions long ago. Trains no longer halted at his platform except the slow passenger at dawn, and the clerk who brought his salary once a month had begun to treat the visit as a favour. Still, he wound the platform clock each morning, chalked the day's date on the board and swept the waiting room that nobody waited in. When a young inspector, sent to assess whether the station should be closed, asked him why he bothered, he looked genuinely puzzled. 'The train comes at six,' he said. 'Somebody might be on it.' The inspector wrote 'traffic negligible' in his report and recommended closure. On the train back, however, he found that he could not stop thinking about the clock. Question: The stationmaster's reply to the inspector suggests that he:","options":["hopes his diligence will finally earn him a long-awaited promotion","does not realise that his station is being reviewed for possible closure","values the work for its own sake and for any passenger who might come","secretly resents the passengers who no longer use his station"],"answer":2,"explanation":"'Somebody might be on it' shows he does the work for its own sake and for a possible passenger. The first sentence rules out hopes of promotion, and nothing shows resentment.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-148","question":"Passage: The stationmaster at Kalwadi had stopped expecting promotions long ago. Trains no longer halted at his platform except the slow passenger at dawn, and the clerk who brought his salary once a month had begun to treat the visit as a favour. Still, he wound the platform clock each morning, chalked the day's date on the board and swept the waiting room that nobody waited in. When a young inspector, sent to assess whether the station should be closed, asked him why he bothered, he looked genuinely puzzled. 'The train comes at six,' he said. 'Somebody might be on it.' The inspector wrote 'traffic negligible' in his report and recommended closure. On the train back, however, he found that he could not stop thinking about the clock. Question: The last sentence most strongly implies that the inspector:","options":["had decided to withdraw his recommendation to close the station","had noticed that the platform clock was running a few minutes slow","regretted having travelled to such a remote and empty station","sensed that his report missed something the routine stood for"],"answer":3,"explanation":"Being unable to stop thinking about the clock (a symbol of the stationmaster's devotion) suggests the bare finding 'traffic negligible' left something out. Nothing says he changed his recommendation, which is the overreach.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-149","question":"Passage: The stationmaster at Kalwadi had stopped expecting promotions long ago. Trains no longer halted at his platform except the slow passenger at dawn, and the clerk who brought his salary once a month had begun to treat the visit as a favour. Still, he wound the platform clock each morning, chalked the day's date on the board and swept the waiting room that nobody waited in. When a young inspector, sent to assess whether the station should be closed, asked him why he bothered, he looked genuinely puzzled. 'The train comes at six,' he said. 'Somebody might be on it.' The inspector wrote 'traffic negligible' in his report and recommended closure. On the train back, however, he found that he could not stop thinking about the clock. Question: As used in the inspector's report, 'negligible' means:","options":["carefully recorded in full detail","steadily increasing over the years","too small to be worth considering","impossible to measure accurately"],"answer":2,"explanation":"With one slow train and almost no passengers, the traffic was so small it could be disregarded, which is what 'negligible' means.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-150","question":"Passage: We are often told to 'think for ourselves' rather than defer to experts. The advice sounds admirable, but taken literally it is impossible. No one can personally verify that the earth orbits the sun, that a particular vaccine is safe, or that the bridge they are about to cross will bear their weight. Modern life rests on a vast division of intellectual labour in which each of us trusts far more than we could ever check. The real question, then, is not whether to trust but whom, and on what grounds. Here independent thinking does have a role: we can ask whether experts disagree among themselves, whether they have a stake in the answer, and whether their past predictions have held up. Such questions do not require us to master the science, only to judge the people who have. Question: The author would most likely agree that:","options":["expert opinion should be accepted without any questioning by ordinary people","thinking for oneself means personally checking every scientific claim","an expert with any stake in a question should never be believed","one can trust experts while weighing their consensus, interests and record"],"answer":3,"explanation":"The author rejects literal self-reliance but keeps a role for independent thinking in choosing whom to trust. A stake in the answer is one thing to weigh, not an automatic disqualification.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-151","question":"Passage: We are often told to 'think for ourselves' rather than defer to experts. The advice sounds admirable, but taken literally it is impossible. No one can personally verify that the earth orbits the sun, that a particular vaccine is safe, or that the bridge they are about to cross will bear their weight. Modern life rests on a vast division of intellectual labour in which each of us trusts far more than we could ever check. The real question, then, is not whether to trust but whom, and on what grounds. Here independent thinking does have a role: we can ask whether experts disagree among themselves, whether they have a stake in the answer, and whether their past predictions have held up. Such questions do not require us to master the science, only to judge the people who have. Question: The examples of the earth's orbit, the vaccine and the bridge mainly serve to:","options":["show that we all rely on knowledge we cannot check ourselves","prove that experts are nearly always right about such matters","illustrate the danger of trusting engineers and doctors blindly","show that science has now settled every important question"],"answer":0,"explanation":"They are introduced with 'No one can personally verify', supporting the claim that literal self-reliance is impossible. They say nothing about how often experts are right.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-152","question":"Passage: We are often told to 'think for ourselves' rather than defer to experts. The advice sounds admirable, but taken literally it is impossible. No one can personally verify that the earth orbits the sun, that a particular vaccine is safe, or that the bridge they are about to cross will bear their weight. Modern life rests on a vast division of intellectual labour in which each of us trusts far more than we could ever check. The real question, then, is not whether to trust but whom, and on what grounds. Here independent thinking does have a role: we can ask whether experts disagree among themselves, whether they have a stake in the answer, and whether their past predictions have held up. Such questions do not require us to master the science, only to judge the people who have. Question: Which of the following best describes the structure of the passage?","options":["A theory is described, tested against the evidence and then finally rejected","Two opposing views are set out side by side and then deliberately left unresolved","A historical development is traced from its origins to the present day","A maxim is challenged, the issue reframed, and the maxim kept in a narrower role"],"answer":3,"explanation":"'Think for yourself' is called impossible taken literally, the question becomes 'whom to trust', and independent thinking returns in a limited form ('does have a role').","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-153","question":"Passage: Boredom has a poor reputation. It is treated as a problem to be solved, and the phone in every pocket promises to solve it instantly. Yet psychologists who study the state describe it less as emptiness than as a signal: a feeling that what we are doing does not match what we want to be doing. Like hunger, it is unpleasant precisely so that we act on it. The trouble with curing boredom by scrolling is not that scrolling is wicked but that it silences the signal without answering it. The person who reaches for the phone at every idle moment may never discover what the restlessness was pointing towards. Some of the most productive minds in history, it is worth recalling, did their best thinking on long, dull walks. Question: The comparison of boredom with hunger suggests that boredom:","options":["is unpleasant for a purpose: to push us to change what we are doing","is a bodily need that must be satisfied at regular, fixed intervals","is caused by a lack of nourishing activities in modern life","will disappear by itself if it is simply ignored long enough"],"answer":0,"explanation":"'Unpleasant precisely so that we act on it' makes the discomfort a prompt to act, like hunger. The passage says nothing about fixed intervals or the feeling fading by itself.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-154","question":"Passage: Boredom has a poor reputation. It is treated as a problem to be solved, and the phone in every pocket promises to solve it instantly. Yet psychologists who study the state describe it less as emptiness than as a signal: a feeling that what we are doing does not match what we want to be doing. Like hunger, it is unpleasant precisely so that we act on it. The trouble with curing boredom by scrolling is not that scrolling is wicked but that it silences the signal without answering it. The person who reaches for the phone at every idle moment may never discover what the restlessness was pointing towards. Some of the most productive minds in history, it is worth recalling, did their best thinking on long, dull walks. Question: The author's main objection to relieving boredom with a phone is that it:","options":["removes the discomfort without answering what it was signalling","is morally wrong to waste so much precious time on idle entertainment","leaves people more bored afterwards than they were before","stops people from taking the long walks that inspire ideas"],"answer":0,"explanation":"The author says scrolling 'silences the signal without answering it' and explicitly says the trouble is 'not that scrolling is wicked'. Greater boredom later is never claimed.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-155","question":"Passage: Boredom has a poor reputation. It is treated as a problem to be solved, and the phone in every pocket promises to solve it instantly. Yet psychologists who study the state describe it less as emptiness than as a signal: a feeling that what we are doing does not match what we want to be doing. Like hunger, it is unpleasant precisely so that we act on it. The trouble with curing boredom by scrolling is not that scrolling is wicked but that it silences the signal without answering it. The person who reaches for the phone at every idle moment may never discover what the restlessness was pointing towards. Some of the most productive minds in history, it is worth recalling, did their best thinking on long, dull walks. Question: The last sentence of the passage functions as:","options":["an illustration that unfilled, dull time can prove productive","the main conclusion of the passage, that walking cures boredom","a concession that boredom is in fact harmless for most people","evidence that productive people are rarely, if ever, bored"],"answer":0,"explanation":"The reference to great thinkers on 'long, dull walks' backs up the idea that heeding boredom can lead somewhere. It is an illustration, not the main claim, and it does not say such people were never bored.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-156","question":"Passage: A 'nudge' changes the way a choice is presented without forbidding any option or changing its price. Placing fruit at eye level in a canteen, or enrolling employees in a pension scheme unless they opt out, are classic examples. Supporters argue that nudges respect freedom, since anyone can still choose the chips or leave the scheme. Critics reply that the freedom is partly an illusion: a nudge works precisely because most people will not bother to resist it, and whoever designs the default is quietly making the decision for them. The supporters' best answer is that there is no neutral way to present choices. Fruit must be placed somewhere; a form must have some default. If the designer cannot avoid influencing us, the argument goes, better that the influence be deliberate and aimed at our own good. Question: The supporters' 'best answer' to the critics rests on the assumption that:","options":["people always resist defaults that they happen to dislike","people never notice when a choice has been quietly arranged for them","every way of arranging a choice pushes people in some direction","nudges cost less to introduce than bans or new taxes"],"answer":2,"explanation":"The reply works only if no arrangement is neutral ('Fruit must be placed somewhere'), so influence is unavoidable. Universal resistance would undercut the nudge itself, and cost is never discussed.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-157","question":"Passage: A 'nudge' changes the way a choice is presented without forbidding any option or changing its price. Placing fruit at eye level in a canteen, or enrolling employees in a pension scheme unless they opt out, are classic examples. Supporters argue that nudges respect freedom, since anyone can still choose the chips or leave the scheme. Critics reply that the freedom is partly an illusion: a nudge works precisely because most people will not bother to resist it, and whoever designs the default is quietly making the decision for them. The supporters' best answer is that there is no neutral way to present choices. Fruit must be placed somewhere; a form must have some default. If the designer cannot avoid influencing us, the argument goes, better that the influence be deliberate and aimed at our own good. Question: According to the critics, nudges succeed because:","options":["they make the healthier option cheaper than the alternatives","they quietly forbid the most harmful choices that would otherwise be on offer","most people do not bother to depart from the option set for them","people consciously agree with the designer's goals for them"],"answer":2,"explanation":"The critics say a nudge 'works precisely because most people will not bother to resist it'. By definition nudges neither change prices nor forbid options.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-158","question":"Passage: A 'nudge' changes the way a choice is presented without forbidding any option or changing its price. Placing fruit at eye level in a canteen, or enrolling employees in a pension scheme unless they opt out, are classic examples. Supporters argue that nudges respect freedom, since anyone can still choose the chips or leave the scheme. Critics reply that the freedom is partly an illusion: a nudge works precisely because most people will not bother to resist it, and whoever designs the default is quietly making the decision for them. The supporters' best answer is that there is no neutral way to present choices. Fruit must be placed somewhere; a form must have some default. If the designer cannot avoid influencing us, the argument goes, better that the influence be deliberate and aimed at our own good. Question: Which of the following would count as a nudge as the passage defines it?","options":["Raising the tax on cigarettes to discourage people from smoking","A licence form with 'yes' to organ donation pre-ticked but changeable","Banning the sale of sugary drinks in all school canteens","Paying people a cash reward for each kilogram of weight they manage to lose"],"answer":1,"explanation":"A nudge changes presentation 'without forbidding any option or changing its price'. A pre-ticked but changeable default fits; taxes and rewards change prices, and a ban forbids an option.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-159","question":"Passage: The old customs house on the waterfront has been repaired so often that hardly a beam of the original survives. Its timbers were replaced after a fire, its roof after a cyclone, its facade after the city decided it should look as it did a century ago. Heritage officials insist it is still the building that stood here in 1880, and in a sense they are right: it occupies the same site, serves a similar purpose and has never been entirely torn down at once. Purists disagree. A building, they say, is its material, and a copy assembled piece by piece over a hundred years is still a copy. The dispute matters for more than philosophy. Grants for 'original' structures are larger than those for reconstructions, so the question of what the building is has become a question of who pays for it. Question: Which of the following best captures the heritage officials' reasoning?","options":["Only original materials can make a building truly authentic","A reconstruction is as valuable as an original if it looks exactly the same","Buildings that have survived disasters deserve larger heritage grants","Continuity of site, use and gradual repair preserves a building's identity"],"answer":3,"explanation":"The officials point to the same site, a similar purpose and never being torn down 'all at once'. The material view is the purists' position.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-160","question":"Passage: The old customs house on the waterfront has been repaired so often that hardly a beam of the original survives. Its timbers were replaced after a fire, its roof after a cyclone, its facade after the city decided it should look as it did a century ago. Heritage officials insist it is still the building that stood here in 1880, and in a sense they are right: it occupies the same site, serves a similar purpose and has never been entirely torn down at once. Purists disagree. A building, they say, is its material, and a copy assembled piece by piece over a hundred years is still a copy. The dispute matters for more than philosophy. Grants for 'original' structures are larger than those for reconstructions, so the question of what the building is has become a question of who pays for it. Question: The author mentions grants in the last two sentences in order to:","options":["show that an abstract question of identity has real financial consequences","argue that the purists are motivated mainly by money rather than principle","suggest that the officials are deliberately misleading the public","prove that the customs house is still an original structure"],"answer":0,"explanation":"'The dispute matters for more than philosophy' introduces the grants: what counts as original decides who pays. No motive or deception is attributed to either side.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-161","question":"Passage: The old customs house on the waterfront has been repaired so often that hardly a beam of the original survives. Its timbers were replaced after a fire, its roof after a cyclone, its facade after the city decided it should look as it did a century ago. Heritage officials insist it is still the building that stood here in 1880, and in a sense they are right: it occupies the same site, serves a similar purpose and has never been entirely torn down at once. Purists disagree. A building, they say, is its material, and a copy assembled piece by piece over a hundred years is still a copy. The dispute matters for more than philosophy. Grants for 'original' structures are larger than those for reconstructions, so the question of what the building is has become a question of who pays for it. Question: The purists would most likely regard which of the following as 'original'?","options":["A palace rebuilt stone for stone on the same site after an earthquake","A bridge whose every plank has been replaced over decades without ever closing it","A fort reconstructed exactly from its builders' drawings","A temple whose walls have been cleaned many times but never replaced"],"answer":3,"explanation":"For purists 'a building is its material', so only a structure that keeps its original fabric qualifies. The bridge with every plank replaced is the officials' kind of continuity, the trap.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-162","question":"Passage: When small loans to poor women were first promoted, they were hailed as a way out of poverty that needed no charity: borrowers would start businesses, repay with interest and lift their families up. Early success stories were genuine. But when researchers later compared villages that received microcredit with similar villages that did not, the average effects on income were modest. Many loans had been used not to start businesses but to smooth consumption, paying for a medical emergency or a wedding. This does not make the loans worthless. A household that can borrow to cover a crisis without selling its only cow is better off, even if its income has not risen. The mistake was to sell a useful financial tool as a cure for poverty, and then to feel disillusioned when it turned out to be merely useful. Question: According to the passage, the comparative studies found that microcredit:","options":["brought borrowers no benefit of any kind","raised average incomes only slightly","was used mainly to start new businesses","worked better in towns than in villages"],"answer":1,"explanation":"The studies found 'the average effects on income were modest'. The passage then argues the loans had other benefits, and it says many were used for consumption, not businesses.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-163","question":"Passage: When small loans to poor women were first promoted, they were hailed as a way out of poverty that needed no charity: borrowers would start businesses, repay with interest and lift their families up. Early success stories were genuine. But when researchers later compared villages that received microcredit with similar villages that did not, the average effects on income were modest. Many loans had been used not to start businesses but to smooth consumption, paying for a medical emergency or a wedding. This does not make the loans worthless. A household that can borrow to cover a crisis without selling its only cow is better off, even if its income has not risen. The mistake was to sell a useful financial tool as a cure for poverty, and then to feel disillusioned when it turned out to be merely useful. Question: The phrase 'merely useful' in the last sentence is used:","options":["to dismiss microcredit as a complete and costly failure","ironically, to mock disappointment born of inflated hopes","to praise microcredit as a proven cure for rural poverty everywhere","to show that the author has no opinion on the matter"],"answer":1,"explanation":"The author has just defended the loans' value; calling them 'merely useful' mocks the disillusionment that came from overselling them, not the loans themselves.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-164","question":"Passage: When small loans to poor women were first promoted, they were hailed as a way out of poverty that needed no charity: borrowers would start businesses, repay with interest and lift their families up. Early success stories were genuine. But when researchers later compared villages that received microcredit with similar villages that did not, the average effects on income were modest. Many loans had been used not to start businesses but to smooth consumption, paying for a medical emergency or a wedding. This does not make the loans worthless. A household that can borrow to cover a crisis without selling its only cow is better off, even if its income has not risen. The mistake was to sell a useful financial tool as a cure for poverty, and then to feel disillusioned when it turned out to be merely useful. Question: Which of the following, if true, would most strengthen the author's claim that the loans had value even without raising incomes?","options":["Hit by crop failure, borrowers less often sold livestock or took children out of school.","Many borrowers went on to take second and third loans from the same lenders within a year.","Interest rates on small loans were much higher than those charged by commercial banks.","A few borrowers' businesses grew into large firms employing hundreds."],"answer":0,"explanation":"The author's claim is that loans protect households in a crisis; evidence of fewer distress sales supports it directly. Business growth supports the income story instead, and repeat borrowing proves nothing by itself.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-165","question":"Passage: A survey announces that the average family spends 3.72 hours a week cooking. The two decimal places suggest a precision the method cannot possibly deliver; the figure was built from people's rough guesses about their own habits, and nobody remembers their week to the nearest minute. Such false precision is more than a stylistic flaw. Readers tend to trust a number more when it looks exact, so a careful-looking figure can carry more authority than the evidence behind it deserves. Honest reporting would round the result and state the uncertainty: 'between three and four hours, based on self-reports'. That sounds less impressive, which is exactly why it is so rarely done. Question: The author's main objection to the figure '3.72 hours' is that it:","options":["is far too low to be a realistic estimate for most families","implies a precision that the underlying data cannot support","was worked out with an incorrect averaging formula","leaves out families that do not cook at home at all"],"answer":1,"explanation":"The objection is that two decimal places suggest precision from mere 'rough guesses'. The author never questions the size of the figure or the arithmetic.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-166","question":"Passage: A survey announces that the average family spends 3.72 hours a week cooking. The two decimal places suggest a precision the method cannot possibly deliver; the figure was built from people's rough guesses about their own habits, and nobody remembers their week to the nearest minute. Such false precision is more than a stylistic flaw. Readers tend to trust a number more when it looks exact, so a careful-looking figure can carry more authority than the evidence behind it deserves. Honest reporting would round the result and state the uncertainty: 'between three and four hours, based on self-reports'. That sounds less impressive, which is exactly why it is so rarely done. Question: The last sentence suggests that false precision persists mainly because:","options":["survey firms lack the statistical training to round their figures correctly","exact numbers persuade, while honest rounding sounds less impressive","readers insist on seeing decimal places in every statistic","self-reported data cannot be rounded without losing accuracy"],"answer":1,"explanation":"'That sounds less impressive, which is exactly why it is so rarely done' ties the habit to the persuasive pull of exact numbers. Readers trusting exact figures is not the same as insisting on them.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-167","question":"Passage: A survey announces that the average family spends 3.72 hours a week cooking. The two decimal places suggest a precision the method cannot possibly deliver; the figure was built from people's rough guesses about their own habits, and nobody remembers their week to the nearest minute. Such false precision is more than a stylistic flaw. Readers tend to trust a number more when it looks exact, so a careful-looking figure can carry more authority than the evidence behind it deserves. Honest reporting would round the result and state the uncertainty: 'between three and four hours, based on self-reports'. That sounds less impressive, which is exactly why it is so rarely done. Question: Which of the following would the author regard as the most honest way to report the finding?","options":["Families spend exactly 3.72 hours a week cooking.","Families spend 3.7 hours a week cooking, a precise and reliable figure.","Families say they spend roughly three to four hours a week cooking.","Cooking time cannot be measured, so no figure should be given."],"answer":2,"explanation":"The author recommends rounding and stating the basis ('based on self-reports'); 'say' and 'roughly three to four' do both. The author wants an honest range, not silence.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-168","question":"Passage: The octopus is a puzzle for anyone who believes intelligence requires a long life and a social upbringing. Most octopuses live for only a year or two, never meet their parents and spend their lives largely alone. Yet in laboratories they open screw-top jars, escape from tanks and appear to recognise individual keepers. Stranger still, about two-thirds of their neurons sit not in the brain but in the arms, which can respond to touch and taste with some independence. Intelligence, the octopus suggests, can evolve along routes quite unlike our own. If so, our habit of measuring other animals by how closely they resemble us may lead us to overlook minds that are organised on entirely different lines. Question: The octopus is called a 'puzzle' because it:","options":["has more neurons than any other animal, most of them located in its arms","learns its many skills by watching its parents over a long childhood","cannot solve problems once it is outside a laboratory","is clever without the long life and upbringing thought necessary"],"answer":3,"explanation":"The puzzle is for those who think intelligence needs a long life and upbringing; octopuses live briefly, never meet their parents, yet solve problems. Neuron totals are not compared.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-169","question":"Passage: The octopus is a puzzle for anyone who believes intelligence requires a long life and a social upbringing. Most octopuses live for only a year or two, never meet their parents and spend their lives largely alone. Yet in laboratories they open screw-top jars, escape from tanks and appear to recognise individual keepers. Stranger still, about two-thirds of their neurons sit not in the brain but in the arms, which can respond to touch and taste with some independence. Intelligence, the octopus suggests, can evolve along routes quite unlike our own. If so, our habit of measuring other animals by how closely they resemble us may lead us to overlook minds that are organised on entirely different lines. Question: The author's final point is that:","options":["judging animals by their likeness to us may blind us to other kinds of mind","octopuses are, in some respects, more intelligent than humans","intelligence always requires neurons to be gathered in one brain","laboratory tests tend to greatly overestimate the intelligence of wild animals"],"answer":0,"explanation":"The closing sentence warns that measuring animals 'by how closely they resemble us' may make us overlook other kinds of mind. The octopus's arm neurons argue against the 'single brain' option.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-170","question":"Passage: The octopus is a puzzle for anyone who believes intelligence requires a long life and a social upbringing. Most octopuses live for only a year or two, never meet their parents and spend their lives largely alone. Yet in laboratories they open screw-top jars, escape from tanks and appear to recognise individual keepers. Stranger still, about two-thirds of their neurons sit not in the brain but in the arms, which can respond to touch and taste with some independence. Intelligence, the octopus suggests, can evolve along routes quite unlike our own. If so, our habit of measuring other animals by how closely they resemble us may lead us to overlook minds that are organised on entirely different lines. Question: Which of the following can be inferred from the passage?","options":["Octopuses raised by their parents grow more intelligent than others.","Some of an octopus's responses may not be directed by its brain.","Octopuses live longer in laboratories than they do in the wild.","An octopus can recognise every human being that it meets."],"answer":1,"explanation":"Arms that 'respond to touch and taste with some independence' imply some responses are not run by the brain. The passage says octopuses never meet their parents and only 'appear to recognise individual keepers'.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-171","question":"Passage: Every generation of grammarians has believed that the language is decaying. Writers in the eighteenth century complained that slovenly speakers were ruining English; their own usage, which we now regard as polished, had been denounced by their predecessors in exactly the same terms. Linguists point out that what purists call corruption is simply change, and that change is how every living language works. Latin did not 'decay' into Italian, Spanish and French; it changed into them. None of this means that rules are pointless. Standard forms make communication across regions easier, and a job applicant who ignores them pays a real price. But the standard is a convention, useful in the way that driving on one side of the road is useful, not a moral law whose violation reveals a defect of character. Question: The comparison with driving on one side of the road suggests that standard grammar is:","options":["arbitrary, and therefore safe for careful speakers and writers to ignore","enforced by law and punished whenever it is broken","useful because it is shared, not because it is correct in itself","a reliable sign of a speaker's good character and education"],"answer":2,"explanation":"Which side of the road we drive on is arbitrary, but everyone sticking to it is what makes it useful. The author has just said that ignoring the standard 'pays a real price', so 'safe to ignore' is wrong.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-172","question":"Passage: Every generation of grammarians has believed that the language is decaying. Writers in the eighteenth century complained that slovenly speakers were ruining English; their own usage, which we now regard as polished, had been denounced by their predecessors in exactly the same terms. Linguists point out that what purists call corruption is simply change, and that change is how every living language works. Latin did not 'decay' into Italian, Spanish and French; it changed into them. None of this means that rules are pointless. Standard forms make communication across regions easier, and a job applicant who ignores them pays a real price. But the standard is a convention, useful in the way that driving on one side of the road is useful, not a moral law whose violation reveals a defect of character. Question: The reference to eighteenth-century writers mainly serves to:","options":["show that complaints of decline recur and target usage later accepted","prove that English was purer in the eighteenth century than it is today","show that eighteenth-century grammarians had better rules than ours","explain how Latin gradually changed into Italian and French"],"answer":0,"explanation":"Their own 'polished' usage had been attacked by earlier purists in the same terms, so the complaint is a recurring pattern, not evidence of real decay.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-173","question":"Passage: Every generation of grammarians has believed that the language is decaying. Writers in the eighteenth century complained that slovenly speakers were ruining English; their own usage, which we now regard as polished, had been denounced by their predecessors in exactly the same terms. Linguists point out that what purists call corruption is simply change, and that change is how every living language works. Latin did not 'decay' into Italian, Spanish and French; it changed into them. None of this means that rules are pointless. Standard forms make communication across regions easier, and a job applicant who ignores them pays a real price. But the standard is a convention, useful in the way that driving on one side of the road is useful, not a moral law whose violation reveals a defect of character. Question: Which of the following statements would the author most likely REJECT?","options":["Standard forms help people from different regions understand one another.","A language that changes is not necessarily decaying.","People who break grammatical rules reveal a weakness of character.","Ignoring standard usage can hurt a job applicant's chances."],"answer":2,"explanation":"The author says the standard is 'not a moral law whose violation reveals a defect of character'. The other three statements are all made or endorsed in the passage.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-174","question":"Passage: When wolves were returned to a large wilderness park after an absence of seventy years, a striking story quickly spread. The wolves, it was said, frightened the deer away from riverbanks; freed from browsing, willows recovered; the willows steadied the banks, and the rivers themselves changed course. The story was so elegant that it became a favourite of documentaries. Ecologists who studied the park more closely were more cautious. Willows had recovered in some places and not others, a long drought had ended around the same time, and hunters outside the park had also been killing more deer. The wolves probably played a part, but separating their effect from everything else that changed was far harder than the tidy narrative suggested. The episode is a reminder that nature rarely arranges itself into stories with a single hero. Question: The ecologists' caution was based mainly on the fact that:","options":["other changes happening at the same time could also explain the recovery","the wolves were removed from the park again soon after their return","willows do not normally grow along the banks of mountain rivers at all","deer numbers actually rose sharply in the years after the wolves returned"],"answer":0,"explanation":"They cite the end of a drought, extra hunting outside the park and patchy recovery, all of which make the wolves' effect hard to isolate.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-175","question":"Passage: When wolves were returned to a large wilderness park after an absence of seventy years, a striking story quickly spread. The wolves, it was said, frightened the deer away from riverbanks; freed from browsing, willows recovered; the willows steadied the banks, and the rivers themselves changed course. The story was so elegant that it became a favourite of documentaries. Ecologists who studied the park more closely were more cautious. Willows had recovered in some places and not others, a long drought had ended around the same time, and hunters outside the park had also been killing more deer. The wolves probably played a part, but separating their effect from everything else that changed was far harder than the tidy narrative suggested. The episode is a reminder that nature rarely arranges itself into stories with a single hero. Question: The author's attitude towards the popular story is best described as:","options":["dismissive, treating it as entirely false and deliberately misleading","sceptical of its tidiness, without denying the wolves mattered","uncritically enthusiastic about its elegance","indifferent to whether it was true or false"],"answer":1,"explanation":"'The wolves probably played a part' keeps some credit for them, while 'tidy narrative' and 'a single hero' question the neat version. 'Entirely false' goes too far.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-176","question":"Passage: When wolves were returned to a large wilderness park after an absence of seventy years, a striking story quickly spread. The wolves, it was said, frightened the deer away from riverbanks; freed from browsing, willows recovered; the willows steadied the banks, and the rivers themselves changed course. The story was so elegant that it became a favourite of documentaries. Ecologists who studied the park more closely were more cautious. Willows had recovered in some places and not others, a long drought had ended around the same time, and hunters outside the park had also been killing more deer. The wolves probably played a part, but separating their effect from everything else that changed was far harder than the tidy narrative suggested. The episode is a reminder that nature rarely arranges itself into stories with a single hero. Question: Which of the following, if true, would most STRENGTHEN the popular story?","options":["Willows recovered most where wolves hunted most, other conditions being equal.","Willows also recovered strongly in nearby parks where no wolves had been released.","The long drought ended in the very same year that the wolves were released.","Documentaries about the park's wolves drew record numbers of tourists to the region."],"answer":0,"explanation":"Recovery that tracks wolf activity while the other factors are held equal isolates the wolves' effect. Recovery without wolves, or a drought ending at the same time, supports the rival explanations.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-177","question":"Passage: In the final round, Ananya needed only a draw to win the tournament, and her opponent, a boy two years younger, offered one on the twentieth move. She looked at the board for a long time. The position was level; a draw was the sensible result, and her coach, watching from the edge of the hall, gave the faintest nod. She declined. Later she could not quite explain why, except that the boy had offered it too quickly, with the air of someone who was afraid of the position rather than satisfied with it. For three hours she pressed, found nothing, and finally lost a pawn in time trouble. She saved the endgame only with a stalemate trick she had learnt at the age of eight. Her coach said nothing on the way home, and she was grateful for it. Question: Ananya most probably declined the draw because she:","options":["believed, after long study, that she already had a winning position on the board","had misread her coach's nod as advice to keep playing on","needed a win, not a draw, to take the tournament title","sensed from the hasty offer that her opponent was uneasy and might crack"],"answer":3,"explanation":"She notes the offer came 'too quickly' from someone 'afraid of the position'. The position was level, the coach's nod favoured the draw, and a draw was all she needed.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-178","question":"Passage: In the final round, Ananya needed only a draw to win the tournament, and her opponent, a boy two years younger, offered one on the twentieth move. She looked at the board for a long time. The position was level; a draw was the sensible result, and her coach, watching from the edge of the hall, gave the faintest nod. She declined. Later she could not quite explain why, except that the boy had offered it too quickly, with the air of someone who was afraid of the position rather than satisfied with it. For three hours she pressed, found nothing, and finally lost a pawn in time trouble. She saved the endgame only with a stalemate trick she had learnt at the age of eight. Her coach said nothing on the way home, and she was grateful for it. Question: Her coach's silence on the way home is best understood as:","options":["anger that her risky play had lost her the tournament title","tactful restraint about a risk that nearly cost her the title","disappointment that she had tamely accepted the draw she was offered","a sign that he had not been watching the game closely"],"answer":1,"explanation":"She saved the game, so she won the tournament, but only after an unnecessary risk against his signal. Her gratitude suggests the silence was kind restraint, not anger.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-179","question":"Passage: In the final round, Ananya needed only a draw to win the tournament, and her opponent, a boy two years younger, offered one on the twentieth move. She looked at the board for a long time. The position was level; a draw was the sensible result, and her coach, watching from the edge of the hall, gave the faintest nod. She declined. Later she could not quite explain why, except that the boy had offered it too quickly, with the air of someone who was afraid of the position rather than satisfied with it. For three hours she pressed, found nothing, and finally lost a pawn in time trouble. She saved the endgame only with a stalemate trick she had learnt at the age of eight. Her coach said nothing on the way home, and she was grateful for it. Question: Which of the following is true according to the passage?","options":["Ananya won the final game outright after three hours of sustained pressure.","Ananya's opponent was older and more experienced than she was.","Ananya's coach signalled clearly that she should decline the offered draw.","Ananya still got the result she needed, but only after a narrow escape."],"answer":3,"explanation":"She lost a pawn and saved the endgame only by a stalemate trick, a draw, which was enough. The opponent was younger, and the coach's nod approved the draw.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-180","question":"Passage: The deep seabed is strewn with potato-sized nodules rich in the metals that batteries need, and mining companies argue that collecting them would be gentler than digging new mines on land. No forests would be cleared, no villages moved. Marine biologists answer that we know almost nothing about the life the nodules support. Many of the animals found on recent expeditions had never been described, and some depend on the nodules themselves as the only hard surface in a sea of mud. Because the nodules take millions of years to form, whatever lives on them would not return within any timescale that matters to humans. The companies' comparison, the biologists say, rests on a kind of blindness: a forest's loss is visible, while a loss two miles under the sea is not, and what cannot be seen is too easily counted as nothing. Question: The mining companies' main argument is that seabed mining:","options":["would be less destructive than opening new mines on land","would supply battery metals more cheaply than any other source","would leave the seabed and its animals entirely unharmed","has already been shown to protect rare deep-sea animals"],"answer":0,"explanation":"They argue that collecting nodules 'would be gentler than digging new mines on land', with no forests cleared or villages moved. Cost and 'no harm at all' are not claimed.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-181","question":"Passage: The deep seabed is strewn with potato-sized nodules rich in the metals that batteries need, and mining companies argue that collecting them would be gentler than digging new mines on land. No forests would be cleared, no villages moved. Marine biologists answer that we know almost nothing about the life the nodules support. Many of the animals found on recent expeditions had never been described, and some depend on the nodules themselves as the only hard surface in a sea of mud. Because the nodules take millions of years to form, whatever lives on them would not return within any timescale that matters to humans. The companies' comparison, the biologists say, rests on a kind of blindness: a forest's loss is visible, while a loss two miles under the sea is not, and what cannot be seen is too easily counted as nothing. Question: According to the biologists, the damage from removing nodules would be especially lasting because:","options":["the nodules take millions of years to form, so lost habitat would not return","the soft mud of the seabed is poisonous to most of the animals that live on it","mining ships would pollute the water above the site for decades","the animals living there are already endangered by deep-sea fishing"],"answer":0,"explanation":"Some animals use the nodules as 'the only hard surface in a sea of mud', and the nodules take millions of years to form, so the habitat would not return in any human timescale.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-182","question":"Passage: The deep seabed is strewn with potato-sized nodules rich in the metals that batteries need, and mining companies argue that collecting them would be gentler than digging new mines on land. No forests would be cleared, no villages moved. Marine biologists answer that we know almost nothing about the life the nodules support. Many of the animals found on recent expeditions had never been described, and some depend on the nodules themselves as the only hard surface in a sea of mud. Because the nodules take millions of years to form, whatever lives on them would not return within any timescale that matters to humans. The companies' comparison, the biologists say, rests on a kind of blindness: a forest's loss is visible, while a loss two miles under the sea is not, and what cannot be seen is too easily counted as nothing. Question: The 'blindness' the biologists attribute to the companies refers to:","options":["the companies' lack of underwater cameras, lights and sensors","treating harm that cannot be seen as if it were no harm at all","the fact that many deep-sea animals have no working eyes at all","the companies' refusal to publish their survey data"],"answer":1,"explanation":"The passage explains the word: 'what cannot be seen is too easily counted as nothing'. It is a figurative blindness, not a lack of equipment.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-183","question":"Passage: It has become common wisdom that social media traps users in 'filter bubbles', feeding them only views they already hold. The idea is intuitive, but the evidence is surprisingly mixed. Several large studies have found that heavy users of social media actually encounter a wider range of political opinions than people who get their news from a single newspaper or television channel. What seems to divide people is less the absence of opposing views than the way they meet them: often in the form of the other side's most extreme voices, shared by one's own side in mockery. Exposure of this kind may harden opinions rather than soften them. If so, the cure for polarisation is not simply more exposure to the other side, which users already have, but better exposure. Question: The author's main point is that:","options":["the problem is less missing contact with opposing views than its distorted form","social media users almost never encounter opposing political views","filter bubbles are the main cause of today's political polarisation","people who read a single newspaper are more open-minded than social media users"],"answer":0,"explanation":"The author questions the filter-bubble idea (users see more variety) and moves the blame to how opposing views are met: extreme voices, shared in mockery.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-184","question":"Passage: It has become common wisdom that social media traps users in 'filter bubbles', feeding them only views they already hold. The idea is intuitive, but the evidence is surprisingly mixed. Several large studies have found that heavy users of social media actually encounter a wider range of political opinions than people who get their news from a single newspaper or television channel. What seems to divide people is less the absence of opposing views than the way they meet them: often in the form of the other side's most extreme voices, shared by one's own side in mockery. Exposure of this kind may harden opinions rather than soften them. If so, the cure for polarisation is not simply more exposure to the other side, which users already have, but better exposure. Question: The phrase 'shared by one's own side in mockery' suggests that users often meet opposing views:","options":["through respectful debates led by experts on both sides","in their least reasonable form, held up for ridicule","only by accident and very rarely, if at all","in the form of balanced news reports from neutral sources"],"answer":1,"explanation":"The other side's 'most extreme voices' are passed around to be laughed at, so users meet the weakest version of opposing views. The studies show the contact is not rare.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-185","question":"Passage: It has become common wisdom that social media traps users in 'filter bubbles', feeding them only views they already hold. The idea is intuitive, but the evidence is surprisingly mixed. Several large studies have found that heavy users of social media actually encounter a wider range of political opinions than people who get their news from a single newspaper or television channel. What seems to divide people is less the absence of opposing views than the way they meet them: often in the form of the other side's most extreme voices, shared by one's own side in mockery. Exposure of this kind may harden opinions rather than soften them. If so, the cure for polarisation is not simply more exposure to the other side, which users already have, but better exposure. Question: Which of the following would the author most likely recommend?","options":["Showing users as many posts from the other side as possible, whatever their tone","Banning political content from social media platforms altogether","Showing users the most thoughtful opposing arguments, not the most extreme","Encouraging people to rely on a single trusted newspaper for news"],"answer":2,"explanation":"The author calls for 'not simply more exposure ... but better exposure'. Simply showing more posts from the other side is exactly what the author says is not enough.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-186","question":"Passage: Folk songs have no authors in the modern sense. A tune travels from village to village, picking up a new verse here, a changed melody there, until no one can say whose song it is. This endless borrowing is how the tradition stays alive. Modern copyright law, by contrast, treats a song as the property of whoever first fixed it in a recording or on paper. The law has real virtues: it lets composers earn a living from their work. But when a recording company copyrights an arrangement of a traditional song, the villagers who have sung it for generations may find themselves, in principle, infringing on their own heritage. A system designed to reward creativity can, applied without thought, end up fencing off the very commons from which creativity grows. Question: The word 'commons' in the last sentence refers to:","options":["village land owned and grazed jointly by its residents","the shared stock of traditional material new work draws on","the lower house of a legislature such as Parliament","the profits earned by recording companies from old folk songs"],"answer":1,"explanation":"The metaphor of 'fencing off' shared land is applied to the pool of folk material 'from which creativity grows'. Literal village land is the tempting but wrong reading.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-187","question":"Passage: Folk songs have no authors in the modern sense. A tune travels from village to village, picking up a new verse here, a changed melody there, until no one can say whose song it is. This endless borrowing is how the tradition stays alive. Modern copyright law, by contrast, treats a song as the property of whoever first fixed it in a recording or on paper. The law has real virtues: it lets composers earn a living from their work. But when a recording company copyrights an arrangement of a traditional song, the villagers who have sung it for generations may find themselves, in principle, infringing on their own heritage. A system designed to reward creativity can, applied without thought, end up fencing off the very commons from which creativity grows. Question: The author's view of copyright law is best described as:","options":["wholly hostile, regarding it as a form of theft from the poor","wholly supportive, regarding it as essential to every single art form","approving of its aim but wary of its careless use on folk songs","indifferent, treating it as a purely technical legal matter"],"answer":2,"explanation":"The author grants that 'the law has real virtues' but warns of harm when it is 'applied without thought' to traditional songs.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-188","question":"Passage: Folk songs have no authors in the modern sense. A tune travels from village to village, picking up a new verse here, a changed melody there, until no one can say whose song it is. This endless borrowing is how the tradition stays alive. Modern copyright law, by contrast, treats a song as the property of whoever first fixed it in a recording or on paper. The law has real virtues: it lets composers earn a living from their work. But when a recording company copyrights an arrangement of a traditional song, the villagers who have sung it for generations may find themselves, in principle, infringing on their own heritage. A system designed to reward creativity can, applied without thought, end up fencing off the very commons from which creativity grows. Question: According to the passage, folk songs stay alive through:","options":["careful preservation of a single, original authorised version","the protection that copyright law gives to their makers","continual borrowing and change as they pass between villages","being recorded and sold by professional companies"],"answer":2,"explanation":"The passage says 'This endless borrowing is how the tradition stays alive'. Copyright and recording are presented as possible threats.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-189","question":"Passage: Two drivers leave the same party, equally drunk, and drive home by the same road. One arrives safely. The other, through no greater fault, meets a child who runs into the street, and kills her. The law will treat the second driver far more harshly, and most of us feel that it should. Yet if we ask what each driver actually did, the answer is the same: each chose to drive while drunk. The difference lies entirely in something neither controlled. Philosophers call this 'moral luck', and it is uncomfortable because it suggests that our judgements of blame depend partly on chance. One response is to say the two are equally guilty and should be punished alike; another is to accept that outcomes matter to us in ways that pure logic cannot fully justify. Question: The example of the two drivers is used to show that:","options":["the law punishes drunk driving far too leniently in most cases like these","the second driver was in fact more careless than the first","children should be kept away from roads, especially at night","people assign blame by outcomes that lay beyond the agent's control"],"answer":3,"explanation":"Both made the same choice, yet the one whose luck was worse is blamed more. The passage says 'through no greater fault', which rules out greater carelessness.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-190","question":"Passage: Two drivers leave the same party, equally drunk, and drive home by the same road. One arrives safely. The other, through no greater fault, meets a child who runs into the street, and kills her. The law will treat the second driver far more harshly, and most of us feel that it should. Yet if we ask what each driver actually did, the answer is the same: each chose to drive while drunk. The difference lies entirely in something neither controlled. Philosophers call this 'moral luck', and it is uncomfortable because it suggests that our judgements of blame depend partly on chance. One response is to say the two are equally guilty and should be punished alike; another is to accept that outcomes matter to us in ways that pure logic cannot fully justify. Question: Which of the following situations is most closely analogous to the problem of 'moral luck' described in the passage?","options":["A student who studies harder than another scores higher marks in the exam.","Two doctors make the same error; only the one whose patient dies is disciplined.","Two thieves steal the same amount and receive exactly the same sentence.","A driver who deliberately speeds causes a serious accident and is punished for it."],"answer":1,"explanation":"The analogy needs identical conduct, different outcomes decided by chance, and different blame. Only the doctors fit; in the others, the conduct differs or the treatment is equal.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-191","question":"Passage: Two drivers leave the same party, equally drunk, and drive home by the same road. One arrives safely. The other, through no greater fault, meets a child who runs into the street, and kills her. The law will treat the second driver far more harshly, and most of us feel that it should. Yet if we ask what each driver actually did, the answer is the same: each chose to drive while drunk. The difference lies entirely in something neither controlled. Philosophers call this 'moral luck', and it is uncomfortable because it suggests that our judgements of blame depend partly on chance. One response is to say the two are equally guilty and should be punished alike; another is to accept that outcomes matter to us in ways that pure logic cannot fully justify. Question: Which two responses to moral luck does the passage mention?","options":["Abolishing punishment altogether, or punishing only the luckier of the two agents","Blaming the victim, or blaming the law that defines the offence","Judging only by outcomes, or judging only by the letter of the law","Treating both as equally guilty, or accepting that outcomes sway our judgement"],"answer":3,"explanation":"The last sentence gives both: punish the two drivers alike, or accept that outcomes matter to us 'in ways that pure logic cannot fully justify'.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-192","question":"Passage: When a popular temple, museum or train service has more visitors than places, someone must decide who gets in. A price does it by excluding those unwilling or unable to pay; a queue does it by excluding those unwilling or unable to wait. Queues are often defended as fairer, since everyone's time is equally precious while money is not equally shared. The defence is weaker than it looks. Time is not equally available either: a daily-wage labourer who spends four hours in line loses four hours of earnings, while a retired official loses nothing but patience. And wherever queues are long, a market in waiting soon appears, as people are paid to stand in line for others, so the well-off end up buying their way in after all, only less efficiently. Question: The author argues that the claim 'queues are fairer than prices' is weaker than it looks because:","options":["queues always move more slowly than systems based on price","prices are a perfectly fair way of sharing out scarce places","waiting costs people unequally, and the rich can pay others to wait","most people would rather pay a fee than wait for hours in a long line"],"answer":2,"explanation":"The two reasons given are that time is 'not equally available' (the labourer loses wages) and that a market in waiting lets the rich buy their way in. The author never calls prices perfectly fair.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-193","question":"Passage: When a popular temple, museum or train service has more visitors than places, someone must decide who gets in. A price does it by excluding those unwilling or unable to pay; a queue does it by excluding those unwilling or unable to wait. Queues are often defended as fairer, since everyone's time is equally precious while money is not equally shared. The defence is weaker than it looks. Time is not equally available either: a daily-wage labourer who spends four hours in line loses four hours of earnings, while a retired official loses nothing but patience. And wherever queues are long, a market in waiting soon appears, as people are paid to stand in line for others, so the well-off end up buying their way in after all, only less efficiently. Question: The example of the daily-wage labourer and the retired official illustrates that:","options":["retired officials are naturally more patient than labourers","labourers generally prefer queues to paying higher prices","waiting is pleasant for those who have plenty of free time","the same wait can cost one person far more than another"],"answer":3,"explanation":"The labourer loses four hours of earnings while the official loses 'nothing but patience', so the same wait costs them very different amounts.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-194","question":"Passage: When a popular temple, museum or train service has more visitors than places, someone must decide who gets in. A price does it by excluding those unwilling or unable to pay; a queue does it by excluding those unwilling or unable to wait. Queues are often defended as fairer, since everyone's time is equally precious while money is not equally shared. The defence is weaker than it looks. Time is not equally available either: a daily-wage labourer who spends four hours in line loses four hours of earnings, while a retired official loses nothing but patience. And wherever queues are long, a market in waiting soon appears, as people are paid to stand in line for others, so the well-off end up buying their way in after all, only less efficiently. Question: The phrase 'only less efficiently' at the end implies that:","options":["queues are actually more efficient than prices at sharing places","the outcome resembles pricing, but hired line-standers' time is wasted","the people paid to stand in line are unfairly exploited by the rich who hire them","the wealthy end up being shut out of the temple after all"],"answer":1,"explanation":"The rich still get in by paying, as under a price system, but hours are burnt by people standing in line for them, so it is the same outcome at higher total cost.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-195","question":"Passage: Textbooks once told history as the deeds of great men: a king decided, a general triumphed, an inventor had a flash of insight. Later historians pushed back, arguing that individuals are carried along by forces larger than themselves: climate, trade, population and technology. If one inventor had not built the steam engine, they said, another would have, since the coal, the demand and the craftsmen were all in place. The correction was needed, but it can be pushed too far. Structural forces explain why something was likely to happen, not exactly when, how or in what form. A war that was 'bound to come' still began on a particular morning, after particular decisions by particular people, and those details shaped what followed for decades. Question: The later historians' argument about the steam engine assumes that:","options":["inventors are usually unaware of the earlier work of other inventors","the steam engine was not an especially important invention","coal was scarce and costly at the time of the invention","ripe conditions make an invention likely, whoever produces it"],"answer":3,"explanation":"'Another would have, since the coal, the demand and the craftsmen were all in place' rests on the idea that ripe conditions make the invention likely whoever builds it.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-196","question":"Passage: Textbooks once told history as the deeds of great men: a king decided, a general triumphed, an inventor had a flash of insight. Later historians pushed back, arguing that individuals are carried along by forces larger than themselves: climate, trade, population and technology. If one inventor had not built the steam engine, they said, another would have, since the coal, the demand and the craftsmen were all in place. The correction was needed, but it can be pushed too far. Structural forces explain why something was likely to happen, not exactly when, how or in what form. A war that was 'bound to come' still began on a particular morning, after particular decisions by particular people, and those details shaped what followed for decades. Question: The author's own position is best described as:","options":["a return to the older view that only great men really make history","a complete rejection of structural explanations in favour of individual genius","the view that wars cannot be explained by any theory at all","forces matter, but individual choices shape the timing and form of events"],"answer":3,"explanation":"The author calls the structural correction 'needed' but warns that it 'can be pushed too far', since particular decisions still decide when, how and in what form events happen.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-197","question":"Passage: Textbooks once told history as the deeds of great men: a king decided, a general triumphed, an inventor had a flash of insight. Later historians pushed back, arguing that individuals are carried along by forces larger than themselves: climate, trade, population and technology. If one inventor had not built the steam engine, they said, another would have, since the coal, the demand and the craftsmen were all in place. The correction was needed, but it can be pushed too far. Structural forces explain why something was likely to happen, not exactly when, how or in what form. A war that was 'bound to come' still began on a particular morning, after particular decisions by particular people, and those details shaped what followed for decades. Question: The example of the war that was 'bound to come' is used to show that:","options":["wars are always caused by the decisions of a single powerful person","a likely event still unfolds through choices whose effects last","structural forces make every war impossible to avoid","historians cannot agree on exactly when wars begin"],"answer":1,"explanation":"The war may have been likely, but it began 'after particular decisions by particular people', and 'those details shaped what followed for decades'.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-198","question":"Passage: The precautionary principle holds that when an activity threatens serious harm, the lack of full scientific certainty should not be a reason to delay protective action. Stated that way, it is hard to quarrel with. The difficulty arises when the principle is applied to only one side of a decision. Banning a new pesticide because its long-term effects are uncertain may seem cautious, but if farmers respond by returning to an older chemical whose harms are well known, the ban may cause more damage than it prevents. Every choice, including the choice to forbid, carries risks of its own. A principle that looks only at the risks of acting, and never at the risks of not acting, is not caution but a bias wearing caution's clothes. Question: The author's main criticism is directed at:","options":["weighing the risks of acting while ignoring those of not acting","the idea that serious harms should be prevented in advance where possible","scientists who demand full certainty before taking any action","farmers who go back to older and more harmful pesticides"],"answer":0,"explanation":"The author accepts the principle as stated ('hard to quarrel with') and objects only when it is 'applied to only one side of a decision'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-199","question":"Passage: The precautionary principle holds that when an activity threatens serious harm, the lack of full scientific certainty should not be a reason to delay protective action. Stated that way, it is hard to quarrel with. The difficulty arises when the principle is applied to only one side of a decision. Banning a new pesticide because its long-term effects are uncertain may seem cautious, but if farmers respond by returning to an older chemical whose harms are well known, the ban may cause more damage than it prevents. Every choice, including the choice to forbid, carries risks of its own. A principle that looks only at the risks of acting, and never at the risks of not acting, is not caution but a bias wearing caution's clothes. Question: The pesticide example shows that:","options":["new pesticides are always safer than the older chemicals they replace on farms","the precautionary principle should never be applied to farming","a ban meant to cut risk may raise it by driving people to worse options","farmers usually ignore government bans on harmful chemicals"],"answer":2,"explanation":"Farmers obey the ban but switch to an older chemical with known harms, so the ban 'may cause more damage than it prevents'. Nothing says new pesticides are always safer.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-200","question":"Passage: The precautionary principle holds that when an activity threatens serious harm, the lack of full scientific certainty should not be a reason to delay protective action. Stated that way, it is hard to quarrel with. The difficulty arises when the principle is applied to only one side of a decision. Banning a new pesticide because its long-term effects are uncertain may seem cautious, but if farmers respond by returning to an older chemical whose harms are well known, the ban may cause more damage than it prevents. Every choice, including the choice to forbid, carries risks of its own. A principle that looks only at the risks of acting, and never at the risks of not acting, is not caution but a bias wearing caution's clothes. Question: The final sentence suggests that one-sided precaution is:","options":["a prejudice against action disguised as prudence","a genuine form of caution that should be encouraged","a scientific way of weighing risks","the only rational response to uncertainty"],"answer":0,"explanation":"'A bias wearing caution's clothes' means a prejudice that only looks like caution. The author denies it is real caution.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-201","question":"Passage: My mother's recipe notebook is useless to anyone but her. 'Enough salt,' it says. 'Cook till it smells right.' 'Add the tamarind when the onions are the colour of Grandmother's sari.' For years I thought this was carelessness and tried to pin her down: how many grams, how many minutes? She would look at me as if I had asked how many steps it took to walk home. Only after she fell ill and I tried to cook her dishes for her did I understand. The notebook was never meant to replace her; it was meant to remind her of what she already knew. The knowledge was in her hands and nose, and the words were only the knots in a handkerchief. I am slowly learning to read them, by burning a great many onions. Question: The narrator's early attempts to 'pin her down' reflect a belief that:","options":["her mother was deliberately hiding the real recipes from her own daughter","the notebook had been written for a professional cook","cooking knowledge could be fully captured in exact measurements","her mother had begun to forget how to cook her own dishes"],"answer":2,"explanation":"Asking 'how many grams, how many minutes?' shows the narrator assumed the dishes could be reduced to precise quantities. Nothing suggests secrecy or forgetfulness.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-202","question":"Passage: My mother's recipe notebook is useless to anyone but her. 'Enough salt,' it says. 'Cook till it smells right.' 'Add the tamarind when the onions are the colour of Grandmother's sari.' For years I thought this was carelessness and tried to pin her down: how many grams, how many minutes? She would look at me as if I had asked how many steps it took to walk home. Only after she fell ill and I tried to cook her dishes for her did I understand. The notebook was never meant to replace her; it was meant to remind her of what she already knew. The knowledge was in her hands and nose, and the words were only the knots in a handkerchief. I am slowly learning to read them, by burning a great many onions. Question: Comparing the notebook's words to 'knots in a handkerchief' implies that the words:","options":["were a secret code meant to keep the family recipes private","were jotted down in a confusing and random order without any plan at all","had been written hastily and were best ignored by others","were reminders of knowledge the writer already had, not instructions"],"answer":3,"explanation":"A knot in a handkerchief is a reminder that only means something to the person who tied it, which matches 'meant to remind her of what she already knew'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-203","question":"Passage: My mother's recipe notebook is useless to anyone but her. 'Enough salt,' it says. 'Cook till it smells right.' 'Add the tamarind when the onions are the colour of Grandmother's sari.' For years I thought this was carelessness and tried to pin her down: how many grams, how many minutes? She would look at me as if I had asked how many steps it took to walk home. Only after she fell ill and I tried to cook her dishes for her did I understand. The notebook was never meant to replace her; it was meant to remind her of what she already knew. The knowledge was in her hands and nose, and the words were only the knots in a handkerchief. I am slowly learning to read them, by burning a great many onions. Question: The tone of the last sentence is best described as:","options":["wry and affectionate","bitter and resentful","coldly detached","despairing"],"answer":0,"explanation":"'Burning a great many onions' pokes gentle fun at the narrator's own slow progress while showing love for the mother's way of cooking.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-204","question":"Passage: In the nineteenth century, an English economist noticed something odd about coal. Steam engines were becoming far more efficient, using less coal for each unit of work, yet the nation's total consumption of coal was rising, not falling. The reason was that efficiency made steam power cheaper, and cheaper power found countless new uses that had not been worth pursuing before. The same pattern has been observed since with lighting, cars and computing: as each unit of service becomes cheaper, people consume so many more units that total resource use may climb. This does not make efficiency pointless. It means that efficiency alone cannot be relied upon to cut consumption; if the goal is to use less, efficiency must be paired with something that keeps the saved resources from simply being spent elsewhere, such as a price on the resource itself. Question: The 'odd' observation about coal was that:","options":["more efficient engines went with greater total use of coal","coal became more expensive as engines steadily improved","engines used more coal per unit of work as time went on","the nation stopped using coal for anything except running engines"],"answer":0,"explanation":"Engines used less coal per unit of work 'yet the nation's total consumption of coal was rising'. The second option reverses the efficiency trend.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-205","question":"Passage: In the nineteenth century, an English economist noticed something odd about coal. Steam engines were becoming far more efficient, using less coal for each unit of work, yet the nation's total consumption of coal was rising, not falling. The reason was that efficiency made steam power cheaper, and cheaper power found countless new uses that had not been worth pursuing before. The same pattern has been observed since with lighting, cars and computing: as each unit of service becomes cheaper, people consume so many more units that total resource use may climb. This does not make efficiency pointless. It means that efficiency alone cannot be relied upon to cut consumption; if the goal is to use less, efficiency must be paired with something that keeps the saved resources from simply being spent elsewhere, such as a price on the resource itself. Question: The author would most likely agree that:","options":["efficiency improvements should be discouraged because they raise consumption","efficiency can raise total use unless price or supply is also managed","greater efficiency always reduces the total use of a resource","the pattern seen with coal was unique to the nineteenth century"],"answer":1,"explanation":"The author says efficiency is not pointless but 'cannot be relied upon' alone and should be paired with something like a price on the resource. The pattern is said to recur with lighting, cars and computing.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-206","question":"Passage: In the nineteenth century, an English economist noticed something odd about coal. Steam engines were becoming far more efficient, using less coal for each unit of work, yet the nation's total consumption of coal was rising, not falling. The reason was that efficiency made steam power cheaper, and cheaper power found countless new uses that had not been worth pursuing before. The same pattern has been observed since with lighting, cars and computing: as each unit of service becomes cheaper, people consume so many more units that total resource use may climb. This does not make efficiency pointless. It means that efficiency alone cannot be relied upon to cut consumption; if the goal is to use less, efficiency must be paired with something that keeps the saved resources from simply being spent elsewhere, such as a price on the resource itself. Question: Which of the following is the best example of the pattern the passage describes?","options":["After a factory installs efficient machines, its electricity bill falls and nothing else changes.","After buses become cheaper to run and fares fall, total fuel use rises as trips multiply.","After petrol prices rise sharply, people drive less and buy smaller cars.","After a new dam is built, farmers grow thirstier crops because water is now plentiful."],"answer":1,"explanation":"The pattern needs cheaper service per unit (through efficiency) that leads to so much more use that total consumption rises. The dam increases supply rather than efficiency, and the factory case shows no rebound.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-207","question":"Passage: Politicians love to open things. A new flyover, a new hospital wing or a new metro line comes with a ribbon, a plaque and a photograph. Maintaining what already exists comes with none of these. Repainting a bridge's steel to stop rust, clearing a drain before the monsoon or replacing worn pipes is invisible when it is done and noticed only when it is not, usually after a collapse or a flood. The incentives therefore tilt steadily towards building new assets and neglecting old ones, even though a rupee spent on maintenance often saves several rupees of later reconstruction. Some cities have tried to correct the bias by setting aside a fixed share of every budget for upkeep, so that it does not have to compete for attention with projects that photograph better. Question: According to the passage, maintenance is neglected mainly because:","options":["it costs more in the long run than building new assets","engineers prefer designing new projects to repairing old ones","it earns little credit, being noticed only when it fails","citizens object to repairs that disrupt their daily traffic"],"answer":2,"explanation":"Upkeep is 'invisible when it is done and noticed only when it is not', so it brings no ribbon or photograph. The passage says maintenance is actually cheaper in the long run.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-208","question":"Passage: Politicians love to open things. A new flyover, a new hospital wing or a new metro line comes with a ribbon, a plaque and a photograph. Maintaining what already exists comes with none of these. Repainting a bridge's steel to stop rust, clearing a drain before the monsoon or replacing worn pipes is invisible when it is done and noticed only when it is not, usually after a collapse or a flood. The incentives therefore tilt steadily towards building new assets and neglecting old ones, even though a rupee spent on maintenance often saves several rupees of later reconstruction. Some cities have tried to correct the bias by setting aside a fixed share of every budget for upkeep, so that it does not have to compete for attention with projects that photograph better. Question: The phrase 'projects that photograph better' suggests that spending decisions are shaped by:","options":["the quality of the drawings that architects submit to the city for approval","how many photographs ordinary citizens take of new public works","how impressive a project looks to the public, not just its real value","the cost of the publicity campaigns that announce projects"],"answer":2,"explanation":"The phrase picks up the ribbon-plaque-photograph image: projects with visible ceremony win attention over upkeep that may be worth more.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-209","question":"Passage: Politicians love to open things. A new flyover, a new hospital wing or a new metro line comes with a ribbon, a plaque and a photograph. Maintaining what already exists comes with none of these. Repainting a bridge's steel to stop rust, clearing a drain before the monsoon or replacing worn pipes is invisible when it is done and noticed only when it is not, usually after a collapse or a flood. The incentives therefore tilt steadily towards building new assets and neglecting old ones, even though a rupee spent on maintenance often saves several rupees of later reconstruction. Some cities have tried to correct the bias by setting aside a fixed share of every budget for upkeep, so that it does not have to compete for attention with projects that photograph better. Question: The fixed budget share for upkeep is meant to:","options":["reduce the total amount spent on the city's infrastructure","stop cities from building any new assets until repairs are done","shield upkeep money from competing with more glamorous projects","make maintenance work more visible to voters at election time"],"answer":2,"explanation":"The share is set aside 'so that it does not have to compete for attention' with showier projects. It does not ban new building or publicise repairs.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-210","question":"Passage: Ask people which is more dangerous, flying or driving, and many will hesitate, even though, mile for mile, flying is far safer. Psychologists trace the error to the way we estimate likelihood: we judge how common something is by how easily examples come to mind. A plane crash is reported for days, with pictures of wreckage; the steady toll of road deaths is reported, if at all, in a single line. Vivid, memorable events therefore seem more frequent than they are, and ordinary dangers fade into the background. The bias has costs. After a well-publicised air disaster, some travellers switch to driving, and in doing so expose themselves to a greater risk than the one they are fleeing. Question: According to the passage, people misjudge the danger of flying because:","options":["flying is in fact more dangerous than the official figures suggest","vivid, heavily reported events come to mind easily and seem more common","most people have little personal experience of driving over long distances","road deaths are never reported in the news at all"],"answer":1,"explanation":"We judge frequency 'by how easily examples come to mind', and crashes are vivid and much reported. Road deaths are reported 'if at all, in a single line', which is not the same as never.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-211","question":"Passage: Ask people which is more dangerous, flying or driving, and many will hesitate, even though, mile for mile, flying is far safer. Psychologists trace the error to the way we estimate likelihood: we judge how common something is by how easily examples come to mind. A plane crash is reported for days, with pictures of wreckage; the steady toll of road deaths is reported, if at all, in a single line. Vivid, memorable events therefore seem more frequent than they are, and ordinary dangers fade into the background. The bias has costs. After a well-publicised air disaster, some travellers switch to driving, and in doing so expose themselves to a greater risk than the one they are fleeing. Question: The last sentence implies that switching from flying to driving after an air disaster is:","options":["self-defeating, since it raises the traveller's risk","a sensible precaution to take after a crash","an effective way of escaping the availability bias altogether","unaffected by the media coverage of the crash"],"answer":0,"explanation":"The travellers 'expose themselves to a greater risk than the one they are fleeing', so the move defeats its own purpose, and it is driven by the coverage.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-212","question":"Passage: Ask people which is more dangerous, flying or driving, and many will hesitate, even though, mile for mile, flying is far safer. Psychologists trace the error to the way we estimate likelihood: we judge how common something is by how easily examples come to mind. A plane crash is reported for days, with pictures of wreckage; the steady toll of road deaths is reported, if at all, in a single line. Vivid, memorable events therefore seem more frequent than they are, and ordinary dangers fade into the background. The bias has costs. After a well-publicised air disaster, some travellers switch to driving, and in doing so expose themselves to a greater risk than the one they are fleeing. Question: Which of the following would be another example of the bias described in the passage?","options":["Fearing lightning more after a vivid news report about a strike","Choosing the cheaper of two otherwise identical products in a shop","Forgetting a close friend's birthday despite being reminded","Studying harder before an examination one expects to be difficult"],"answer":0,"explanation":"The bias is judging likelihood by how easily a vivid example comes to mind; a dramatic lightning report inflates the felt risk in the same way.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-213","question":"Passage: A narrator who tells us 'I am a calm and reasonable man' in the first paragraph and then describes, with mounting excitement, how he followed a neighbour for weeks, has told us more than he intends. Readers quickly learn to distrust him, and the pleasure of such stories lies in reading against the grain: noticing what the narrator leaves out, the excuses he offers too readily, the details that contradict his own account. The device is old, but it asks something unusual of the reader. In most fiction we accept what we are told and attend to what happens. With an unreliable narrator, the real story is partly assembled by the reader from the gaps between what is said and what is shown. Question: The narrator in the opening example 'has told us more than he intends' because:","options":["he openly admits, early in the story, that he cannot be trusted","his excited account of his conduct belies his claim to be calm","he describes his neighbour's habits with great precision","he narrates events in the exact order in which they happened"],"answer":1,"explanation":"He claims to be 'calm and reasonable' but describes stalking someone 'with mounting excitement', so his telling gives him away without his meaning it to.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-214","question":"Passage: A narrator who tells us 'I am a calm and reasonable man' in the first paragraph and then describes, with mounting excitement, how he followed a neighbour for weeks, has told us more than he intends. Readers quickly learn to distrust him, and the pleasure of such stories lies in reading against the grain: noticing what the narrator leaves out, the excuses he offers too readily, the details that contradict his own account. The device is old, but it asks something unusual of the reader. In most fiction we accept what we are told and attend to what happens. With an unreliable narrator, the real story is partly assembled by the reader from the gaps between what is said and what is shown. Question: As used in the passage, 'reading against the grain' means:","options":["reading critically to detect what the narrator hides or distorts","reading the story backwards, from its last page to its very first","rejecting the story as badly written and poorly constructed","reading only to follow the events of the plot as they unfold"],"answer":0,"explanation":"The passage defines it: noticing omissions, too-ready excuses and contradictory details in the narrator's account.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-215","question":"Passage: A narrator who tells us 'I am a calm and reasonable man' in the first paragraph and then describes, with mounting excitement, how he followed a neighbour for weeks, has told us more than he intends. Readers quickly learn to distrust him, and the pleasure of such stories lies in reading against the grain: noticing what the narrator leaves out, the excuses he offers too readily, the details that contradict his own account. The device is old, but it asks something unusual of the reader. In most fiction we accept what we are told and attend to what happens. With an unreliable narrator, the real story is partly assembled by the reader from the gaps between what is said and what is shown. Question: According to the passage, stories with unreliable narrators differ from most fiction in that:","options":["they contain no important events, only the narrator's thoughts","the author tells the reader directly which of the characters are lying","they are always narrated in the third person by an outsider","the reader must piece together the true story from gaps in the telling"],"answer":3,"explanation":"In most fiction 'we accept what we are told', but here 'the real story is partly assembled by the reader from the gaps'. The narrator in the example speaks as 'I', so third person is wrong.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-216","question":"Passage: A gift, anthropologists have long observed, is rarely free. In many societies, to accept a gift is to accept an obligation to return one, and to fail to do so is to lose standing. The return must not be too quick, which would look like settling a bill, nor too exact, which would turn friendship into trade; it should come later and be roughly, not precisely, equal. The vagueness is the point. A debt that is never quite settled keeps the relationship open, since each side always owes the other a little. A transaction settled in full, by contrast, leaves the two parties free never to meet again. Question: According to the passage, a return gift that is immediate and exactly equal would be inappropriate because it would:","options":["seem far too generous to the person receiving the return gift","insult the giver by suggesting the first gift was cheap","break a written law that governs gifts in many societies","make it a settled transaction and so close the relationship"],"answer":3,"explanation":"Too quick 'would look like settling a bill' and too exact 'would turn friendship into trade'; a settled transaction 'leaves the two parties free never to meet again'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-217","question":"Passage: A gift, anthropologists have long observed, is rarely free. In many societies, to accept a gift is to accept an obligation to return one, and to fail to do so is to lose standing. The return must not be too quick, which would look like settling a bill, nor too exact, which would turn friendship into trade; it should come later and be roughly, not precisely, equal. The vagueness is the point. A debt that is never quite settled keeps the relationship open, since each side always owes the other a little. A transaction settled in full, by contrast, leaves the two parties free never to meet again. Question: The statement 'The vagueness is the point' means that:","options":["anthropologists have failed to measure gifts accurately","people are careless about what their gifts are actually worth","gifts are best avoided because they only cause confusion","the imprecise return keeps both parties tied to each other"],"answer":3,"explanation":"A debt 'never quite settled keeps the relationship open', so the vagueness is the purpose, not a flaw.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-218","question":"Passage: Defenders of tipping say it rewards good service: a waiter who is attentive earns more than one who is surly. The research is less flattering. Studies of restaurant bills have found that the size of a tip depends only weakly on how good the service was, and much more on things the waiter cannot control or should not have to: the size of the bill, the weather, the customer's mood and, uncomfortably, the waiter's appearance. If tips mostly reflect such factors, they do little to motivate better service and a good deal to make workers' incomes unpredictable. That is why some restaurants have abolished tipping and raised menu prices to pay higher fixed wages instead. Question: The research mentioned undermines the defence of tipping by showing that tips:","options":["are almost always much smaller than what a good waiter actually deserves","are larger when the service is poor than when it is good","are mostly kept by restaurant owners rather than waiters","track service quality only weakly and depend largely on other factors"],"answer":3,"explanation":"Tips depend 'only weakly' on service and much more on the bill, the weather, mood and looks, so they cannot reliably reward good service. The research never says tips are larger for poor service.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-219","question":"Passage: Defenders of tipping say it rewards good service: a waiter who is attentive earns more than one who is surly. The research is less flattering. Studies of restaurant bills have found that the size of a tip depends only weakly on how good the service was, and much more on things the waiter cannot control or should not have to: the size of the bill, the weather, the customer's mood and, uncomfortably, the waiter's appearance. If tips mostly reflect such factors, they do little to motivate better service and a good deal to make workers' incomes unpredictable. That is why some restaurants have abolished tipping and raised menu prices to pay higher fixed wages instead. Question: The word 'uncomfortably' suggests that the author finds the link between tips and a waiter's appearance:","options":["amusing but essentially harmless to anyone","surprising but fair, given customers' differing tastes","troubling, since it rewards what should not matter","easy to correct with better staff training"],"answer":2,"explanation":"Appearance is listed among things the waiter 'should not have to' control; 'uncomfortably' marks it as unfair, not amusing or fair.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-220","question":"Passage: Before the railways, every town kept its own time, set by the sun. When it was noon in one town, it might be several minutes before or after noon in a town a hundred kilometres to the west, and nobody minded, since no one could travel between them fast enough to notice. Trains changed that. A timetable that listed departures in a dozen different local times invited confusion and, on single-track lines, collisions. Railway companies began to run their trains on a single standard time, and towns gradually followed, often grumbling that they had been robbed of their own noon. Standard time, now so natural that we rarely think of it, was in origin a technical convenience for one industry that the rest of society eventually adopted. Question: Local differences in time did not trouble people before the railways because:","options":["every town used exactly the same clock","travel was too slow for the differences to matter","most people did not own watches","towns were too far apart to trade with one another"],"answer":1,"explanation":"Nobody minded 'since no one could travel between them fast enough to notice'. The towns kept different times, which rules out the same clock.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-221","question":"Passage: Before the railways, every town kept its own time, set by the sun. When it was noon in one town, it might be several minutes before or after noon in a town a hundred kilometres to the west, and nobody minded, since no one could travel between them fast enough to notice. Trains changed that. A timetable that listed departures in a dozen different local times invited confusion and, on single-track lines, collisions. Railway companies began to run their trains on a single standard time, and towns gradually followed, often grumbling that they had been robbed of their own noon. Standard time, now so natural that we rarely think of it, was in origin a technical convenience for one industry that the rest of society eventually adopted. Question: The author's main point about standard time is that:","options":["a now-natural arrangement began as a practical fix for one industry","governments imposed standard time against the railways' wishes","towns lost money and trade when they adopted standard time","local solar time was more accurate than the standard time that replaced it"],"answer":0,"explanation":"The last sentence states it: standard time was 'a technical convenience for one industry that the rest of society eventually adopted'. The railways themselves began it.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-222","question":"Passage: Before the railways, every town kept its own time, set by the sun. When it was noon in one town, it might be several minutes before or after noon in a town a hundred kilometres to the west, and nobody minded, since no one could travel between them fast enough to notice. Trains changed that. A timetable that listed departures in a dozen different local times invited confusion and, on single-track lines, collisions. Railway companies began to run their trains on a single standard time, and towns gradually followed, often grumbling that they had been robbed of their own noon. Standard time, now so natural that we rarely think of it, was in origin a technical convenience for one industry that the rest of society eventually adopted. Question: The phrase 'robbed of their own noon' suggests that some towns:","options":["lost money because their town clocks were stolen","were made to work straight through the usual midday rest break","resented giving up a local custom tied to their identity","could no longer see the sun overhead at midday"],"answer":2,"explanation":"'Grumbling' and 'their own noon' show resentment at losing a locally set time; 'robbed' is figurative.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-223","question":"Passage: A famous experiment found that shoppers offered twenty-four varieties of jam were less likely to buy any than shoppers offered six. The result was taken up eagerly as proof that too much choice paralyses us, and it was cited in countless books and talks. Later attempts to repeat the effect produced a muddle: some found it, many did not, and a few found the opposite. The current view is more modest. Large assortments seem to discourage choice when the options are hard to compare, when the chooser has no clear preference and when the decision feels consequential; in other conditions variety is welcomed. The episode says as much about how findings spread as about how people shop. A striking, simple result travels far faster than the qualifications that later surround it. Question: The 'current view' described in the passage holds that:","options":["more choice always makes people less likely to buy anything","the original jam experiment was fabricated by its authors","big assortments deter choice only under certain conditions","variety of products never affects shoppers' final decisions"],"answer":2,"explanation":"The current view is 'more modest': big assortments discourage choice when options are hard to compare, preferences unclear and stakes high. Nothing suggests fraud.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-224","question":"Passage: A famous experiment found that shoppers offered twenty-four varieties of jam were less likely to buy any than shoppers offered six. The result was taken up eagerly as proof that too much choice paralyses us, and it was cited in countless books and talks. Later attempts to repeat the effect produced a muddle: some found it, many did not, and a few found the opposite. The current view is more modest. Large assortments seem to discourage choice when the options are hard to compare, when the chooser has no clear preference and when the decision feels consequential; in other conditions variety is welcomed. The episode says as much about how findings spread as about how people shop. A striking, simple result travels far faster than the qualifications that later surround it. Question: The last two sentences suggest that the author is chiefly concerned with:","options":["how jam and similar goods are marketed in supermarkets","how a striking finding spreads faster than its later qualifications","the dishonesty of the researchers who ran the original jam-tasting study","why shoppers dislike being offered too much variety"],"answer":1,"explanation":"'A striking, simple result travels far faster than the qualifications' shifts the focus to how findings spread. Failed repeats are not presented as proof of dishonesty.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-225","question":"Passage: A famous experiment found that shoppers offered twenty-four varieties of jam were less likely to buy any than shoppers offered six. The result was taken up eagerly as proof that too much choice paralyses us, and it was cited in countless books and talks. Later attempts to repeat the effect produced a muddle: some found it, many did not, and a few found the opposite. The current view is more modest. Large assortments seem to discourage choice when the options are hard to compare, when the chooser has no clear preference and when the decision feels consequential; in other conditions variety is welcomed. The episode says as much about how findings spread as about how people shop. A striking, simple result travels far faster than the qualifications that later surround it. Question: According to the current view, which situation is most likely to discourage a person from deciding?","options":["Picking a snack from a wide range of familiar favourites at a party","Choosing fruit from a large, varied basket when one already knows one wants an apple","Selecting a film from a large catalogue for a casual evening at home","Choosing among forty similar insurance plans, unsure, when the stakes are high"],"answer":3,"explanation":"Only the insurance case meets all three conditions: options hard to compare, no clear preference and a consequential decision. The others lack at least one.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-226","question":"Passage: The cobbler on the corner had mended Mr Khanna's shoes for thirty years without once being asked his name. Mr Khanna would drop them on the bench, say 'By Friday,' and leave. When the cobbler fell ill one winter, the shoes went instead to a shop in the market, which returned them glossy and stiff, with new heels that clicked on the marble of Mr Khanna's office. He wore them for a week and then, to his own surprise, walked to the corner to ask when the old man would be back. The neighbouring tea-seller did not know. 'You never asked him anything before,' he said, not unkindly. Mr Khanna had no answer to that, and stood by the empty bench a while longer than he could later explain. Question: The detail that the new heels 'clicked on the marble' suggests that the market shop's work:","options":["was so poorly done that the shoes soon began to fall apart at the seams","was exactly the smart finish Mr Khanna had always wanted","damaged the polished marble floor of his office building","was showy and unfamiliar, lacking the quiet fit of the cobbler's work"],"answer":3,"explanation":"'Glossy and stiff' heels that announce themselves contrast with thirty years of unnoticed mending, and within a week he goes looking for the old man. Nothing says the shoes fell apart.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-227","question":"Passage: The cobbler on the corner had mended Mr Khanna's shoes for thirty years without once being asked his name. Mr Khanna would drop them on the bench, say 'By Friday,' and leave. When the cobbler fell ill one winter, the shoes went instead to a shop in the market, which returned them glossy and stiff, with new heels that clicked on the marble of Mr Khanna's office. He wore them for a week and then, to his own surprise, walked to the corner to ask when the old man would be back. The neighbouring tea-seller did not know. 'You never asked him anything before,' he said, not unkindly. Mr Khanna had no answer to that, and stood by the empty bench a while longer than he could later explain. Question: The tea-seller's remark, 'You never asked him anything before', mainly serves to:","options":["gently show how impersonal his dealings with the cobbler had been","accuse Mr Khanna of having caused the cobbler's illness","explain where the cobbler had gone and when he was likely to return","praise Mr Khanna for his long loyalty to the old cobbler"],"answer":0,"explanation":"Said 'not unkindly', the remark points out that in thirty years Mr Khanna never even asked the man's name, and he 'had no answer'. It is a gentle rebuke, not an accusation or praise.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-228","question":"Passage: The cobbler on the corner had mended Mr Khanna's shoes for thirty years without once being asked his name. Mr Khanna would drop them on the bench, say 'By Friday,' and leave. When the cobbler fell ill one winter, the shoes went instead to a shop in the market, which returned them glossy and stiff, with new heels that clicked on the marble of Mr Khanna's office. He wore them for a week and then, to his own surprise, walked to the corner to ask when the old man would be back. The neighbouring tea-seller did not know. 'You never asked him anything before,' he said, not unkindly. Mr Khanna had no answer to that, and stood by the empty bench a while longer than he could later explain. Question: Mr Khanna's lingering by the empty bench most probably reflects:","options":["irritation that his shoes had not been properly mended on time","a plan to take over the cobbler's business himself","a dawning sense of loss for a bond he had taken for granted","fear that the tea-seller would think badly of him"],"answer":2,"explanation":"He goes 'to his own surprise' to ask after the old man and stays longer 'than he could later explain': a late awareness of what the relationship meant.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-229","question":"Passage: In 1912 a German meteorologist proposed that the continents had once been joined and had slowly drifted apart. He pointed to the way the coastlines of South America and Africa fit together, to matching fossils on both sides of the Atlantic and to rock formations that seemed to continue from one continent to the other. Geologists rejected the idea, and not simply out of prejudice. He could not explain what force was strong enough to push continents through the solid ocean floor, and the mechanisms he suggested were shown to be far too weak. Half a century later, evidence from the sea floor revealed that new crust is constantly forming along ocean ridges, supplying the missing mechanism, and his idea was absorbed into the theory of plate tectonics. It is tempting to tell this as a tale of a lone genius defeated by closed minds. It is more accurately a tale of a correct conclusion offered, for a time, without a convincing explanation. Question: According to the passage, geologists rejected the idea mainly because:","options":["the coastlines of South America and Africa do not in fact fit","fossils on the two sides of the Atlantic were completely different","no adequate mechanism for moving the continents had been shown","its author was a meteorologist rather than a geologist"],"answer":2,"explanation":"The passage says the rejection was 'not simply out of prejudice': he could not explain the force, and his suggested mechanisms were 'far too weak'. The outsider explanation is the trap.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-230","question":"Passage: In 1912 a German meteorologist proposed that the continents had once been joined and had slowly drifted apart. He pointed to the way the coastlines of South America and Africa fit together, to matching fossils on both sides of the Atlantic and to rock formations that seemed to continue from one continent to the other. Geologists rejected the idea, and not simply out of prejudice. He could not explain what force was strong enough to push continents through the solid ocean floor, and the mechanisms he suggested were shown to be far too weak. Half a century later, evidence from the sea floor revealed that new crust is constantly forming along ocean ridges, supplying the missing mechanism, and his idea was absorbed into the theory of plate tectonics. It is tempting to tell this as a tale of a lone genius defeated by closed minds. It is more accurately a tale of a correct conclusion offered, for a time, without a convincing explanation. Question: The author's view of the episode is that:","options":["geologists were blinded by prejudice against an outsider to their field","the theory of drifting continents was eventually shown to be entirely false","scientific consensus always turns out to be correct in the end","rejection was reasonable at the time, though the conclusion proved right"],"answer":3,"explanation":"The author rejects the 'lone genius defeated by closed minds' story and calls it 'a correct conclusion offered ... without a convincing explanation'. The idea was later absorbed into plate tectonics, not refuted.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-231","question":"Passage: In 1912 a German meteorologist proposed that the continents had once been joined and had slowly drifted apart. He pointed to the way the coastlines of South America and Africa fit together, to matching fossils on both sides of the Atlantic and to rock formations that seemed to continue from one continent to the other. Geologists rejected the idea, and not simply out of prejudice. He could not explain what force was strong enough to push continents through the solid ocean floor, and the mechanisms he suggested were shown to be far too weak. Half a century later, evidence from the sea floor revealed that new crust is constantly forming along ocean ridges, supplying the missing mechanism, and his idea was absorbed into the theory of plate tectonics. It is tempting to tell this as a tale of a lone genius defeated by closed minds. It is more accurately a tale of a correct conclusion offered, for a time, without a convincing explanation. Question: The evidence from the sea floor mattered because it:","options":["showed that the continents had never been joined at all","proved that the coastlines of the continents fitted together","supplied a process by which the continents could move","revealed new fossils matching those in Africa"],"answer":2,"explanation":"New crust forming along ocean ridges provided 'the missing mechanism', the very gap that had led to the original rejection.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-232","question":"Passage: If a man marries his housekeeper and she continues to cook and clean as before, but now without wages, the nation's measured output falls. The example is an old joke among economists, but it points to a serious blind spot. GDP counts work only when money changes hands. Cooking, cleaning, caring for children and the elderly, fetching water and fuel: when done unpaid within the household, as most of it is, and mostly by women, none of it appears in the national accounts. This is not merely an accounting curiosity. Policies judged by their effect on GDP may treat as costless a change that shifts burdens onto unpaid carers, such as cutting public care services, because the extra hours worked at home are never counted. Question: The example of the man who marries his housekeeper shows that GDP:","options":["can fall even when the useful work done stays the same","falls whenever people in the country get married","rises whenever families take on more household chores","measures the work done inside homes accurately and fully"],"answer":0,"explanation":"She does the same cooking and cleaning, but once wages stop, measured output falls, because GDP 'counts work only when money changes hands'.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-233","question":"Passage: If a man marries his housekeeper and she continues to cook and clean as before, but now without wages, the nation's measured output falls. The example is an old joke among economists, but it points to a serious blind spot. GDP counts work only when money changes hands. Cooking, cleaning, caring for children and the elderly, fetching water and fuel: when done unpaid within the household, as most of it is, and mostly by women, none of it appears in the national accounts. This is not merely an accounting curiosity. Policies judged by their effect on GDP may treat as costless a change that shifts burdens onto unpaid carers, such as cutting public care services, because the extra hours worked at home are never counted. Question: Why, according to the passage, might cutting public care services look costless when judged by GDP?","options":["Public care services make no contribution to GDP at all, since they are free to users.","Unpaid carers are compensated by the state for their extra work.","Cutting public services always raises GDP by reducing costs.","The extra care then done unpaid at home goes uncounted, hiding its burden."],"answer":3,"explanation":"The burden moves to unpaid carers, and 'the extra hours worked at home are never counted', so the cost is invisible in the measure used to judge the policy.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-234","question":"Passage: If a man marries his housekeeper and she continues to cook and clean as before, but now without wages, the nation's measured output falls. The example is an old joke among economists, but it points to a serious blind spot. GDP counts work only when money changes hands. Cooking, cleaning, caring for children and the elderly, fetching water and fuel: when done unpaid within the household, as most of it is, and mostly by women, none of it appears in the national accounts. This is not merely an accounting curiosity. Policies judged by their effect on GDP may treat as costless a change that shifts burdens onto unpaid carers, such as cutting public care services, because the extra hours worked at home are never counted. Question: As used in the passage, 'blind spot' refers to:","options":["a deliberate attempt by officials to hide data","a simple mistake in the arithmetic of GDP","economists' habit of joking about serious matters of policy","real economic activity that the measure fails to see"],"answer":3,"explanation":"The blind spot is unpaid household work, which really happens but is left out of the national accounts.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-235","question":"Passage: A dying friend asks you to scatter her ashes in the hills where she grew up. After her death, you realise that nobody else knows of the request, and the journey would be long and costly. Can you break the promise? She cannot be disappointed; she will never know. Yet most people feel that breaking it would be a wrong, and not merely a wrong against the living who might lose trust in promises generally. Some philosophers explain this by saying that our interests can extend beyond our lives: a person who cared deeply about where she would rest has an interest that can be honoured or betrayed after she is gone. Others reply that the feeling is real but misplaced, a habit formed among the living that we carry over to cases where it no longer applies. Question: The phrase 'and not merely a wrong against the living' indicates that many people believe breaking the promise:","options":["would harm no one at all, since the friend can never know","would wrong the dead friend herself, not only the living","would wrong only the friend's family and relatives","is acceptable as long as nobody else finds out"],"answer":1,"explanation":"'Not merely' means the wrong goes beyond its effect on the living, to the friend herself. The setup notes that no one else knows, yet people still feel it is wrong.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-236","question":"Passage: A dying friend asks you to scatter her ashes in the hills where she grew up. After her death, you realise that nobody else knows of the request, and the journey would be long and costly. Can you break the promise? She cannot be disappointed; she will never know. Yet most people feel that breaking it would be a wrong, and not merely a wrong against the living who might lose trust in promises generally. Some philosophers explain this by saying that our interests can extend beyond our lives: a person who cared deeply about where she would rest has an interest that can be honoured or betrayed after she is gone. Others reply that the feeling is real but misplaced, a habit formed among the living that we carry over to cases where it no longer applies. Question: The two philosophical positions described differ mainly on whether:","options":["promises should be made at all","a person's interests can outlast her death","the journey to the hills is too costly","people actually feel bound by such promises"],"answer":1,"explanation":"One side says interests 'extend beyond our lives'; the other calls the feeling 'real but misplaced'. Both accept that people feel bound, so the question is whether the dead have interests.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-237","question":"Passage: When a city renames a street, it rarely changes what people call it. Residents go on using the old name for decades, giving directions by it and printing it on wedding cards, while the official name lives mainly on signboards and in government files. Renaming is nonetheless a favourite act of governments, because it is cheap, symbolic and immediate: it announces whose memory the state wishes to honour. The gap between the two kinds of naming is revealing. A name imposed from above records the priorities of those in power at a particular moment; a name that survives in daily use records what the people who live there actually remember. A city's map, read carefully, is therefore two maps laid on top of each other. Question: According to the passage, governments favour renaming streets because it is:","options":["popular with residents, who adopt the new names at once","a way of making maps more accurate","cheap, symbolic and quick to carry out","required by law whenever a leader dies"],"answer":2,"explanation":"The passage says renaming is favoured 'because it is cheap, symbolic and immediate'. It also says residents keep the old names, which rules out the first distractor.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-238","question":"Passage: When a city renames a street, it rarely changes what people call it. Residents go on using the old name for decades, giving directions by it and printing it on wedding cards, while the official name lives mainly on signboards and in government files. Renaming is nonetheless a favourite act of governments, because it is cheap, symbolic and immediate: it announces whose memory the state wishes to honour. The gap between the two kinds of naming is revealing. A name imposed from above records the priorities of those in power at a particular moment; a name that survives in daily use records what the people who live there actually remember. A city's map, read carefully, is therefore two maps laid on top of each other. Question: The 'two maps' in the last sentence refer to:","options":["an old printed map of the city and a new digital one","names set by authority and names kept alive by everyday use","a map of the city's streets and a map of its buildings","the maps used by tourists and the ones used by city planners"],"answer":1,"explanation":"The previous sentence contrasts names 'imposed from above' with names that 'survive in daily use'; the two maps are these two layers of naming.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-239","question":"Passage: When a city renames a street, it rarely changes what people call it. Residents go on using the old name for decades, giving directions by it and printing it on wedding cards, while the official name lives mainly on signboards and in government files. Renaming is nonetheless a favourite act of governments, because it is cheap, symbolic and immediate: it announces whose memory the state wishes to honour. The gap between the two kinds of naming is revealing. A name imposed from above records the priorities of those in power at a particular moment; a name that survives in daily use records what the people who live there actually remember. A city's map, read carefully, is therefore two maps laid on top of each other. Question: Which of the following can be inferred from the passage?","options":["Residents usually adopt new street names within a few months of the change.","A surviving old name may record local memory better than the official one.","Governments rename streets mainly to help postal services deliver mail.","Official street names never appear on signboards or in files."],"answer":1,"explanation":"A name that survives in daily use 'records what the people who live there actually remember', while the official one records the priorities of those in power. Official names do appear on signboards.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-240","question":"Passage: Newspapers often quote 'a senior official who did not wish to be named'. Anonymity can be essential: a civil servant who reveals wrongdoing may lose her job, or worse, if identified. But anonymity also removes the reader's chief tool for judging a claim, namely knowing who is making it and what that person stands to gain. An official may hide behind it to float an idea he dare not own, to damage a rival, or to test public reaction before a decision. Responsible editors therefore treat anonymity as a privilege granted for a reason, not a convenience. They ask why the source needs protection, whether the claim can be checked another way, and whether readers can be told at least something, such as the source's department or the reason for the anonymity, to help them weigh what they read. Question: According to the passage, the main cost of anonymity to the reader is that it:","options":["hides who is making the claim and what they stand to gain","makes newspaper reports longer and harder to follow","exposes whistle-blowers to the risk of losing their jobs or worse","prevents editors from checking the facts of a story"],"answer":0,"explanation":"Anonymity 'removes the reader's chief tool for judging a claim, namely knowing who is making it and what that person stands to gain'. It protects whistle-blowers; it does not expose them.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-241","question":"Passage: Newspapers often quote 'a senior official who did not wish to be named'. Anonymity can be essential: a civil servant who reveals wrongdoing may lose her job, or worse, if identified. But anonymity also removes the reader's chief tool for judging a claim, namely knowing who is making it and what that person stands to gain. An official may hide behind it to float an idea he dare not own, to damage a rival, or to test public reaction before a decision. Responsible editors therefore treat anonymity as a privilege granted for a reason, not a convenience. They ask why the source needs protection, whether the claim can be checked another way, and whether readers can be told at least something, such as the source's department or the reason for the anonymity, to help them weigh what they read. Question: Which of the following practices would the author most likely endorse?","options":["Never quoting anonymous sources under any circumstances whatsoever","Granting anonymity to any official who asks for it, with no questions asked","Naming sources against their wishes whenever a claim is important enough","Granting anonymity only for good reason and naming the source's department"],"answer":3,"explanation":"The author accepts that anonymity 'can be essential' but treats it as 'a privilege granted for a reason', with readers told something about the source. A total ban and automatic anonymity are both rejected.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-242","question":"Passage: Newspapers often quote 'a senior official who did not wish to be named'. Anonymity can be essential: a civil servant who reveals wrongdoing may lose her job, or worse, if identified. But anonymity also removes the reader's chief tool for judging a claim, namely knowing who is making it and what that person stands to gain. An official may hide behind it to float an idea he dare not own, to damage a rival, or to test public reaction before a decision. Responsible editors therefore treat anonymity as a privilege granted for a reason, not a convenience. They ask why the source needs protection, whether the claim can be checked another way, and whether readers can be told at least something, such as the source's department or the reason for the anonymity, to help them weigh what they read. Question: As used in the passage, the word 'float' most nearly means:","options":["drift slowly on the surface of water","put forward tentatively to test reactions","withdraw quietly from any public discussion","make official and binding on everyone"],"answer":1,"explanation":"An official floats 'an idea he dare not own': he puts it out without commitment, alongside 'test public reaction'.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-243","question":"Passage: When almost every student in a course receives a top grade, the grade stops carrying information. An employer looking at a transcript full of A's learns that the student passed, but not whether she was outstanding or merely adequate. Grade inflation is often blamed on lenient teachers, but its causes are more structural. Where students rate their teachers and those ratings affect promotions, a teacher who grades strictly pays a personal price for keeping standards that benefit everyone. Each teacher who softens a little does little harm; together they drain the grades of meaning. Like many such problems, it is easier to solve collectively, for instance by reporting each grade alongside the share of the class who received it, than by asking individuals to resist pressures that reward giving in. Question: According to the passage, top grades given to almost everyone are a problem because they:","options":["stop employers telling outstanding students from adequate ones","make students work much harder than is really necessary to pass","are against the stated grading rules of most universities","cause strict teachers to lose their jobs or promotions"],"answer":0,"explanation":"'The grade stops carrying information': an employer cannot tell whether a student 'was outstanding or merely adequate'.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-244","question":"Passage: When almost every student in a course receives a top grade, the grade stops carrying information. An employer looking at a transcript full of A's learns that the student passed, but not whether she was outstanding or merely adequate. Grade inflation is often blamed on lenient teachers, but its causes are more structural. Where students rate their teachers and those ratings affect promotions, a teacher who grades strictly pays a personal price for keeping standards that benefit everyone. Each teacher who softens a little does little harm; together they drain the grades of meaning. Like many such problems, it is easier to solve collectively, for instance by reporting each grade alongside the share of the class who received it, than by asking individuals to resist pressures that reward giving in. Question: The author regards grade inflation as structural mainly because:","options":["ratings make strictness costly to each teacher, though it helps everyone","teachers today are simply lazier and more lenient than teachers in the past","students demand easier courses and lighter workloads","employers no longer bother to read students' transcripts"],"answer":0,"explanation":"Blaming 'lenient teachers' is set aside: where ratings affect promotion, each strict teacher 'pays a personal price', so individually small softenings add up to the problem.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-245","question":"Passage: When almost every student in a course receives a top grade, the grade stops carrying information. An employer looking at a transcript full of A's learns that the student passed, but not whether she was outstanding or merely adequate. Grade inflation is often blamed on lenient teachers, but its causes are more structural. Where students rate their teachers and those ratings affect promotions, a teacher who grades strictly pays a personal price for keeping standards that benefit everyone. Each teacher who softens a little does little harm; together they drain the grades of meaning. Like many such problems, it is easier to solve collectively, for instance by reporting each grade alongside the share of the class who received it, than by asking individuals to resist pressures that reward giving in. Question: Reporting each grade alongside the share of the class who received it would help because it would:","options":["force every teacher to give fewer top grades in future","stop students from rating their teachers at the end of each term's course","make transcripts shorter and easier for employers to read","show relative standing without needing teachers to resist pressure"],"answer":3,"explanation":"If most of the class got an A, the share shows that the A means little, so information returns at the level of the system and no individual teacher has to grade more strictly.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-246","question":"Passage: Automation is meant to reduce human error, and in routine conditions it does. But it creates a curious problem. When a system handles everything that is normal, the human operator is left only with what is abnormal: the rare emergency the designers did not foresee. Yet the operator, having spent months watching a machine do the work, has had little chance to practise. The more reliable the automation, the less skilled the person who must take over when it fails, and the less prepared she is for exactly the moment that matters most. Some designers now deliberately hand routine tasks back to operators from time to time, not because the machine needs help, but because the human does. Question: The 'curious problem' created by automation is that:","options":["machines make far more errors than humans do in real emergencies","operators refuse to trust automated systems that they do not fully understand","reliable automation leaves operators unpractised for the rare crisis","designers deliberately make their systems unreliable"],"answer":2,"explanation":"Reliable automation leaves operators only the unforeseen emergencies while denying them practice: 'The more reliable the automation, the less skilled the person who must take over'.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-247","question":"Passage: Automation is meant to reduce human error, and in routine conditions it does. But it creates a curious problem. When a system handles everything that is normal, the human operator is left only with what is abnormal: the rare emergency the designers did not foresee. Yet the operator, having spent months watching a machine do the work, has had little chance to practise. The more reliable the automation, the less skilled the person who must take over when it fails, and the less prepared she is for exactly the moment that matters most. Some designers now deliberately hand routine tasks back to operators from time to time, not because the machine needs help, but because the human does. Question: The final sentence suggests that routine tasks are handed back to operators in order to:","options":["reduce wear and tear on the expensive machines","save electricity and other running costs","check whether the machine has developed a fault","keep operators' skills sharp for emergencies"],"answer":3,"explanation":"The tasks are returned 'not because the machine needs help, but because the human does', meaning the operator needs practice.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-248","question":"Passage: Keeping honeybees has become a popular way to 'save the bees'. Rooftop hives have appeared on offices and hotels, and their honey is sold with a conservation label. Ecologists are uneasy. The honeybee is a single, domesticated species, managed like livestock and in no danger of disappearing. The pollinators that are declining are mostly wild: hundreds of species of solitary bees, bumblebees and hoverflies. Where hives are packed densely into a city, honeybees may compete with these wild insects for the same limited flowers. Adding hives to help pollinators is a little like keeping chickens to help wild birds. Those who genuinely want to help would do better to plant a variety of flowering plants and leave patches of bare ground and dead wood where wild bees nest. Question: The ecologists are uneasy about rooftop hives mainly because:","options":["honey from city hives is unsafe to eat because of pollution","honeybees are close to extinction and should not be disturbed by people at all","honeybees aren't under threat and may crowd out wild pollinators that are","rooftop hives damage the roofs of the buildings they stand on"],"answer":2,"explanation":"The honeybee is domesticated and 'in no danger of disappearing', while declining wild pollinators may lose flowers to dense hives. Saying honeybees are endangered reverses the passage.","difficulty":"hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-249","question":"Passage: Keeping honeybees has become a popular way to 'save the bees'. Rooftop hives have appeared on offices and hotels, and their honey is sold with a conservation label. Ecologists are uneasy. The honeybee is a single, domesticated species, managed like livestock and in no danger of disappearing. The pollinators that are declining are mostly wild: hundreds of species of solitary bees, bumblebees and hoverflies. Where hives are packed densely into a city, honeybees may compete with these wild insects for the same limited flowers. Adding hives to help pollinators is a little like keeping chickens to help wild birds. Those who genuinely want to help would do better to plant a variety of flowering plants and leave patches of bare ground and dead wood where wild bees nest. Question: The comparison with 'keeping chickens to help wild birds' is meant to show that:","options":["adding domestic animals does little for declining wild relatives","chickens and honeybees need very similar care from their keepers","wild birds depend on chickens for much of their food","keeping animals in cities is always cruel to them"],"answer":0,"explanation":"Chickens, like honeybees, are farmed animals that look like the wild group in trouble; adding more of them does not help, and may harm, the wild group.","difficulty":"very-hard","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-250","question":"Passage: Keeping honeybees has become a popular way to 'save the bees'. Rooftop hives have appeared on offices and hotels, and their honey is sold with a conservation label. Ecologists are uneasy. The honeybee is a single, domesticated species, managed like livestock and in no danger of disappearing. The pollinators that are declining are mostly wild: hundreds of species of solitary bees, bumblebees and hoverflies. Where hives are packed densely into a city, honeybees may compete with these wild insects for the same limited flowers. Adding hives to help pollinators is a little like keeping chickens to help wild birds. Those who genuinely want to help would do better to plant a variety of flowering plants and leave patches of bare ground and dead wood where wild bees nest. Question: What does the author recommend for those who want to help pollinators?","options":["Installing more honeybee hives on office and hotel rooftops","Planting varied flowers and leaving nesting places for wild bees","Buying only honey that carries a conservation label","Clearing dead wood and bare patches out of gardens to keep them tidy"],"answer":1,"explanation":"The last sentence recommends 'a variety of flowering plants' and leaving 'bare ground and dead wood where wild bees nest'. Clearing dead wood is the opposite.","difficulty":"moderate","source":"CAT · IBPS PO Mains · SSC CGL Tier 2"},
  {"id":"eng-reading-comprehension-251","question":"Passage: Lichens, partnerships between a fungus and an alga, have no roots and take in water and nutrients straight from air and rain. This makes them sensitive to pollutants such as sulphur dioxide: in heavily polluted city centres few species survive, while a richer variety grows in cleaner suburbs. Scientists sometimes survey lichens as a cheap guide to air quality. But the method has limits. Lichens reflect conditions averaged over years, so they cannot capture a sudden spike in pollution, and they cannot say which pollutant is responsible. Question: Which of the following can be inferred from the passage?","options":["Lichens take in most of their nutrients through roots, which is why pollutants damage them","A suburb with a rich variety of lichens must be entirely free of every kind of pollutant","A lichen survey would be a poor tool for detecting a brief, one-day surge in pollution","Lichen surveys are more costly than electronic monitors but are preferred for their accuracy"],"answer":2,"explanation":"Since lichens average conditions over years, a one-day spike would barely register. Lichens have no roots, a rich variety does not prove zero pollution, and the passage calls surveys cheap, not costly.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-252","question":"Passage: Studies comparing paper and screen reading often report that readers remember the sequence of a story better after reading print. Critics note, however, that most participants grew up reading on paper, and that the screens in the experiments were often glary tablets rather than modern e-ink readers. The finding, they say, may reflect familiarity rather than anything built into the medium. Question: Which of the following, if true, would most strengthen the critics' view?","options":["Participants who had read mostly on screens since childhood showed no memory advantage for print","Paper books continue to outsell e-books in every country where the studies were carried out","Readers of printed stories also said that they enjoyed those stories more than screen readers did","E-ink readers are lighter and easier to carry than most printed books of the same length"],"answer":0,"explanation":"If screen-raised readers show no print advantage, familiarity rather than the medium explains the result. Sales figures, enjoyment and weight do not bear on memory or on the critics' point.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-253","question":"Passage: In old tailoring workshops an apprentice spent the first year sweeping floors, sharpening shears and threading needles before he was allowed to touch cloth. Modern training schools call this wasteful and compress it into a month of stitching drills. Veteran tailors reply that the sweeping years taught apprentices to read the master's habits: how he chalked a line, when he paused, what he rejected. Such knowledge, they say, cannot be written into a syllabus. Question: The veteran tailors regard the early chores as:","options":["a test of obedience to be passed before real instruction starts","a way for workshop owners to obtain cheap labour from beginners","an outdated custom that the modern schools were right to drop","an informal channel through which unwritten skills were absorbed"],"answer":3,"explanation":"The veterans say the chores let apprentices pick up what the master did, knowledge that cannot be syllabused. Obedience tests and cheap labour are not suggested by the passage, and the veterans do not call the custom outdated.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-254","question":"Passage: House sparrows have vanished from many city neighbourhoods. Explanations abound: mobile towers, pesticides, glass-fronted buildings. Yet careful counts in one city found sparrows thriving in old lanes with tiled roofs and dusty courtyards, but absent from new apartment blocks, although both areas had the same number of mobile towers. The pattern points less to a single poison than to the loss of nesting niches and of the insects that feed chicks. Question: The author compares old lanes with new blocks mainly to:","options":["show that sparrows prefer crowded places to open ones","weaken one popular explanation by keeping that factor equal in both areas","prove that pesticides are the main cause of the sparrows' decline","argue that old buildings should be preserved for their historic value"],"answer":1,"explanation":"Both areas had the same mobile-tower density, yet sparrows differed, so towers cannot be the main cause. The passage does not blame pesticides or discuss heritage preservation.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-255","question":"Passage: Engineers who study old stone bridges are struck by how well they have lasted, and some conclude that earlier builders were more careful than modern ones. But the bridges that survive are exactly those that were well built; the many poorly built ones collapsed long ago and left no trace. Our impression of past craftsmanship is therefore formed from a sample that time has already filtered. Question: The author's main point is that:","options":["modern builders use materials that are weaker than the stone used in earlier times","earlier builders were careful because the cost of failure was borne by the builders themselves","most old bridges remain standing because they are inspected and repaired every year","judgements about earlier builders are distorted because only the sturdy structures remain to be seen"],"answer":3,"explanation":"The point is survivorship: only well-built bridges survive to be judged, so the sample is biased. The other options bring in ideas (materials, builder liability, repairs) that the passage never states.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-256","question":"Passage: Some early literatures seem to lack a word for blue. This has led a few writers to claim that ancient people could not see the colour. Linguists reply that having no word is not the same as having no perception: several languages today use one word for both green and blue, yet their speakers can tell the two apart in tests. A name, in other words, follows need and habit, not eyesight. Question: Which of the following would the author most probably accept?","options":["The absence of a colour word in a text is weak evidence about the vision of its writers","Languages with a single word for green and blue are certain to be older than other languages","Ancient writers deliberately avoided colour terms because they thought them unimportant","Speakers of languages with fewer colour words are better at telling colours apart in tests"],"answer":0,"explanation":"The author argues that a missing word does not show missing perception, so it is weak evidence about eyesight. Nothing is said about age of languages, deliberate avoidance, or superior test performance.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-257","question":"Passage: In a classic classroom demonstration, a teacher asks students to guess the number of beans in a jar. Individual guesses vary wildly, yet the average of all the guesses usually lands close to the true count. The effect depends on the guesses being independent: if students first hear a confident classmate announce a figure, their errors begin to move together and the average loses its accuracy. Question: According to the passage, which of the following would reduce the accuracy of the group average?","options":["Allowing students to take more time before they write down a figure","Increasing the number of students who take part in the guessing","Telling students beforehand that the jar holds fewer than a thousand beans","Letting students revise their guesses after hearing one person's confident estimate"],"answer":3,"explanation":"Independence is the condition for accuracy; hearing one confident figure makes errors correlated. More students or more time does not break independence, and the passage does not say that a range hint harms accuracy.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-258","question":"Passage: A ferry operator that has spent heavily on a new terminal is reluctant to cancel an unprofitable route, saying it cannot waste the investment. But the money is gone whether or not the route continues. The only sensible question is whether the future income from the route will exceed its future costs. Treating past spending as a reason to carry on turns one loss into two. Question: The author would most likely advise the operator to:","options":["keep the route running until the terminal's cost has been fully recovered","judge the route only on its expected future income and future costs","sell the terminal at once to recover as much of the investment as possible","reduce the number of ferries without changing the fares on the route"],"answer":1,"explanation":"The passage says past spending is irrelevant and only future income against future costs matters. Waiting to recover the terminal's cost is exactly the error it describes.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-259","question":"Passage: Before railways, each town set its clocks by the sun, so noon in one city differed by minutes from noon in the next. This was harmless when travel was slow. Timetables changed that: a train could not run to a dozen local times. Railway companies therefore adopted a single standard time, and the public followed, not because any law demanded it, but because keeping local time meant missing trains. Question: According to the passage, the public adopted standard time mainly because:","options":["scientists proved that the sun's position was an unreliable guide to the hour","local time was abolished by the law once railway companies requested it","keeping separate local times made it easy to miss one's train","towns wanted their noon to coincide with the noon of neighbouring cities"],"answer":2,"explanation":"The passage says it was not law but the daily penalty of missing trains that drove the public to follow railway time. The other reasons are either denied or never mentioned.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-260","question":"Passage: Speed breakers slow vehicles at the spot where they are placed, yet some studies find that drivers brake hard before them and accelerate sharply afterwards, so average speeds along the road barely change. Ambulances and buses are slowed just as much as private cars. Engineers increasingly favour narrowing carriageways or placing visible pedestrian crossings, which make drivers slow down because they judge the road to be riskier. Question: It can be inferred that engineers prefer narrowing carriageways because:","options":["they change the driver's sense of risk along a stretch rather than at a single point","they cost far less to build and maintain than a speed breaker does","they permit ambulances and buses to travel faster than private cars","they remove the need for pedestrian crossings on busy roads altogether"],"answer":0,"explanation":"The passage contrasts a point effect (speed breakers) with an effect on perceived risk along the road. Cost and the removal of crossings are not mentioned, and narrowing roads does not favour ambulances.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-261","question":"Passage: Students who type lecture notes can capture almost every word, and often do, since typing is fast. Those who write by hand cannot keep up and must decide what matters. Experiments suggest that the handwriters understand concepts better, though the typists have longer notes. The effort of choosing what to write, rather than the pen itself, seems to be what helps. Question: Which of the following would the author be most likely to say about a typist who deliberately summarises in her own words?","options":["She will still do worse than handwriters because the keyboard blocks understanding","She will remember more only if she types faster than the average student","She will produce shorter notes but understand less of the lecture's content","She may gain much of the benefit usually attributed to handwriting"],"answer":3,"explanation":"If the benefit comes from selecting and rephrasing, not from the pen, a typist who does so should gain it too. The other options contradict this reasoning.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-262","question":"Passage: Many weather proverbs, such as ‘red sky at night, shepherd's delight’, hold up because they encode real regularities: in mid-latitudes weather generally moves from west to east, so a clear western sky at sunset suggests that fair weather is arriving. But proverbs fail when carried to places where prevailing winds differ. A saying is thus a local forecast, not a universal law. Question: The author's attitude to weather proverbs is best described as:","options":["unqualified admiration","qualified respect","open scepticism","amused indifference"],"answer":1,"explanation":"The author grants that proverbs rest on real patterns but limits them to places where those patterns hold, which is qualified respect. There is no admiration without conditions, no scepticism and no indifference.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-263","question":"Passage: Small loans to poor women were once hailed as a way out of poverty. Later studies found that for most borrowers the loans did not raise incomes much; they were used to smooth consumption or to stretch household budgets. This does not make the loans worthless: smoothing a bad month may spare a family from selling its assets. It does suggest that they are a tool for stability rather than a ladder out of poverty. Question: The central claim of the passage is that microloans:","options":["mainly help households cope with shocks rather than rise out of poverty","fail to benefit borrowers and should therefore be withdrawn from poor areas","raise the incomes of most women who borrow them for small businesses","should be given only to families who already own some saleable assets"],"answer":0,"explanation":"The passage calls the loans a tool for stability rather than a ladder out of poverty. It explicitly rejects calling them worthless, and it neither says incomes rise nor restricts loans to those with assets.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-264","question":"Passage: As Himalayan glaciers shrink, the rivers they feed first carry more water, because ice melts faster. Planners may take this surge as a lasting gain and build irrigation for larger fields. But once the ice reserves dwindle, the flow will fall below its earlier levels. The danger lies in mistaking a temporary windfall for a permanent supply. Question: The ‘danger’ mentioned in the passage is that:","options":["glaciers may melt so fast that they flood the fields downstream","irrigation canals may be built too close to the glaciers' edge","a short-term rise in flow may lead to commitments that cannot be sustained","farmers may refuse to use the extra water that the glaciers supply"],"answer":2,"explanation":"The danger is treating a temporary surge as permanent and building for it, only to face lower flow later. Flooding, canal location and farmers' refusal are not discussed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-265","question":"Passage: Tea bushes grow well under scattered shade trees, which keep leaf temperatures even, add leaf litter to the soil and shelter birds that eat pests. Yet many estates have felled shade trees to let in more sun, hoping for faster growth. Yields rise for a time, but the soil thins and pest-control bills climb. The estate gains a good season and then pays for it over many. Question: What does the passage suggest about felling the shade trees?","options":["It should be done only on estates where birds are scarce","Its gains come early while its costs build up later","It has no effect on yields once the first season has passed","Its costs are borne chiefly by neighbouring estates and not the owner"],"answer":1,"explanation":"The last sentence says one good season is followed by many seasons of cost, i.e. early gains and later costs. The passage does not mention bird scarcity or neighbouring estates and says yields do rise at first.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-266","question":"Passage: Salt-pan workers on dry coastal flats start before dawn, raking brine under a sun that blisters. They are poorly paid and hardly seen in policy debates, though the salt on every kitchen shelf passes through their hands. Their illnesses, especially of the eyes and feet, are rarely recorded, because the workers move with the season and no clinic follows them. Question: According to the passage, why are the workers' illnesses rarely recorded?","options":["The workers refuse treatment because they cannot afford to miss a day's wages","Doctors believe that eye and foot ailments are not serious enough to record","Policy debates have so far treated salt production as a minor industry","No health service accompanies workers who migrate with the seasons"],"answer":3,"explanation":"The passage gives the reason directly: the workers move with the season and no clinic follows them. Refusal of treatment and doctors' views are not mentioned.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-267","question":"Passage: Typewriter sales have crept up among young writers who say that the machine forbids endless editing: each mistake is permanent and each sentence must be thought through before it is typed. Sceptics call it affectation. Yet the practice may simply be a self-imposed constraint, like a poet's choosing a sonnet's fourteen lines. The limit does not hinder creativity; it channels it. Question: The comparison with the sonnet is meant to show that:","options":["limits chosen voluntarily can stimulate creative work","old forms of writing are generally better than modern ones","poets and typists face similar difficulties in revising their work","the typewriter is as ancient a device as the sonnet is a form"],"answer":0,"explanation":"The sonnet is an example of a freely chosen limit that helps creativity, which is the author's defence of the typewriter. Nothing is said about old forms being better or about revision difficulties.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-268","question":"Passage: Planting trees is often prescribed as the cure for urban heat. Trees do cool streets, through shade and through evaporation from leaves. But a sapling offers little shade for a decade, and street trees in cramped pits often die young. A city that counts saplings planted rather than canopy achieved will report progress while its pavements stay hot. Question: The author is critical of:","options":["planting trees along streets in place of building more parks","relying on evaporation rather than shade to cool the city","measuring tree programmes by the number planted rather than the shade provided","spending public money on urban heat when other problems are more urgent"],"answer":2,"explanation":"The final sentence criticises counting saplings instead of canopy. The author accepts that trees cool streets and does not oppose tree planting, parks or the spending itself.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-269","question":"Passage: A placebo is an inert pill, yet patients given one often report relief. Some conclude that the pain must have been imaginary. This is a mistake: placebos can trigger the release of natural painkillers in the brain, so the relief is real, although its source is the patient's expectation rather than the pill's chemistry. The effect shows how closely belief and body are linked, not that symptoms are fake. Question: Which of the following best expresses the author's view?","options":["Patients who respond to placebos should be treated as if they had no real illness","Relief from a placebo is genuine even though the pill has no active ingredient","Placebos are as effective as medicines for treating every kind of serious illness","Pain relief caused by belief is weaker in effect than relief caused by drugs"],"answer":1,"explanation":"The author insists the relief is real while its cause is expectation. The other options either dismiss placebo responders, overstate placebo power, or compare strengths, none of which is stated.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-270","question":"Passage: In a factory study, output rose whenever researchers altered the lighting, whether brighter or dimmer. The workers, it seems, were responding to the attention they were receiving rather than to the lighting itself. The lesson for managers is double-edged: observation can improve performance, but it makes any improvement during a trial hard to credit to the change being tested. Question: Which of the following inferences is best supported by the passage?","options":["Dim lighting is as good for factory output as bright lighting","Workers perform better only when they are told that they are being studied","Managers should avoid all trials, because trials always mislead","A trial conducted under observation can overstate the benefit of the change tested"],"answer":3,"explanation":"If observation itself lifts output, the gain seen during a trial may be wrongly credited to the change under test. The passage does not conclude that lighting is irrelevant to output, that workers do better only when told, or that trials should be avoided.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-271","question":"Passage: On a village common that anyone may use, each herder gains fully from adding an animal but shares the cost of overgrazing with all. On this logic each adds one more, and the pasture is ruined. Yet many villages have protected their commons for centuries through rules on numbers and penalties for cheats. The tragedy, therefore, is not inevitable; it is what happens when such rules are absent. Question: Which of the following would the author agree with?","options":["Shared resources can be preserved where a community enforces agreed limits","Herders are by nature unable to restrain their own greed for more animals","Common land should be divided among individual families to prevent ruin","Overgrazing is a problem only on commons that are large and poorly guarded"],"answer":0,"explanation":"The author cites villages that protected commons through enforced rules, so shared resources can survive with limits. The passage does not say herders are incapable of restraint, nor does it propose dividing the common.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-272","question":"Passage: A student who spends a Saturday at a free lecture says it cost nothing. An economist would disagree: the cost of any choice is the best alternative given up. If the student could have earned a thousand rupees tutoring that day, then the ‘free’ lecture costs a thousand rupees in the sense that matters for the decision. Free is a statement about price, not about cost. Question: The last sentence of the passage means that:","options":["services offered without a fee are usually worth less than paid services","a service can carry no fee and yet require giving up something valuable","price and cost are two different words for the same economic idea","lectures should be priced to reflect what students could have earned instead"],"answer":1,"explanation":"Price is what is charged; cost includes what is sacrificed. A free lecture can have a price of zero but a real cost. The other options misread the distinction.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-273","question":"Passage: In a sealed-bid auction where the highest bidder wins and pays her own bid, rational bidders bid below their true valuation so as to leave themselves a profit. In an auction where the winner pays the second-highest bid, honest bidding is the best strategy: bidding higher risks overpaying and bidding lower risks losing something worth having. The design of the rules thus shapes whether bidders tell the truth. Question: Which statement best summarises the passage?","options":["Bidders in sealed auctions always bid lower than the value they place on the item","Honest bidding is never possible when the winner pays her own bid","The rules of an auction influence whether bidders reveal their true valuation","Second-price auctions raise more money for sellers than first-price auctions do"],"answer":2,"explanation":"The passage's conclusion is that rule design shapes truthful bidding. 'Always lower' overstates the first case, 'never possible' is too strong, and revenue is not discussed.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-274","question":"Passage: The ‘memory palace’ technique asks a person to place items to be remembered along a familiar route, such as the rooms of a home, and later to walk the route mentally. It works because human memory for places and images is far stronger than for lists and abstractions. The method's weakness is that it suits concrete items; abstract ideas must first be turned into pictures, a step that can take longer than learning them outright. Question: According to the passage, the memory palace is LEAST suited to:","options":["a shopping list of ordinary household items","the names of rooms in a familiar home","a sequence of objects shown in a photograph","abstract ideas that must first be converted into images"],"answer":3,"explanation":"The passage names abstract ideas as the weakness, since converting them into pictures can cost more time than simply learning them. Concrete items such as a shopping list suit the method well.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-275","question":"Passage: Customers waiting in a single queue that feeds several counters are generally served more fairly, and often faster, than those who pick among separate queues, because one slow transaction in a separate queue holds up everyone behind it. Yet many shops keep parallel queues, since each customer feels in control when allowed to choose. Perceived control, it seems, is valued over actual waiting time. Question: The passage implies that shops retain separate queues because:","options":["customers appear to prefer the feeling of choice to shorter average waits","a single queue requires more counters than the shop can afford to staff","separate queues serve customers with slow transactions more fairly","a single queue discourages customers from visiting the shop again"],"answer":0,"explanation":"The author says perceived control is valued over actual waiting time, implying shops cater to that preference. Staffing costs, fairness to slow customers and customer loss are not stated.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-276","question":"Passage: Many woodland wildflowers bear seeds with a fatty appendage that ants find irresistible. The ants carry the seeds to their nests, eat the appendage and discard the seed in a waste chamber, where it sprouts in soil enriched by the ants. The flower pays in fat; the ant provides transport and fertiliser. Remove the ants from a woodland and these flowers will not vanish at once, but their spread will stall, and the patches on the forest floor will grow older and thinner. Question: Which of the following is the most likely result of the ants' disappearance from such a woodland?","options":["The flowers would spread faster, because the seeds would no longer be eaten by ants","The flowers would die out within a single season for want of fertile soil","The existing patches would flourish, since competition for the seeds would end","The flowers would persist for a while but would find it harder to colonise new ground"],"answer":3,"explanation":"The passage says the flowers would not vanish at once, but their spread would stall. That is persistence without colonisation, not rapid spread, sudden death or flourishing.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-277","question":"Passage: A cinema sells small popcorn at ₹120 and large at ₹220, and few customers choose the large. When a medium size at ₹210 is added, sales of the large jump, though almost nobody buys the medium. The medium was never meant to be bought; its job is to make the large look like a bargain by comparison. Shoppers rarely judge value in isolation; they judge it against whatever the seller places beside it. Question: The medium-sized popcorn in the passage serves mainly to:","options":["make the large size appear to be better value","tempt buyers away from the small size","raise the average price paid for medium portions","test how many customers read the price board"],"answer":0,"explanation":"The medium is a decoy: its near-large price makes the large look cheap by comparison. The passage says almost nobody buys the medium, and it does not discuss the small size or test reading habits.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-278","question":"Passage: Along one stretch of coast, fishermen's work songs list rocks, sandbanks and the order of landmarks as a boat nears harbour. To outsiders the songs are charming folk art; to the singers they are charts, memorised in rhythm because rhythm survives fear and fatigue better than prose does. When GPS replaces the songs, a boat may find harbour more easily, but a body of knowledge about the coast that was never written anywhere is lost with them. Question: The author's attitude to the replacement of the songs by GPS is best described as:","options":["wholly approving of the new technology and its safety benefits","regretful about what is lost, though not hostile to GPS itself","bitterly opposed to any use of modern technology at sea","detached and uninterested in the fate of the old songs"],"answer":1,"explanation":"The author concedes that GPS helps boats find harbour but laments the loss of unwritten knowledge, which is regret without hostility. The passage is neither fully approving nor bitter nor detached.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-279","question":"Passage: Ice-cream sales and drowning deaths rise and fall together across the year. No one concludes that ice cream causes drowning; a third factor, summer heat, drives both. Yet when the same pattern appears in less familiar settings, say between private tutoring and exam scores, we are quick to assume a causal link. The test for causation is not whether two things move together but whether a hidden factor can account for both. Question: The author uses the ice-cream example to:","options":["warn parents against letting children eat ice cream near water","show that drowning deaths are mainly a result of hot weather","show how a hidden common factor can create a false look of causation","argue that tutoring has no influence on the scores of students"],"answer":2,"explanation":"The example is a familiar case of a common cause (heat) mimicking a causal link. The author does not claim anything about tutoring itself; the comparison only shows that we apply the logic unevenly.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-280","question":"Passage: Forecasters who appear often on television tend to be more confident and more dramatic than those who do not, and they are no more accurate. Producers prefer them because a bold, clear prediction makes better viewing than a cautious one. Over time the audience remembers the confident forecaster's hits and forgets his misses, while the careful forecaster, whose modest probabilities are often right, gets little airtime. Question: Which of the following is implied by the passage?","options":["Cautious forecasters make more accurate predictions than confident ones","Producers deliberately select forecasters whom they know to be inaccurate","Confident forecasters lose their audience as soon as their predictions fail","A forecaster's visibility is a poor guide to how accurate he really is"],"answer":3,"explanation":"Television forecasters are no more accurate than the others, so being seen often says little about accuracy. The passage does not claim that cautious forecasters are more accurate, that producers know the forecasters are wrong, or that audiences desert them.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-281","question":"Passage: For decades, foresters put out every fire in dry pine forests, believing fire to be pure destruction. The forests grew thick with undergrowth and dead wood, and when fires finally came they were hotter and more destructive than the small, frequent burns that had once cleared the floor. Some managers now light controlled burns. The change is not a love of fire but an acknowledgement that suppressing a natural process does not abolish it, only delays it and raises its cost. Question: Which of the following is NOT supported by the passage?","options":["Controlled burns have ended all large and destructive fires in pine forests","Small, frequent burns once cleared the floors of dry pine forests","Putting out every fire allowed fuel to build up in the forests","Controlled burns reflect a revised understanding of the role of fire"],"answer":0,"explanation":"The passage never says controlled burns have ended large fires; it only says some managers now light them. The other three statements are directly stated or clearly implied.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-282","question":"Passage: A fishery sets a total catch limit for the season and lets boats fish until it is reached. Each skipper reasons that any fish he leaves will be caught by someone else, so he fishes harder and earlier. The limit is reached in a few weeks, boats sit idle for the rest of the year, and the fish are landed in a glut that depresses prices. A limit that fixes the total but leaves the race open produces speed, not stewardship. Question: The passage suggests that the catch limit alone fails because:","options":["skippers are not told how large the total limit is for the season","it encourages each boat to rush to take a share before the limit is reached","the limit is set at a level that is too high to protect the fish stock","idle boats cause damage to the harbour during the closed season"],"answer":1,"explanation":"The race for a share is the flaw the author identifies: each skipper fishes harder because leaving fish means someone else gets them. The passage does not suggest the limit is too high, unknown to skippers or harmful to harbours.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-283","question":"Passage: Legal documents are written in a dense style that is often defended as precision. But the sentence that is hard for a layperson to read is often hard for lawyers to agree on; long clauses with nested exceptions have produced more disputes than they have prevented. Plain drafting is not a loss of rigour: it forces the writer to decide what he means, and a document whose meaning is clear is the best defence against a dispute. Question: Which of the following best states the author's position?","options":["Lawyers should avoid drafting contracts and leave the task to laypersons","Dense legal language is useful only when a document concerns large sums","Plain drafting need not cost precision and may actually improve it","Disputes arise only from documents that contain nested exceptions"],"answer":2,"explanation":"The author says plain drafting is no loss of rigour and helps avoid disputes. The other options exaggerate or invent claims, such as laypersons doing the drafting or disputes arising only from nested exceptions.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-284","question":"Passage: In the hours after a flood, rumours spread faster than relief. A false claim that a dam is about to burst empties a road of rescue vehicles; a false claim that a camp has food draws hungry crowds to a place with none. Officials often respond by issuing corrections, which travel slowly. Researchers suggest that the better defence is to supply information early and often, so that rumour finds no vacuum to fill. Question: The phrase ‘no vacuum to fill’ suggests that:","options":["officials should avoid answering rumours directly when they appear","relief workers should keep roads empty until the flood has passed","rumours are harmless so long as corrections are issued quickly","rumours tend to spread where people lack reliable information"],"answer":3,"explanation":"A vacuum is an empty space; the author means a gap in reliable information that rumour fills. Hence prompt official information leaves rumour little room.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-285","question":"Passage: Autocorrect has made spelling errors rarer in messages, but it has not made writers better spellers. Because the software repairs a word before the writer notices the mistake, there is no feedback and nothing to learn from. We have, in effect, transferred a skill to a machine and kept only the illusion of competence. Question: The author's main concern is that:","options":["autocorrect often changes words in ways that alter the meaning of messages","people who use autocorrect no longer learn from their own spelling errors","messages are written too quickly for writers to check them properly","modern spelling rules have grown too complicated for most writers"],"answer":1,"explanation":"The author's complaint is the lack of feedback: the machine fixes the error before the writer sees it, so no learning occurs. Altered meanings, writing speed and complex spelling rules are not mentioned.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-286","question":"Passage: Dung beetles roll their balls of dung in straight lines, even on moonless nights, apparently steering by the band of light made by the Milky Way. When researchers fitted tiny cardboard hats over the beetles' eyes, hiding the sky from view, the insects wandered in circles. The experiment shows more than an animal's skill: it shows that a creature with a brain smaller than a grain of rice can use a pattern that human travellers had to study to learn. Question: The researchers fitted the cardboard hats to find out whether:","options":["the beetles could roll dung balls more quickly when their eyes were covered","the beetles depend on the night sky to keep to a straight course","the beetles' brains are smaller than those of other insects of their size","the beetles can find their way better on moonless nights than on bright ones"],"answer":1,"explanation":"Hiding the sky and then seeing the beetles wander in circles tests whether they steer by the sky. The hats do not test speed, brain size or moonlight preference.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-287","question":"Passage: A fragile cave painting may survive for thousands of years in darkness and still air. Open the cave to visitors, and their breath, warmth and humidity begin to dissolve it within decades. The paradox of heritage is that the more people are allowed to appreciate a monument, the faster they destroy what they came to see. Many sites now build replicas and close the original, a solution that satisfies conservation but leaves some visitors feeling cheated. Question: The ‘paradox’ referred to in the passage is that:","options":["monuments last longer in the open air than in closed spaces","admiring a monument can hasten its decay","replicas are more costly to build than the originals were","visitors feel cheated when they are shown a monument at all"],"answer":1,"explanation":"The paradox is that appreciation (visiting) causes the damage that destroys the object of appreciation. The other options misstate or invent claims.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-288","question":"Passage: A firm that extends its working day from eight to ten hours expects a quarter more output. Studies of long hours suggest otherwise: after the first few hours attention falls, errors rise and the extra time yields progressively less. In some tasks the output of a ten-hour day is barely higher than that of an eight-hour day, and the cost of correcting mistakes may exceed the gain. Question: Which of the following would the author most likely agree with?","options":["Workers should not be paid more for working beyond eight hours","Shorter days always raise output in every kind of task and industry","Firms should measure only the hours worked and ignore the quality of the output","Extra hours of work do not bring a proportionate rise in output"],"answer":3,"explanation":"The author argues that additional hours yield less and less, so output does not rise in proportion. The author does not say that shorter days always raise output or comment on overtime pay.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-289","question":"Passage: Courses promising to triple a reader's speed rely on skimming: the eyes pass over a page and capture its gist. Skimming has its uses, but tests show that comprehension of detail falls steadily as speed rises. There is no shortcut that preserves both. A reader who must remember the argument of a chapter will do better by reading it once, carefully, than by racing through it twice. Question: Which of the following, if true, would most weaken the author's claim?","options":["A study in which readers who tripled their speed kept their grasp of detail intact","A report that most readers prefer to skim a text before reading it carefully","A survey showing that few readers finish the chapters that they begin to read","An experiment in which readers who read twice recalled the gist better than once-readers"],"answer":0,"explanation":"The claim is that speed and detailed comprehension cannot both be kept. A study where they are both kept directly contradicts it. The other findings concern preferences, finishing rates, or gist, not detail.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-290","question":"Passage: Cold storage lets a farmer sell apples in spring rather than at the autumn glut, when prices are lowest. But the benefit is not automatic. If every farmer stores, the glut simply moves to spring, and the storage costs, which are real, are borne without the expected premium. A tool that helps one farmer privately may not help all farmers collectively. Question: The main point of the passage is that:","options":["cold storage is too costly for most small farmers to use","apples fetch the highest prices in the weeks after harvest","a measure that benefits one producer may lose its benefit when everyone adopts it","farmers should sell their entire crop in the autumn to avoid risk"],"answer":2,"explanation":"The final sentence generalises the point: what helps one farmer may not help all when all do it. Costs and autumn prices are details, and the author does not recommend selling everything in autumn.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-291","question":"Passage: The committee met to decide whether to hold a meeting about meetings. After a brisk forty minutes it was agreed that the question was too important to be settled hastily and should be referred to a sub-committee, to be constituted at the next meeting, whose date would be circulated in due course. Everyone left feeling that real progress had been made. Question: The tone of the passage is best described as:","options":["appreciative","indignant","ironic","nostalgic"],"answer":2,"explanation":"The author describes a total lack of progress as 'real progress' and a brisk forty minutes as an achievement, which is irony aimed at committee procedure.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-292","question":"Passage: Mr Iyer had retired six years ago, but he still walked past the school every morning, slowing at the gate as though the bell might ring for him. When a young man in a suit stopped and called him ‘sir’, he did not recognise the face; but when the man said, ‘Third bench, window side, always late’, Mr Iyer laughed aloud and then, to his own embarrassment, had to look away at the hedge. Question: Mr Iyer's looking away at the hedge most likely suggests that he was:","options":["annoyed that the young man had stopped him on the road","ashamed of having been unable to recognise the young man","bored by the young man's recollection of his school days","moved but unwilling to let his feeling show"],"answer":3,"explanation":"His laughter, the embarrassment and the turning away together point to a surge of emotion he did not want to display. Annoyance, shame at not recognising and boredom do not fit the warm context.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-293","question":"Passage: The village well had been dry for two summers, yet each morning Rukmini still lowered the bucket on its frayed rope and listened for the splash. The other women had stopped laughing at her; they had begun, instead, to look away. When the new pipe arrived, she was the last to fill her pots from it, and the first to leave without speaking. Question: Rukmini's behaviour after the pipe arrived suggests that:","options":["she felt a loss that the new water supply could not make up","she was angry that the other women had been given a pipe first","she doubted that the pipe would supply water for very long","she had always disliked the other women of the village"],"answer":0,"explanation":"Her devotion to the dry well, and silent departure from the pipe, suggest the pipe ended something she valued beyond the water. The text gives no evidence of anger at others, doubts about the supply or dislike of the women.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-294","question":"Passage: When a school is judged by its pupils' test scores, teachers naturally begin to teach what the test measures. Scores rise. But the test was only ever a sample of what a good education means; once it becomes the target, it ceases to be a reliable sample, for subjects and skills it does not measure are quietly dropped. The measure improves while the thing it was meant to measure may not. Question: Which of the following best illustrates the author's argument?","options":["A school raises its scores by hiring better teachers and reducing class sizes","A hospital rewarded for short waiting lists begins to turn away its complex cases","A company that pays its salesmen commissions finds that its sales are rising","A city that builds more roads discovers that its traffic jams are getting longer"],"answer":1,"explanation":"The illustration must show a measure being targeted until it no longer reflects the real aim: short waiting lists achieved by avoiding hard cases. Hiring better teachers actually improves education, and the other two cases are not about distorting a proxy.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-295","question":"Passage: A phone whose battery can be replaced in minutes may be used for many years; one with a glued battery is discarded when the battery fails. Manufacturers say sealed designs make devices thinner and sturdier. Repair advocates reply that thinness is a strange benefit if the product is thrown away sooner. The disagreement is partly about what we want a device to be: a sleek object to be replaced, or a tool to be maintained. Question: The author's main purpose is to:","options":["persuade readers to avoid buying phones with sealed batteries","explain why manufacturers earn more from sealed phones than from others","show that repair advocates are mistaken about the sturdiness of devices","present two views on how devices should be designed and what they are for"],"answer":3,"explanation":"The author lays out the manufacturers' and advocates' positions and frames the deeper disagreement, without taking sides. The other options assign the author a one-sided purpose that the passage does not display.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-296","question":"Passage: Children raised with two languages sometimes mix them in a single sentence, which parents fear signals confusion. Linguists regard this as evidence of skill: the child chooses from a larger store of words and slips in the one that fits best. Such children also show strength in switching attention between tasks. What looks like a muddle from outside is, from inside, a more flexible system. Question: According to the passage, linguists regard the mixing of two languages in one sentence as:","options":["a temporary confusion that disappears as soon as the child begins school","a sign of weakness in both languages that parents should correct","a habit that harms the child's attention in other tasks","a sign of linguistic skill and not of confusion"],"answer":3,"explanation":"The passage states that linguists see mixing as evidence of skill, drawing on a larger store of words. The other options contradict the passage.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-297","question":"Passage: English has borrowed so freely from other languages that purists who wish to keep it ‘pure’ would have little left to speak. Words such as ‘pyjamas’, ‘jungle’ and ‘shampoo’ arrived with trade and empire and now pass unnoticed. A language that refuses to borrow is not preserved; it is merely poorer, since vocabulary grows by contact as surely as cities grow by trade. Question: As used in the passage, ‘purists’ most nearly means:","options":["those who insist on keeping a language free of foreign elements","those who study the history and origin of the words of a language","those who translate words from one language into another","those who use only simple words in speaking and in writing"],"answer":0,"explanation":"Purists wish to keep English 'pure', i.e. free of borrowed words, as the sentence about having little left to speak confirms. The other meanings are about study, translation or simplicity.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-298","question":"Passage: River dolphins, nearly blind in muddy water, navigate and hunt by sound. A motorboat's engine fills the same channel with noise, masking the clicks by which they locate fish and one another. Unlike a net or a poison, the damage is invisible: no corpses float to the surface, and so no one notices until the population has dwindled. Dangers that leave no body are the easiest to ignore. Question: The last sentence of the passage implies that:","options":["harm that is not visible tends to attract less attention than harm that is","nets and poisons are less dangerous to river dolphins than noise is","motorboats should be banned from every river in which dolphins live","river dolphins are not harmed by noise unless they are nearly blind"],"answer":0,"explanation":"The author contrasts invisible damage (noise) with visible deaths (nets, poison) and notes the former is easily ignored. The author does not compare the relative danger of the causes, call for a ban or limit the harm to blind dolphins.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-299","question":"Passage: The village postman once knew who was away, who was ill and who was waiting for a letter from a son abroad. He carried not only post but also news. Today a courier scans a barcode and leaves a parcel on the step. Delivery is faster and cheaper, but a quiet system of attention, by which someone noticed if an old woman's letters began to pile up, has gone without being replaced. Question: The passage suggests that the postman's role included:","options":["collecting taxes and fees on behalf of the village council","speeding up delivery by sorting the post before it reached him","keeping an informal watch over the welfare of residents","delivering parcels in return for a small fee from the senders"],"answer":2,"explanation":"Noticing an old woman's piled-up letters shows that his rounds also served as a watch on residents' welfare. Taxes, sorting and parcel fees are not mentioned.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-300","question":"Passage: Scientific papers are reviewed by experts before publication, a process that catches errors but takes months. Some researchers now post findings online first and invite comment. Speed helps when results matter urgently, but unreviewed claims may spread, and be cited, before the errors are found. The two systems are best seen not as rivals but as stages, with a fast circulation of ideas followed by a slow checking of them. Question: The author's view of the two systems is that they:","options":["should be abolished in favour of a single, faster method","are equally likely to allow errors to reach the public","are unsuited to research on questions that matter urgently","can work together as successive stages of one process"],"answer":3,"explanation":"The final sentence calls the two systems stages rather than rivals. The author does not call for abolishing either, does not say errors are equally likely in both, and says speed helps when results are urgent.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-301","question":"Passage: An insurance policy that fully reimburses any loss may lead the insured to take less care, since the cost of carelessness no longer falls on him. Insurers therefore insert deductibles, which require the insured to bear a small part of every loss. A deductible is not merely a device to save the insurer money: it keeps a share of the consequences with the person best placed to prevent the loss. Question: The author's explanation of deductibles is best summarised as follows:","options":["They let insurers charge lower premiums to customers who make no claims","They protect insurers against customers who deliberately cause a loss","They preserve the insured person's incentive to guard against loss","They help insurers to detect false claims made by careless customers"],"answer":2,"explanation":"The deductible keeps part of the consequences with the insured, who can best prevent the loss, which preserves the incentive for care. Premium levels, deliberate loss and false claims are not what the passage discusses.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-302","question":"Passage: A bank can be perfectly sound and still fail if depositors believe that it will. Each depositor knows that the bank holds only a fraction of its deposits in cash; if others withdraw, those at the back of the queue lose. The rational response to a rumour is therefore to join the queue, which makes the rumour come true. Panics of this kind are self-fulfilling: the belief creates the fact that was feared. Question: Which of the following can be inferred from the passage?","options":["A bank can fail from depositors' fears even when its finances are healthy","Banks that keep more than a fraction of deposits in cash are certain to fail","Depositors who join a queue always lose the money they have deposited","Rumours about banks are usually false and are spread by rival banks"],"answer":0,"explanation":"The first sentence and the self-fulfilling logic show that belief alone can bring down a sound bank. The passage does not claim that high cash holdings cause failure, that every depositor loses, or that rivals spread rumours.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-303","question":"Passage: A test for a rare disease is 99 per cent accurate. A patient tests positive and is terrified. Yet if only one person in ten thousand has the disease, then among ten thousand people tested about one has it and is correctly detected, while about a hundred healthy people are wrongly flagged. A positive result then means roughly one chance in a hundred and one of being ill. Accuracy without the background frequency tells us less than it seems. Question: According to the passage, a patient with a positive result in this case:","options":["has the disease, because the test is accurate in ninety-nine cases out of a hundred","is equally likely to be ill as to be healthy, since the test can fail either way","should be retested once for every hundred healthy people in the population","is still far more likely to be healthy than to have the disease"],"answer":3,"explanation":"About one true positive stands against about a hundred false positives, so a positive result leaves roughly a 1-in-101 chance of illness. The other options ignore the base rate the passage emphasises.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-304","question":"Passage: Since chess programs surpassed the best human players, grandmasters have not stopped playing; they study the programs' moves and borrow ideas. The surprise is that human play has become not more mechanical but bolder: moves once dismissed as risky are tried because the machine showed that they work. The program has not made the human redundant; it has widened what the human dares to attempt. Question: The author's main point is that chess programs have:","options":["made human players copy machine moves without understanding them","caused grandmasters to retire earlier than they once used to","expanded the range of ideas that human players are willing to try","proved that chess has been solved and need not be studied further"],"answer":2,"explanation":"The closing sentence says the program widened what humans dare to attempt. The passage says human play became bolder, not mechanical, and players have not stopped playing.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-305","question":"Passage: It is often said that earthquakes do not kill people; buildings do. The statement is overdrawn, but it points to something true: two quakes of equal strength can leave very different tolls, depending on construction and the enforcement of building codes. Where codes exist on paper but inspectors can be bribed, the toll follows corruption as much as tectonics. Disasters called natural are often shaped by human decisions. Question: It can be inferred that the author regards the statement ‘buildings kill’ as:","options":["a complete and accurate account of why earthquakes kill","an exaggeration that nevertheless contains an important truth","a falsehood spread by those who wish to blame the inspectors","a statement of no value to those who plan for disasters"],"answer":1,"explanation":"The author calls it 'overdrawn' yet says it 'points to something true', i.e. an exaggeration with a real insight. The other options are either too approving or too dismissive.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-306","question":"Passage: A court interpreter is expected to be invisible, rendering each word as spoken. But some utterances resist word-for-word rendering: a witness who says ‘he was not exactly honest’ may mean a mild reproach or an accusation of fraud, depending on tone and culture. An interpreter who flattens this nuance may mislead the court; one who adds an explanation may overstep. The post demands both fidelity and judgment, and the two sometimes pull apart. Question: The passage suggests that the interpreter's difficulty is that:","options":["strict fidelity to the words may fail to convey the speaker's real force","witnesses often speak too quickly for the interpreter to follow every word","courts never allow an interpreter to ask a witness what was really meant","interpreters rarely understand the cultural background of the witnesses"],"answer":0,"explanation":"The interpreter must be faithful to the words yet conveying what the speaker meant needs judgment; the two can conflict. Speed, court rules and cultural ignorance are not mentioned.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-307","question":"Passage: People who rely on navigation apps tend to remember routes less well than those who study a paper map. The app speaks of turns, not of places, so the traveller sees the road without forming a picture of the area. The map, by contrast, shows relationships: that the market lies beyond the river, that the station is north of the school. A route is a line; a map is a mind's picture. Question: The last sentence suggests that a paper map:","options":["is always more accurate than a navigation app on a long journey","costs less than an app and is easier to carry on a journey","shows how places are related, not merely how to reach one","should be studied only after the traveller has used a navigation app"],"answer":2,"explanation":"A map shows relationships among places, giving a mental picture, while a route is only a line from A to B. Accuracy, cost and the order of use are not discussed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-308","question":"Passage: It is commonly argued that anonymity makes people cruel online, since they cannot be identified. Yet some forums that require real names are no gentler. What seems to matter more is the audience: people are harsher when they speak to a crowd of strangers whom they expect to cheer them on than when they speak to a small group whom they will meet again. Civility is nurtured less by identification than by continuing relationships. Question: Which of the following would the author most likely agree with?","options":["Anonymous forums are always crueller than forums in which real names appear","Demanding real names will not, on its own, make a forum more courteous","Large crowds are the only audiences before which people behave cruelly","Online groups whose members know each other are never harsh with one another"],"answer":1,"explanation":"The author argues that identification does not by itself bring civility, since name-requiring forums are no gentler. 'Always crueller', 'only' and 'never harsh' are absolute claims that the passage does not make.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-309","question":"Passage: A village of ten families has an average annual income of ₹90,000. Then a single family strikes it rich, and the average rises to ₹150,000 though nine families' incomes have not moved. The average has risen because of the outlier, and describes no actual household. For such skewed distributions, the median, the middle value, tells a truer story. Question: The author prefers the median to the mean in this case because:","options":["the median is easier to calculate for a village of only ten families","the median is always lower than the mean in every set of incomes","nine of the ten families will be better off if the median is used","one extreme income drags the mean above what a typical family earns"],"answer":3,"explanation":"One outlier inflates the mean so that it describes no real family, while the median stays near the typical household. Ease of calculation and 'always lower' are not the reasons given.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-310","question":"Passage: Shoppers offered twenty varieties of jam stop at the stall more often than those offered six, but those offered six buy more. Too many options seem to attract and yet to paralyse: each choice made means many alternatives forgone, and the buyer fears regret. Sellers who believe that more variety always means more sales may be mistaking the interest of browsers for the intentions of buyers. Question: Which of the following is supported by the passage?","options":["A large range of options draws attention but may lower actual purchases","Shoppers who are offered six varieties of jam never regret what they buy","Sellers should stock only six varieties of every product they sell","Buyers who stop at a stall always intend to buy something from it"],"answer":0,"explanation":"The data show more stopping but fewer purchases with twenty varieties. 'Never regret', 'only six of every product' and 'always intend' are extensions that the passage does not support.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-311","question":"Passage: The minimalist guru urges us to own only a hundred things, and makes a handsome living doing so. His books, videos and weekend retreats, sold at premium prices, are rarely mentioned in his sermons on simplicity. It is hard to resist the thought that nothing is as lucrative as telling people that they need less. Question: The author's tone is best described as:","options":["reverently admiring","wryly sceptical","coldly neutral","bitterly angry"],"answer":1,"explanation":"The wit in the last sentence and the point about unmentioned premium products show a gently mocking doubt about the guru's sincerity, not reverence, neutrality or bitterness.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-312","question":"Passage: The conductor never looked at passengers' faces, only at their hands: the coin held ready, the note folded small, the pass drawn from a sleeve. By the second stop he knew who would argue about change. He had once told a trainee that a man's hands cannot lie, and the trainee had written it down as though it were a rule, which is how a clever remark becomes a bad habit. Question: The final clause of the passage suggests that the narrator believes:","options":["trainees rarely remember what experienced conductors tell them","passengers' hands are a less reliable guide than their faces","the conductor's skill came from long years of watching faces","a shrewd observation hardened into a rule may lead one astray"],"answer":3,"explanation":"The narrator says writing the remark down as a rule turned a clever remark into a bad habit, i.e. fixed rules from sharp observations can mislead. The passage does not say trainees forget, nor compare hands with faces.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-313","question":"Passage: Her mother called every evening at seven, and every evening the conversation followed the same script: had she eaten, was the landlord behaving, did the cough persist. For months Anjali answered quickly, her eyes on her laptop. It was only when the call failed to come one evening that she noticed how carefully she had memorised the script, and how little she knew what to say without it. Question: Anjali's realisation at the end of the passage is that:","options":["she depended on the routine of the calls more than she had admitted","her mother had begun to lose interest in her daily life","she should have ended the calls long before they had grown dull","the landlord had been neglecting his duties for several months"],"answer":0,"explanation":"Noticing how well she knew the script and how lost she was without it shows that the calls mattered to her more than her hurried answers suggested. The other options have no support in the text.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-314","question":"Passage: The first rain did not fall so much as arrive. It crept up the street as a smell of wet dust, and then the roofs began to murmur, one after another, like a congregation finding its voice. Children ran out with their arms wide; the old men stayed on the verandah, pretending not to smile. Question: The phrase ‘like a congregation finding its voice’ compares the roofs to:","options":["a crowd that grows angry as its numbers increase","a group of children who suddenly run out to play","a body of people that begins to sing in unison","a gathering of elders that waits in silence for news"],"answer":2,"explanation":"A congregation finding its voice is a group beginning to sing or chant together, the way the roofs start to sound one after another. Anger, running children and silent elders belong to other images in the passage.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-315","question":"Passage: Barbara's colleagues thought her stubborn for pursuing a theory that most of the field had abandoned. She did not argue; she simply kept collecting data, year after year, and kept it in an order that others could check. When her results were finally published they were not accepted at once; they were examined, and the examination took longer than the discovery. What persuaded the field was not her confidence but her records. Question: According to the passage, what finally persuaded the field?","options":["Her long and patient defence of the theory at conferences","The careful, checkable data that she had gathered over the years","The decision of her colleagues to abandon their own theories","The speed with which her results were published and accepted"],"answer":1,"explanation":"The last sentence says it was her records, not her confidence, that persuaded the field. She did not argue, and the results were not accepted at once.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-316","question":"Passage: Cheap air tickets are celebrated as democratising travel. But their price excludes costs borne by others: the emissions, the noise, the pressure on fragile destinations. The ticket is cheap because someone else, often someone who never boards a plane, is paying part of the bill. To call this accessibility is to confuse a low price with a low cost. Question: The author's argument depends on the assumption that:","options":["people who never travel by plane should be given free tickets","airlines would lose money if they charged the full cost of flights","all passengers on cheap flights are indifferent to the emissions","some costs of air travel are not included in the ticket price"],"answer":3,"explanation":"The argument that a low price is not a low cost requires that some costs are left out of the price. The other statements are not needed for the argument to hold.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-317","question":"Passage: Governments often assume that people will save enough for old age if given the opportunity. Experience suggests otherwise: most people postpone saving, aware that they should start but never quite starting. Schemes that enrol employees automatically and let them opt out raise savings dramatically, though no one is compelled. The lesson is not that people are foolish but that inertia is powerful and can be put to good use. Question: According to the passage, automatic enrolment works because:","options":["most people tend to stay with whatever is set as the default","employees are compelled by law to remain in the scheme once enrolled","employees understand pensions better than governments assume","most people are unable to calculate how much they need to save"],"answer":0,"explanation":"Inertia keeps people in the default arrangement even though they may opt out. The scheme is not compulsory, and the passage does not mention understanding or calculation.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-318","question":"Passage: Many people think of trade as a contest in which one country's gain must be another's loss. Yet if each country produces what it makes at relatively low cost and buys the rest, both can end up with more than if each tried to make everything. The mistake lies in imagining a fixed pie to be divided, when trade is one of the ways in which the pie grows. Question: The ‘mistake’ referred to in the passage is:","options":["believing that every country can profit equally from trade","assuming that countries should make nothing for themselves","thinking that low-cost producers cannot buy from other countries","assuming that the total to be shared between countries is fixed"],"answer":3,"explanation":"The 'fixed pie' image identifies the mistake: treating the total gain as fixed so that one side's gain must be the other's loss. The other options are not what the author calls a mistake.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-319","question":"Passage: A farm that grows only one high-yielding variety of rice earns more in a good year than one that grows several. But the single variety shares a single weakness: a new pest, or an unexpected drought, can ruin the whole crop together. Diversity looks wasteful in a good year, like an insurance premium unclaimed, and is justified only in the bad one. Question: The comparison with an insurance premium suggests that crop diversity:","options":["is a cost that farmers should avoid unless the government pays for it","earns higher profits in a good year than a single variety does","costs a little in good years but shields against ruin in bad years","is useful only against pests and has no value in a drought year"],"answer":2,"explanation":"A premium is a cost paid in ordinary times for protection in bad times, which matches the author's view of diversity. Higher profit in good years is the opposite of what the passage says.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-320","question":"Passage: Many languages build respect into their grammar: a speaker must choose between a formal and an informal ‘you’ before saying anything at all. English speakers sometimes find this stifling. Yet such systems spare the speaker a different burden: the guesswork of tone. In a language with a mandatory formal form, no one wonders whether first-name terms are too familiar; the grammar has decided. Question: The author suggests that separate formal and informal forms of ‘you’:","options":["make conversation between strangers impossible in those languages","are used by speakers who wish to sound more polite than they feel","should be introduced into English to make speech more respectful","relieve speakers of the need to judge how familiar to be"],"answer":3,"explanation":"The grammar has decided the question of familiarity, so speakers are spared the guesswork. The author does not say conversation is impossible, that speakers insincerely over-polite, or that English should adopt the system.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-321","question":"Passage: Dictionaries do not decide what words mean; they report what speakers use them to mean. When a word such as ‘literally’ acquires a second sense, the lexicographer records it, to the dismay of purists. This is not abdication but method: a dictionary that refused to describe usage would soon describe only a language that no one speaks. Question: The author's view of lexicographers is that they:","options":["should record usage as it is and not as purists wish it to be","are responsible for deciding which new senses of words are correct","ought to resist the spread of new meanings in everyday speech","are careless in accepting every word that speakers invent"],"answer":0,"explanation":"The author calls the recording of changing usage method, not abdication, and warns that refusing to do so would produce a dictionary of an unspoken language. The other options attribute to lexicographers roles the author rejects.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-322","question":"Passage: On very hot days tempers shorten and errors rise. Experiments show that people in hot rooms do worse on tasks that need sustained attention, and some studies link heat waves with increases in violent crime. These findings should not be pressed too far, for crime also depends on how many people are out of doors, and hot evenings drive more people into the streets. Still, the connection between climate and conduct deserves a place in city planning. Question: The author cautions against pressing the findings too far because:","options":["the experiments were carried out only on tasks needing sustained attention","violent crime has been rising in cities even when no heat wave occurs","more people being outdoors in the heat may itself explain a rise in crime","city planners already take climate into account in planning their streets"],"answer":2,"explanation":"The author notes that hot evenings put more people in the streets, which could raise crime without heat altering anyone's temper. The other statements are not the author's reasons.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-323","question":"Passage: When a city renames its streets, residents keep using the old names for decades, long after the signs have changed. The old names are not mere habit: they carry the shared memory of the neighbourhood, who lived where and what shop stood at which corner. A new name, however well chosen, starts without that history. Question: The passage suggests that residents continue to use the old street names because:","options":["they refuse to accept the authority of the city that changed the names","the new names are harder to remember than the names that they replaced","the old names hold the community's shared memories of the neighbourhood","the signs bearing the new names are often missing from the streets"],"answer":2,"explanation":"The passage says the old names carry the neighbourhood's shared memory, which the new names lack. Defiance, difficulty of the new names and missing signs are not mentioned.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-324","question":"Passage: After an event, we find it easy to see how obvious the signs were. A bank collapses, and commentators trace the warnings that, it seems, everyone should have noticed. This is hindsight bias: knowing the outcome, we cannot easily recover the uncertainty of those who did not know it. It is a quiet injustice, since those who judged the signs when they were scattered among a thousand other signals are blamed for failing to read them as clearly as we now do. Question: The main point of the passage is that:","options":["banks collapse mainly because their managers choose to ignore clear warnings of danger","commentators should be barred from discussing events after they happen","judging past decisions in light of the outcome is unfair to those who made them","the signs of danger are always hidden among a great many other signals around them"],"answer":2,"explanation":"The author calls hindsight judgment a quiet injustice to those who decided without knowing the outcome. The passage does not say managers ignore clear warnings or that commentary should be barred, and 'always' overstates the case.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-325","question":"Passage: Drip irrigation can halve a farmer's water use, yet where electricity for pumps is free, farmers have little reason to adopt it: saving water saves them nothing. Policy-makers who subsidise the equipment and also supply free power are paying twice for opposite ends. The pricing of water and power, not the technology, is the real lever. Question: The author's argument implies that:","options":["the adoption of water-saving technology depends on prices that reward saving","drip irrigation does not in fact reduce the amount of water that farmers use","subsidies on equipment should be raised until every farmer has adopted it","free electricity should be given only to farmers who have drip systems"],"answer":0,"explanation":"If free power removes any gain from saving water, then prices that reward saving are what drive adoption. The passage affirms that drip irrigation halves water use and criticises, rather than recommends, bigger subsidies.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-326","question":"Passage: Large factories can make shirts more cheaply than small tailors because their fixed costs are spread over many units. It does not follow that small producers are doomed. Where customers value fit, speed or personal service, a small producer sells something the factory cannot: attention. The danger for the small firm lies not in competing on price, where it must lose, but in forgetting that it never needed to compete there. Question: The author's advice to small producers is best summarised as:","options":["compete on what a factory cannot offer instead of on price","merge with other small firms to spread their fixed costs","copy the factory's methods as closely as their budgets allow","lower their prices below those of the factory to win customers"],"answer":0,"explanation":"The author says small firms sell attention and should not compete on price, where they must lose. Merging, copying and undercutting are not suggested.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-327","question":"Passage: Cameras installed in a car park reduce theft there, and are often credited with the fall in crime in the area. Yet a count of thefts in the neighbouring streets shows a rise. The thieves, it seems, did not reform; they moved. A measure that shifts a problem from one place to another may look successful from the spot where it is applied and be a failure when seen over the whole area. Question: Which of the following conclusions is best supported by the passage?","options":["Cameras are of no use to the police in the detection of any crime","Thieves are always deterred from stealing when cameras are present","The area's crime has fallen because the thieves have begun to reform","The cameras' success may be local and may not reduce theft overall"],"answer":3,"explanation":"Theft fell in the car park but rose nearby, so the benefit may be only local. 'No use' and 'always deterred' overstate, and the author explicitly denies that the thieves reformed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-328","question":"Passage: People who have done something virtuous, such as donating to charity, sometimes feel entitled to behave less well afterwards. Experiments find that those who had just recalled a generous act were more willing to cheat on a later task. The effect is small and not universal, but it troubles the common assumption that good deeds build good habits. Virtue, for some, seems to be a balance to be spent and not a trait to be strengthened. Question: The passage challenges the assumption that:","options":["small donations to charity are worth less than large ones","experiments can reveal how people behave when they cheat","doing good makes a person likelier to go on doing good","people who cheat are unaware that they are cheating"],"answer":2,"explanation":"The effect troubles the idea that good deeds build good habits. The other options are not what the passage questions.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-329","question":"Passage: A student who has memorised the rule for dividing fractions can solve a page of sums quickly. Ask her why the rule works and she may be silent. Procedural fluency and conceptual understanding are different possessions: the first can be acquired by drill, the second only by reasoning about why. A course that rewards only the first produces students who are fast and fragile, for a changed question breaks them. Question: The word ‘fragile’ in the passage suggests that such students:","options":["solve sums slowly because they stop to think about each step","dislike mathematics and avoid questions about fractions","become confident enough to teach the rule to others","fail when a problem is presented in an unfamiliar form"],"answer":3,"explanation":"The author says a changed question breaks them: without understanding, they cannot cope when a familiar procedure no longer fits. They are called fast, not slow.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-330","question":"Passage: To encourage households to save water, some utilities charge a low rate for the first block of usage and progressively higher rates for further blocks. Households using a modest amount, which includes most poor families, pay little; heavy users, mostly wealthy households with gardens and pools, pay more per litre. The structure conserves water and protects the poor in a single stroke, provided that large poor families, who cross the first block through sheer numbers, are not penalised. Question: The proviso at the end of the passage is meant to ensure that:","options":["large poor households are not charged unfairly for water they need","wealthy households do not escape the higher rates by using less water","the first block of usage is made small enough to discourage waste","utilities do not lose money on households that use modest amounts"],"answer":0,"explanation":"Large poor families may exceed the first block simply because they have many members; the proviso protects them from being treated like wasteful users. The other options misread the point.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-331","question":"Passage: In some riverside towns, painted lines on old walls record the height of past floods, with dates beside them. Newcomers find them quaint. The old residents treat them as instructions: they tell a family where not to build and how high to keep the grain. When the lines are painted over during renovation, the town loses nothing visible, but it loses a memory that was serving as a warning. Question: The author implies that painting over the marks:","options":["improves the appearance of the town without any other result","shows that the town has stopped being at risk from floods","helps newcomers to settle in without being frightened","removes a source of useful warning for future residents"],"answer":3,"explanation":"The marks are a memory that works as a warning, so erasing them removes it. The town 'loses nothing visible', but the loss is real; the other options contradict this.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-332","question":"Passage: A folk tale told in a hundred villages is told in a hundred ways. Scholars once sought the original version and treated variants as corruptions. Today most regard the search as misguided: the tale exists only in its tellings, and each variant records what a community found worth emphasising. An ‘original’ would be simply the oldest recorded version, and the oldest recorded is not the same as the first. Question: The author's view is that the search for an original folk tale is:","options":["necessary if scholars are to explain how the tale first arose","misguided because the tale exists only in its many tellings","useful mainly in showing which variants have been corrupted","impossible because all the early versions were lost in fires"],"answer":1,"explanation":"The tale exists only in its tellings, and the oldest recorded is not the first, so the search is misguided. Fires and corruption are not part of the author's argument.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-333","question":"Passage: Farmers have long swapped seeds with neighbours, selecting and saving the best. Laws that restrict saving or exchanging seeds from patented varieties protect the breeder's investment, but they also interrupt this informal system of selection that had conserved variety. Defenders of the laws say breeders must recover their costs. The difficulty is that the laws treat seeds as a finished product, when for farmers they are also a continuing process. Question: The author's criticism of the laws is that they:","options":["fail to protect the investment that the breeders have made","allow neighbours to exchange seeds without paying for them","reduce the cost of seed so far that breeders stop making new varieties","ignore that seed saving is an ongoing process of selection"],"answer":3,"explanation":"The author's difficulty is that the laws see seeds as a finished product while for farmers they form an ongoing process. The author concedes that the laws protect breeders' investment.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-334","question":"Passage: Open-plan offices were meant to encourage conversation. Studies of such offices find that face-to-face interaction in fact falls: workers, aware of being overheard and overlooked, put on headphones and send messages instead. What was designed as a space for talk has become a room full of quiet people typing to one another. A building shapes behaviour, but seldom in the direction its designers intended. Question: The passage points out the irony that:","options":["an office designed to encourage talk led workers to talk less","workers who wear headphones produce more than those who do not","messages sent by workers are rarely read by their colleagues","designers of offices seldom consult the workers who use them"],"answer":0,"explanation":"The irony is the reversal: a space meant to raise conversation lowered it. Productivity, message reading and designer consultation are not discussed.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-335","question":"Passage: A researcher's worth is often judged by how many times her papers are cited. But citations record attention, not truth: a flawed paper that is widely criticised is cited as often as a sound one that is widely used. When promotion depends on counts, researchers have an incentive to produce provocative claims, and to cite their friends. A measure meant to reward quality may then reward noise. Question: Which of the following is the author's main criticism of citation counts?","options":["They are too hard to calculate for researchers who publish rarely","They overlook the papers that are read but not cited by anyone","They reward researchers who are old rather than those who are young","They may reward the seeking of attention rather than reliable work"],"answer":3,"explanation":"The author says counts measure attention, and that promotion based on them may reward provocative claims and 'noise'. Calculation, unread papers and age are not mentioned.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-336","question":"Passage: Each wave of labour-saving machinery has brought predictions of permanent unemployment. Those predictions have been wrong in the aggregate: demand rose, new trades emerged and employment recovered. But ‘in the aggregate’ conceals the weaver whose skill became worthless in a year; the new jobs were in other towns, requiring other skills. A society can grow richer while particular people grow poorer, and honesty requires us to say both. Question: The author's attitude to the predictions of permanent unemployment is that they:","options":["were wholly correct in their account of the effect of machines","were mistaken overall but ignored real hardship to individuals","were mistaken because new machines always create jobs in the same towns","were useful because they led governments to protect the weavers"],"answer":1,"explanation":"The predictions failed in the aggregate yet the author insists on the hardship of the weaver; the author does not say they were wholly correct, nor that jobs appeared in the same towns, nor that governments protected the weavers.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-337","question":"Passage: At the border post, Hamid translated between officers and travellers, though he was employed by neither. He had learned early that his task was not to render words but to soften them: a curt order became a request, a terse refusal an apology. The officers thought him unusually efficient; the travellers thought him kind; and Hamid, who was both, wondered at times whether he was anything at all. Question: The last clause of the passage suggests that Hamid felt:","options":["proud that both the officers and the travellers valued his work","angry that neither group employed him as a translator","that his role as a go-between left him without an identity of his own","that his softening of the words made him dishonest in his work"],"answer":2,"explanation":"Being efficient for one side and kind for the other, he wonders whether he is 'anything at all', i.e. whether his role has swallowed his own identity. Pride and anger are not what the clause expresses, and dishonesty is not raised.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-338","question":"Passage: A university has been in existence for two hundred years, though no student, teacher or building from its first decade survives. What, then, is the university? Not its bricks, nor its people, nor even its curriculum, which has changed beyond recognition. It is a continuity of purpose and practice, handed on like a language; and like a language, it can be lost without any single moment at which it dies. Question: According to the passage, the identity of the university lies in:","options":["a continuing tradition of purpose and practice","the buildings that were raised in its first decade","the curriculum that has been followed by its students","the teachers who have remained for the longest time"],"answer":0,"explanation":"The author rules out bricks, people and curriculum and names continuity of purpose and practice. Each of the other options is explicitly rejected.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-339","question":"Passage: The old engineer preferred repair to replacement, a habit his juniors found quaint. ‘A new part,’ he said, ‘hides the fault; a repair makes you understand it.’ His workshop was slow and his bills modest, but machines that left it seldom returned. The firm's accountants valued speed, and in the end the workshop closed, though the accounts did not record what was lost: the faults that were understood. Question: The phrase ‘the accounts did not record what was lost’ suggests that:","options":["the workshop had been run without any accounts at all","the engineer was paid too little for the work he did","the juniors had not learned to repair machines properly","the value of the workshop's work was not captured by the firm's measures"],"answer":3,"explanation":"The firm's accounts measured speed and cost, not understanding of faults, so the workshop's true value never appeared in them. The text does not say that no accounts existed or comment on pay or the juniors' training.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-340","question":"Passage: The letter of rejection was courteous, which made it worse. It thanked him for his interest, praised his ‘evident enthusiasm’ and wished him success elsewhere, in the manner of a doctor wishing a patient a speedy recovery from an illness he had not got. He read it twice, folded it neatly and put it in the drawer, where, he reflected, it would join its colleagues. Question: The tone of the passage is best described as:","options":["bitterly vengeful","wryly resigned","joyfully relieved","coldly indifferent"],"answer":1,"explanation":"The humorous comparison and the quip about the letter joining 'its colleagues' show a rueful acceptance of repeated rejection, i.e. wry resignation. He is neither vengeful, relieved nor indifferent.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-341","question":"Passage: Artificial light at night draws moths away from their feeding and mating, and disorients hatchling turtles, which head for the brightest horizon expecting the sea. Light, which we regard as pure benefit, is for such species a cue they evolved to trust. The harm lies not in the light's brightness alone but in its being out of its natural place: a signal that once meant ‘this way is the sea’ now means nothing, or something false. Question: The author's point about the turtles is that:","options":["hatchling turtles are attracted to bright light because they are naturally blind","turtles should be moved to beaches that have no street lighting","an artificial signal can mislead animals that evolved to rely on a natural one","turtles can easily learn to ignore artificial light after a few nights"],"answer":2,"explanation":"Turtles trust the bright horizon as a sign of the sea; artificial light sends a false signal. The passage does not say turtles are blind, recommends no relocation, or that they learn to ignore the light.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-342","question":"Passage: Place the fruit at eye level in a canteen and the cake out of sight, and people eat more fruit. No choice has been removed; cake remains for anyone who asks. Defenders call this a nudge, a gentle push that preserves freedom. Critics reply that all arrangement shapes behaviour, so the real question is not whether to nudge but who sets the direction. A canteen manager who pushes cake is nudging too; the nudge was always there. Question: The critics' argument rests on the idea that:","options":["every way of arranging choices influences what people choose","canteens should not offer cake to people who want to eat fruit","people are never aware when they are being nudged by others","managers should remove any food that is bad for health"],"answer":0,"explanation":"If every arrangement shapes behaviour, then not nudging is impossible and the only issue is direction. The critics do not call for removing foods, nor claim that people are unaware.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-343","question":"Passage: Nothing in science is proved beyond all revision, and the public sometimes takes this admission as weakness. It is the opposite. A claim that could not be overturned by any evidence would not be knowledge but dogma. What distinguishes science is not certainty but a standing invitation to be shown wrong, and a record of correcting itself when that happens. Question: The author's attitude to the revisability of scientific claims is that it is:","options":["a weakness that scientists should try to conceal from the public","a sign that scientific claims cannot be trusted in practice","a flaw that will disappear as more evidence is collected","a strength and not a defect of the scientific method"],"answer":3,"explanation":"The author says the admission of revisability is the opposite of weakness, since unrevisable claims would be dogma. The other options regard it as a defect.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-344","question":"Passage: We tend to assume that writing preserves knowledge better than memory does. Yet oral performers of long epics, trained from childhood, recited tens of thousands of lines with a stability that surprises literate observers. Their memory was supported by metre, formula and repetition; they were not recalling a text but rebuilding a song. Writing preserves exact words, but a living tradition preserves something else: the ability to produce the song again. Question: According to the passage, oral performers kept their epics alive through:","options":["written copies that were kept in secret by the performers","exact memorisation of each word in a fixed written text","metre, formula and repetition that helped them rebuild the song","the support of literate observers who corrected their errors"],"answer":2,"explanation":"The passage says the performers were not recalling a text but rebuilding a song, aided by metre, formula and repetition. Written copies and exact word memorisation are what the passage denies.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-345","question":"Passage: Firms like to hire specialists because their value is easy to see: a tax expert saves tax. The value of a generalist is harder to measure, as it consists of seeing connections the specialists miss and of noticing when a problem has been put to the wrong expert. In stable times specialists suffice; in changing ones the organisation that has no one who sees across boundaries finds its experts answering questions nobody should be asking. Question: The author suggests that generalists are most valuable when:","options":["firms are choosing among several specialists for a single job","firms need to save as much tax as they possibly can","specialists are unavailable because of changes in the labour market","conditions are changing and problems cross the boundaries of specialisms"],"answer":3,"explanation":"The passage says specialists suffice in stable times, while in changing times someone who sees across boundaries is needed. Tax saving and a shortage of specialists are not the reasons given.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-346","question":"Passage: In music, silence is not an absence but a part of the design: a pause before a climax, a rest that lets a phrase breathe. A beginner fills every gap, afraid that silence will be read as a mistake. A master lets the gap stand, trusting that listeners will supply the expectation; and the expectation, once supplied, makes the next note matter more. Question: Which statement best expresses the central idea of the passage?","options":["Silence can be used as a deliberate element of musical design","Beginners should avoid long pauses until they have mastered rhythm","Listeners dislike music in which the silent passages are long","Masters of music compose pieces that contain no sound at all"],"answer":0,"explanation":"The passage calls silence part of the design and shows the master using it to heighten the next note. The other options contradict or exaggerate the passage.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-347","question":"Passage: In a negotiation, the first number named tends to pull the final settlement towards it, even when both sides know it is arbitrary. A seller who opens with a high price ends higher than one who opens lower. The remedy is not to ignore the first offer, which is almost impossible, but to prepare an independent estimate beforehand, so that one has a figure of one's own to set against it. Question: According to the passage, a negotiator can best resist the pull of the first number by:","options":["refusing to listen to the first offer that the other side makes","naming the first number himself, whatever it may happen to be","agreeing quickly to any offer that is close to the original price","forming an independent estimate before the bargaining begins"],"answer":3,"explanation":"The passage says ignoring the first offer is almost impossible and recommends preparing one's own estimate beforehand. Refusing to listen, opening first or accepting quickly are not advised.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-348","question":"Passage: In a well-known experiment, researchers left wallets containing various sums of money in several cities and noted how many were returned. To the surprise of many, wallets containing more money were returned more often. The explanation offered was that keeping a larger sum made the finders feel more like thieves, and the self-image of an honest person weighed more heavily than the cash. People are honest not only for fear of punishment but for the sake of being who they think they are. Question: The passage implies that finders returned wallets with more money mainly because:","options":["they were afraid that the owners of larger sums would pursue them","they hoped for a larger reward from the owners of such wallets","keeping a large sum conflicted more strongly with their image of themselves","they had less need of money than the finders of the smaller wallets"],"answer":2,"explanation":"The explanation offered is that keeping more money made finders feel more like thieves, a threat to their self-image. Fear of pursuit, reward and need are not mentioned.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-349","question":"Passage: When two countries fix their border along a river, they often forget that rivers move. A river that shifts its course by a few hundred metres hands a field from one village to another without any treaty. Some border agreements anticipate this, specifying whether the boundary follows the old channel or the new; others leave it to be disputed. The lesson is that a line drawn on a living landscape needs rules for change. Question: The main point of the passage is that:","options":["rivers should never be used as boundaries between two countries","villages near a river change hands more often than other villages","treaties about borders are hardly ever respected by the two countries","borders drawn along rivers need rules for the river's changes"],"answer":3,"explanation":"The last sentence states the lesson: a boundary on a changing landscape needs rules for change. The author does not condemn river borders or comment on respect for treaties.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-350","question":"Passage: People habitually underestimate how long a task will take, even when they know that similar tasks took longer in the past. The error persists because we plan by imagining the smooth path from start to finish and forget the interruptions that fill real life. A better method is to ask how long such tasks have taken others, and to treat one's own case as ordinary. Question: The author recommends estimating time by:","options":["looking at how long comparable tasks have actually taken","imagining each step of the work in the greatest possible detail","adding a fixed margin of one hour to every estimate made","assuming that one's own case is better than the average"],"answer":0,"explanation":"The better method is to use the record of similar tasks and treat one's case as ordinary. Detailed imagining is the faulty method described, and the other options are not advised.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-351","question":"Passage: Grain stored in a village godown loses a large share to rats and damp, far more than the farmers can afford to lose. A tempting remedy is to offer a reward for every rat killed. But rat-killing treats a symptom; the rats thrive because the godown has cracks and open sacks. Until the building is repaired, the reward will only produce a steady supply of dead rats and a steady loss of grain. Question: The author's argument is that:","options":["rewards for killing rats are never effective in any storage building","the godown should be abandoned in favour of storage in private homes","the cause of the loss must be tackled and not just its visible symptom","farmers must accept a loss of grain as an unavoidable part of storage"],"answer":2,"explanation":"The author says rat-killing treats a symptom while the cracks and open sacks are the cause. 'Never effective' overstates, and abandoning the godown or accepting the loss is not proposed.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-352","question":"Passage: Courts demand proof beyond reasonable doubt in criminal cases, and a lower standard, a balance of probabilities, in civil ones. The difference reflects the stakes: wrongly convicting a person costs liberty, while wrongly deciding a civil dispute costs money. A system that applied the lower standard to both would convict more guilty people but also more innocent ones. The higher standard is a deliberate choice to prefer one kind of error to the other. Question: According to the passage, the higher standard in criminal cases is a choice to:","options":["make criminal trials faster than civil trials in the same court","punish guilty people more severely than civil wrongdoers","accept that some guilty people may go free rather than convict the innocent","protect the courts from any error in the decisions they give"],"answer":2,"explanation":"Preferring one kind of error means tolerating acquittals of some guilty people to avoid convicting innocents. The standard does not remove all error, and speed and severity are not discussed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-353","question":"Passage: In a famous optical illusion, two lines of equal length look unequal because of the arrowheads at their ends. Even after we have measured them, we continue to see them as different. This shows that perception is not a camera's record but a judgment made by the brain, and that such a judgment cannot be overruled by our knowledge. Seeing, in this sense, is not believing; it is interpreting. Question: The author's point about the illusion is that:","options":["the arrowheads at the ends make one line physically longer than the other","the brain's interpretation persists even when we know that it is mistaken","measuring instruments are less reliable than the human eye in such cases","people can learn to see the lines as equal after a few trials"],"answer":1,"explanation":"We still see unequal lines after measuring them, showing that perception is a judgment that knowledge cannot overrule. The lines are equal in fact, and nothing is said about instruments or learning.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-354","question":"Passage: Technology for reviewing umpires' decisions has made cricket fairer on the whole, but it has also moved the argument elsewhere. Players no longer dispute the decision; they dispute the margin of the technology, whether a ball clipped the stumps by two centimetres or by three. The machine has not ended the argument, only altered its subject, from the umpire's eye to the machine's tolerance. Question: The passage suggests that review technology has:","options":["changed what players dispute without ending the disputes","made umpires unnecessary for most decisions in cricket","made the game less fair than it was before the technology","settled all disputes about whether a ball hit the stumps"],"answer":0,"explanation":"The passage says the argument has been moved and its subject altered, not ended. It also says the game is fairer on the whole, and umpires remain in the story.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-355","question":"Passage: Jurors find a confident eyewitness persuasive, yet research shows that confidence and accuracy are only weakly related. Memory is reconstructed each time it is recalled, and may absorb details from questions asked, photographs seen or accounts heard. A witness may sincerely recall a face that was never there. Courts that treat confidence as a guide to truth therefore risk convicting on the strength of conviction alone. Question: Which of the following can be inferred from the passage?","options":["Eyewitnesses who are unsure of their memories are usually accurate","Jurors are generally unable to follow research on memory","A witness who is very sure of his memory may nonetheless be wrong","Photographs shown to a witness always improve the accuracy of his memory"],"answer":2,"explanation":"Confidence is only weakly linked to accuracy, and a witness may sincerely recall what never happened, so a very sure witness may be wrong. The passage says nothing to support the other options.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-356","question":"Passage: Hebrew was revived as a spoken language after centuries as a language of prayer. Efforts to revive other languages have been less successful, and the difference has usually lain not in the quality of dictionaries but in whether children grew up speaking the language at home. A language kept alive by classes and ceremonies is preserved; a language kept alive by children quarrelling in it is alive. Question: The author regards the use of a language by children at home as:","options":["a hindrance to the use of the language in formal ceremonies","the real test of whether a language is truly alive","a result of the publication of good dictionaries","a less important factor than the number of classes taught"],"answer":1,"explanation":"The contrast between preserving a language and a language alive in children's quarrels makes home use by children the real test of life. The author discounts dictionaries and classes.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-357","question":"Passage: A settlement is counted as a town if its population crosses a threshold and most of its workers are outside farming. A large village whose workers are nonetheless in agriculture remains a village on paper, with a village council, though it may have streets, shops and traffic. The consequence is that such places are denied the services meant for towns. The statistics are tidy; the people living in the gap are not. Question: The author is mainly concerned with showing that:","options":["agriculture should not be practised by the people living in large villages","the population thresholds for towns have been set far too high","towns have grown more quickly than villages in recent decades","official categories can leave some large settlements without suitable services"],"answer":3,"explanation":"The author describes a gap between tidy categories and real settlements that are denied town services. The thresholds themselves and the growth of towns are not the focus.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-358","question":"Passage: When we look at a star ten thousand light-years away, we see light that left it ten thousand years ago. The star may have changed or even vanished since. Looking far, in astronomy, is therefore looking back: the farther the telescope reaches, the older the picture it receives. We cannot see the universe as it is, only as it was, which is the nearest thing to time travel that observers have. Question: The statement ‘looking far is looking back’ means that:","options":["telescopes must be turned backwards to observe very distant stars","distant stars are older than the stars that are close to Earth","light from distant objects shows them as they were in the past","astronomers must wait ten thousand years for each observation"],"answer":2,"explanation":"Light takes time to arrive, so a distant object is seen as it was when the light left it. The passage does not claim that distant stars are older, that telescopes face backwards, or that observers must wait.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-359","question":"Passage: Making bus travel free is often proposed as a way to cut traffic. But if most new riders are people who would otherwise have walked or cycled, then traffic falls little while the cost to the city is large. Free fares may still be justified as a help to the poor, but that is a social argument and not a traffic one. A policy should be defended on the ground on which it actually works. Question: The author's main point is that free bus fares:","options":["are unfair to people who already travel by car and pay their own costs","may not reduce traffic and need a different kind of justification","should be introduced only in cities where there is no traffic","are an effective way of helping the poor and the environment alike"],"answer":1,"explanation":"If new riders come from walking or cycling, traffic hardly falls; the author says the policy must be defended on social grounds. Fairness to drivers and effects on the environment are not discussed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-360","question":"Passage: Explanations of rising obesity often blame individual weakness. Yet the rise has occurred across entire populations within a few decades, too rapidly for human character to have changed. What did change was the environment: cheaper calories, bigger portions, less need to walk. A tide that lifts every boat is not explained by the quality of the boats. Question: The final sentence suggests that:","options":["changes affecting whole populations must have causes beyond individual traits","people with strong characters never gain weight in a changing environment","boats are a poor comparison for the study of the health of people","the quality of an individual's character has no bearing on his health"],"answer":0,"explanation":"A tide lifting every boat cannot be due to differences between the boats; likewise a population-wide rise needs a population-wide cause. The other options are absolute claims the author does not make.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-361","question":"Passage: Bats are widely feared, yet many tropical fruit trees depend on them to pollinate flowers that open at night and to carry seeds over long distances. Where bats are driven out for fear of disease, the trees reproduce less. Fear that leads people to destroy a species may thus damage the forests and orchards on which people themselves depend. Question: Which of the following is the author's main conclusion?","options":["Bats carry diseases that are dangerous to the people who live near them","Tropical fruit trees are the only plants that depend on bats to reproduce","Fear-driven destruction of bats can harm the plants that people rely on","Orchards should be planted far away from the forests where bats live"],"answer":2,"explanation":"The last sentence states the conclusion: destroying bats out of fear may harm the forests and orchards that people depend on. The author does not endorse the disease claim, say 'only', or recommend planting orchards far from bats.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-362","question":"Passage: My grandfather's watch lost four minutes every week, and every Sunday he set it right, with a little ceremony of winding and adjusting. When we offered him one that kept perfect time, he thanked us and put it in a drawer. It was years before I understood that he did not want a watch that told the time; he wanted a small appointment with the time itself. Question: According to the narrator, the grandfather kept the old watch because:","options":["he could not afford to buy another watch for himself","he did not trust gifts that were given to him by his family","tending it was a ritual that he valued more than accuracy","he believed that the new watch was less accurate than the old"],"answer":2,"explanation":"The narrator concludes that he wanted a small appointment with time, i.e. the weekly ritual mattered more than accuracy. The other options are not suggested.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-363","question":"Passage: The invigilator walked the aisles with his hands behind his back, and nobody dared meet his eye. Sunil, who knew every answer, found that his hand shook so much that his writing looked like someone else's. He glanced at the clock, then at the paper, and understood that knowing and showing are different things, and that the examination measured the second. Question: Sunil's reflection at the end shows that he realised that:","options":["the invigilator was deliberately trying to frighten the candidates","he had not prepared well enough for the examination that day","an examination tests what a candidate can show and not merely what he knows","the clock was running faster than it did in the other rooms"],"answer":2,"explanation":"'Knowing and showing are different things, and the examination measured the second' says exactly this. Sunil did know the answers, and there is no suggestion of deliberate intimidation or a fast clock.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-364","question":"Passage: Successful people often explain their success by hard work, and hard work matters. But those who succeed also tend to have been born at the right time, in the right place, to parents who could pay for school. To say so is not to deny effort; it is to notice that effort is rewarded unequally. A society that mistakes luck for merit will neglect those whom luck has passed by. Question: The author's main argument is that:","options":["hard work is of little value to those who wish to succeed in life","successful people should give up part of their income to the poor","success results from effort together with circumstances beyond one's control","parents who pay for school fees are the main cause of success in life"],"answer":2,"explanation":"The passage grants the role of hard work and adds the role of luck and circumstances. It does not belittle effort, call for redistribution, or credit parents alone.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-365","question":"Passage: The play ran for three hours, though its ideas, to be generous, would have filled twenty minutes. The cast delivered their lines with the resolve of people who have been told there is no exit. The set, a single staircase leading nowhere, was the evening's most honest piece of symbolism, and the one with which the audience most readily identified. Question: The reviewer's tone is best described as:","options":["sarcastic and mocking","generous and encouraging","puzzled but respectful","detached and analytical"],"answer":0,"explanation":"The jibes at the length, the cast's 'resolve' and the staircase leading nowhere with which the audience identified are mockery. 'To be generous' is itself ironic.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-366","question":"Passage: The senator's reply, delivered with great firmness, committed him to nothing. Asked whether he would support the bill, he spoke of the importance of balance, the need for dialogue and his respect for all sides. Journalists left with a quotation for every possible outcome, none of which he could be accused of having denied. Question: Which word best describes the senator's reply?","options":["blunt","candid","evasive","hostile"],"answer":2,"explanation":"He avoided a direct answer while sounding firm, leaving room for every outcome, which is evasive. Blunt and candid mean the opposite, and hostility is not shown.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-367","question":"Passage: Canal irrigation brought water to dry land and raised yields for decades. But the water carried small quantities of salt, which remained in the soil as the water evaporated. Year after year the salt accumulated, and in poorly drained fields it now whitens the surface and stunts the crops. The same canal that created the prosperity is eroding it, and the harm is slow enough to go unnoticed until it is severe. Question: The passage suggests that the build-up of salt is dangerous because:","options":["canals cannot be repaired once salt has entered the water","salt makes the water too heavy for the canal to carry","its gradual effect is likely to be noticed only when the damage is serious","farmers refuse to use canal water in the dry season of the year"],"answer":2,"explanation":"The last sentence says the harm is slow enough to go unnoticed until severe. Nothing is said about canal repair, water weight or farmers' refusal.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-368","question":"Passage: In a competitive classroom, one pupil's success is another's failure, and the clever learn to guard their notes. In a cooperative one, pupils are rewarded for the group's performance, and explain things to each other. Studies suggest that those who explain learn as much as those who listen, so the clever lose nothing. The fear that cooperation holds back the best pupils is not borne out. Question: The studies mentioned in the passage support the claim that:","options":["competition is the best way to bring out the talent of clever pupils","pupils who are weak benefit only when they are taught by teachers","bright pupils learn from explaining things to others in the group","cooperative groups produce results that are better than those of competitive ones"],"answer":2,"explanation":"Explainers learn as much as listeners, so clever pupils lose nothing by helping others. The passage does not claim that cooperation yields better results overall.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-369","question":"Passage: When fuel prices rise, people drive less, but not much less in the short run: they must still reach work and school. Over several years, however, they buy more efficient vehicles, move closer to work or shift to public transport. The response to a price rise is therefore small at first and large later. A tax judged by its first-year effect will seem a failure; judged over a decade, it may not. Question: The passage implies that a fuel tax should be judged:","options":["over a long period, because people adjust to it slowly","by its first-year effect, which is the most reliable guide","only by the amount of money that it brings to the government","by how many people shift to public transport in the first year"],"answer":0,"explanation":"The response is small at first and larger later, so a short-run judgment would mislead. The other options rely on the first-year effect or on revenue, which the author does not recommend.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-370","question":"Passage: Satellite images can show a farmer which part of his field is short of water, and by how much. The technology exists, and the images are often free. What is missing is a way of delivering the information in a language the farmer uses, at the hour he needs it, on a phone he can afford. Many an advance fails not in the laboratory but on the last mile to the user. Question: The author's point is that:","options":["satellite images are of little value in the farming of dry fields","the usefulness of a technology depends on how it reaches its users","farmers should be taught to build and to launch their own satellites","laboratories should stop their work on projects of this kind"],"answer":1,"explanation":"The 'last mile' remark means that technology fails if delivery to the user is poor. The author does not dismiss satellite images or the laboratories' work.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-371","question":"Passage: A festival fills the town's streets, and the sweet-seller, flower-vendor and rickshaw-puller earn more in a week than in a month. Economists count this as a boost to the local economy. The festival's value, however, does not lie in what it adds to incomes; the townspeople would not accept the same cash in place of the festival. The rupee value measures what can be counted, not what is cherished. Question: The last sentence of the passage suggests that:","options":["festivals should be organised only in towns that need extra income","the economists' figures about festivals are almost always incorrect","traders profit from festivals more than the townspeople ever realise","the money measure of a festival leaves out much of its worth to the people"],"answer":3,"explanation":"What is cherished is not what can be counted, so the rupee measure leaves out much of the festival's worth. The author does not say the figures are wrong, only that they are incomplete.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-372","question":"Passage: Parents are advised to read aloud to young children, and the advice is sound. But the benefit seems to lie less in the book than in the exchange: a child who is asked what will happen next, or why a character is afraid, acquires words and ideas. A parent who reads in a hurry, without pause, gives the child a story but not the conversation. The book is the occasion; the talk is the education. Question: According to the author, the greatest benefit of reading aloud comes from:","options":["the number of books that the child is able to hear in a year","the choice of difficult books that stretch the child's attention","the speed at which the parent reads each page of the story","talking with the child about the story while reading it"],"answer":3,"explanation":"'The book is the occasion; the talk is the education.' A hurried reading with no pauses gives the story without the conversation. Number of books, difficulty and speed are not what the author values.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-373","question":"Passage: A magazine invited readers to post their opinion on whether the city needed a new flyover, and eighty per cent voted yes. The editor reported that the city wanted a flyover. But the respondents were readers who chose to reply, most of them drivers; those who walk, cycle or take the bus did not read the magazine. A large sample can still be a poor sample if it is selected by the very opinion it measures. Question: The author's main criticism of the magazine's survey is that:","options":["its respondents selected themselves and did not represent the whole city","the number of respondents was too small to give any useful result","the readers were asked a question that they could not understand","the editor failed to report the figures that the survey had produced"],"answer":0,"explanation":"Self-selecting, mostly driver respondents do not represent the city; the author says even a large sample can be poor. The size of the sample is not the complaint.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-374","question":"Passage: Happy people are healthier on average, and it is tempting to conclude that happiness protects health. It may be so, but the reverse is equally plausible: healthy people find it easier to be happy. Or both may stem from something else, such as secure income and good friends. Without an experiment that changes one factor while holding the others fixed, the correlation does not tell us which story is true. Question: According to the passage, to establish that happiness protects health one would need:","options":["a larger survey of the happiness and health of more people","an agreement among doctors that happiness protects health","a study of people who have very secure incomes and good friends","an experiment that changes happiness while holding other factors fixed"],"answer":3,"explanation":"The passage says only an experiment that changes one factor and holds the rest fixed can separate the explanations. A larger survey would still give only correlation.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"eng-reading-comprehension-375","question":"Passage: Where examinations decide a child's future, childhood itself is reorganised around them. Evenings go to coaching, holidays to revision, and games to the idle hour that may not exist. Nobody planned it; each family does what it fears it must, given what others are doing. The result is a race in which all run faster and no one arrives earlier, since the number of places has not changed. Question: The passage implies that the extra effort of every family:","options":["gives no family a lasting advantage when all do the same","raises the number of places that are available in colleges","has been planned by educators who wish to test the children","gives an advantage to families who begin coaching earlier than others"],"answer":0,"explanation":"If all run faster and the number of places is fixed, relative positions do not change. The passage says nobody planned it and says nothing about earlier coaching or more places.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
